def html_anuncio_global():
    """Modal pantalla grande: anuncio de Procsis con fotos. X cierra y recuerda en localStorage."""
    try:
        p = plataforma()
    except Exception:
        return ""
    if not getattr(p, "anuncio_activo", False):
        return ""
    titulo = _esc(getattr(p, "anuncio_titulo", None) or "Aviso importante")
    cuerpo_raw = getattr(p, "anuncio_cuerpo", None) or ""
    cuerpo = cuerpo_raw.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\n", "<br>")
    cuenta = _esc(getattr(p, "anuncio_cuenta", None) or "")
    ver = str(getattr(p, "anuncio_version", None) or "1").replace('"', "").replace("'", "")
    imgs = []
    for attr in ("anuncio_img1", "anuncio_img2"):
        path = (getattr(p, attr, None) or "").strip()
        if path:
            imgs.append(path)
    imgs_html = ""
    if imgs:
        parts = []
        for src_img in imgs:
            parts.append(
                '<img src="' + src_img + '" alt="Anuncio" style="width:100%;max-height:220px;object-fit:cover;'
                'border-radius:12px;margin:10px 0 0;display:block;background:#e2e8f0">'
            )
        imgs_html = '<div style="margin-top:8px">' + "".join(parts) + "</div>"
    cuenta_html = ""
    if cuenta:
        cuenta_html = (
            '<div style="margin-top:16px;padding:14px 16px;background:#ecfdf5;border:1px solid #86efac;border-radius:12px;text-align:left">'
            '<div style="font-size:12px;font-weight:800;color:#065f46;margin-bottom:4px">DATOS PARA DONACIÓN / APOYO</div>'
            '<div style="font-size:15px;font-weight:700;color:#14532d">' + cuenta + "</div></div>"
        )
    return (
        '<div id="anuncio-global" style="display:none;position:fixed;inset:0;z-index:100000;background:rgba(15,23,42,.72);'
        "backdrop-filter:blur(4px);align-items:center;justify-content:center;padding:20px;font-family:Segoe UI,Arial,sans-serif\">"
        '<div style="position:relative;max-width:600px;width:100%;background:#fff;border-radius:18px;'
        'box-shadow:0 25px 60px rgba(0,0,0,.35);overflow:hidden;max-height:92vh;overflow-y:auto">'
        '<button type="button" id="anuncio-cerrar" aria-label="Cerrar" style="position:absolute;top:12px;right:12px;'
        "width:36px;height:36px;border:0;border-radius:50%;background:#f1f5f9;color:#0f172a;font-size:22px;"
        'font-weight:800;cursor:pointer;line-height:36px;z-index:2">×</button>'
        '<div style="background:linear-gradient(135deg,#0B2D57,#1e40af);color:#fff;padding:22px 28px 18px;padding-right:48px">'
        '<div style="font-size:11px;letter-spacing:1px;opacity:.85">PROCSIS · AVISO INSTITUCIONAL</div>'
        '<h2 style="margin:8px 0 0;font-size:20px;line-height:1.3">' + titulo + "</h2></div>"
        '<div style="padding:18px 28px 26px;color:#334155;font-size:14px;line-height:1.55">'
        + imgs_html
        + '<div style="margin-top:12px">' + cuerpo + "</div>" + cuenta_html
        + '<p style="margin:16px 0 0;font-size:12px;color:#94a3b8">Cierre con la X. Se mostrará de nuevo si publicamos una nueva versión del anuncio.</p>'
        "</div></div></div>"
        '<script>(function(){var ver="' + ver + '";var key="edutrack_anuncio_dismiss_"+ver;'
        'try{if(localStorage.getItem(key)==="1")return;}catch(e){}'
        'var el=document.getElementById("anuncio-global");if(!el)return;el.style.display="flex";'
        "var btn=document.getElementById(\"anuncio-cerrar\");"
        'if(btn)btn.onclick=function(){el.style.display="none";try{localStorage.setItem(key,"1");}catch(e){}};'
        "})();</script>"
    )



def css_tema_global():
    """Fuente y colores globales configurados desde soporte."""
    try:
        p = plataforma()
    except Exception:
        return ""
    fuente = (getattr(p, "tema_fuente", None) or "Segoe UI").replace('"', "").replace("<", "")
    # Paleta corporativa unificada
    if (getattr(p, "tema_color_fondo", None) or "").lower() in ("#eef2ff", "#eaf2ff", "#eef6fc", "#e8eef5"):
        try:
            p.tema_color_fondo = "#f1f5f9"
            if not getattr(p, "tema_color_primario", None):
                p.tema_color_primario = "#0B2D57"
            if not getattr(p, "tema_color_acento", None):
                p.tema_color_acento = "#1e3a8a"
            db.session.commit()
        except Exception:
            pass
    prim = (getattr(p, "tema_color_primario", None) or "#0B2D57").replace('"', "") or "#0B2D57"
    acento = (getattr(p, "tema_color_acento", None) or "#1e3a8a").replace('"', "") or "#1e3a8a"
    fondo = "#f1f5f9"  # fondo corporativo unificado
    return (
        '<style id="tema-global">'
        ':root{--azul:' + prim + ';--azul2:' + acento + ';--fondo-app:#f1f5f9;--negro:#0f172a;--gris:#f1f5f9;--borde:#e2e8f0;}'+'body{background:#f1f5f9!important;color:#0f172a}'+'.shell,.main-wrap,.content{background:#f1f5f9}'+'.role-panel,.table-card,.card{background:#fff;border:1px solid #e2e8f0;box-shadow:0 4px 14px rgba(15,23,42,.05)}'+'.topbar,.app-header,header.bar{background:linear-gradient(90deg,#0B2D57,#0f172a)!important}'+'button,.btn{background:#0B2D57;border-radius:10px}'+'button:hover,.btn:hover{background:#1e3a8a}'
        'body,.shell,.login-shell,input,button,select,textarea{'
        'font-family:' + fuente + ',Segoe UI,Arial,sans-serif!important}'
        'body{background:var(--fondo-app,' + fondo + ')}'
        '</style>'
    )



def page(title, body):
    cookie_banner = """
<div id="cookie-banner" style="display:none;position:fixed;bottom:0;left:0;right:0;z-index:99999;font-family:Segoe UI,Arial,sans-serif">
  <div style="max-width:920px;margin:0 auto 16px;background:#fff;border-radius:16px;box-shadow:0 12px 40px rgba(0,0,0,.2);padding:22px 24px;border:1px solid #e5e7eb">
    <h2 style="margin:0 0 10px;font-size:22px;color:#16a34a;font-weight:800">Usamos cookies para mejorar tu experiencia</h2>
    <p style="margin:0 0 16px;font-size:14px;line-height:1.55;color:#334155">
      En este portal utilizamos datos de navegación / cookies propias y técnicas para gestionar el acceso seguro,
      mantener tu sesión, elaborar información estadística básica de uso del sistema y optimizar la funcionalidad del sitio.
      <b>No usamos cookies de publicidad de terceros.</b>
      Si continúa navegando o acepta, autoriza esta utilización.
      Puede conocer más en
      <a href="/cookies" style="color:#15803d;font-weight:700">política completa de cookies</a>
      y
      <a href="/tratamiento-datos" style="color:#15803d;font-weight:700">política de tratamiento de datos personales</a>.
    </p>
    <div id="cookie-config-panel" style="display:none;background:#f0fdf4;border:1px solid #bbf7d0;border-radius:12px;padding:12px;margin-bottom:14px;font-size:13px;color:#166534">
      <label style="display:flex;gap:8px;align-items:center;margin:6px 0"><input type="checkbox" checked disabled> Cookies esenciales (sesión / seguridad) — siempre activas</label>
      <label style="display:flex;gap:8px;align-items:center;margin:6px 0"><input type="checkbox" id="ck-pref" checked> Preferencias de interfaz</label>
      <label style="display:flex;gap:8px;align-items:center;margin:6px 0"><input type="checkbox" id="ck-stat"> Estadística anónima de uso</label>
      <button type="button" id="cookie-save-cfg" style="margin-top:8px;background:#15803d;color:#fff;border:0;border-radius:8px;padding:8px 14px;font-weight:700;cursor:pointer">Guardar preferencias</button>
    </div>
    <div style="display:flex;flex-wrap:wrap;gap:10px;justify-content:center">
      <button type="button" id="cookie-accept-all" style="background:#16a34a;color:#fff;border:0;border-radius:999px;padding:12px 22px;font-weight:800;cursor:pointer;font-size:14px">Aceptar todas las cookies</button>
      <button type="button" id="cookie-reject" style="background:#fff;color:#166534;border:2px solid #16a34a;border-radius:999px;padding:10px 20px;font-weight:700;cursor:pointer;font-size:14px">Rechazar cookies no esenciales</button>
      <button type="button" id="cookie-config" style="background:#fff;color:#166534;border:2px solid #16a34a;border-radius:999px;padding:10px 20px;font-weight:700;cursor:pointer;font-size:14px">Configurar cookies</button>
    </div>
  </div>
</div>
<script>
(function(){
  try {
    var KEY = 'edutrack_cookies_pref';
    if (!localStorage.getItem(KEY)) {
      var b = document.getElementById('cookie-banner');
      if (b) b.style.display = 'block';
    }
    function save(pref) {
      localStorage.setItem(KEY, JSON.stringify(pref));
      localStorage.setItem('edutrack_cookies_ok', '1');
      var b = document.getElementById('cookie-banner');
      if (b) b.style.display = 'none';
    }
    var a = document.getElementById('cookie-accept-all');
    if (a) a.onclick = function(){ save({essential:true, pref:true, stat:true, all:true}); };
    var r = document.getElementById('cookie-reject');
    if (r) r.onclick = function(){ save({essential:true, pref:false, stat:false, all:false}); };
    var c = document.getElementById('cookie-config');
    if (c) c.onclick = function(){
      var p = document.getElementById('cookie-config-panel');
      if (p) p.style.display = p.style.display === 'none' ? 'block' : 'none';
    };
    var s = document.getElementById('cookie-save-cfg');
    if (s) s.onclick = function(){
      var pref = document.getElementById('ck-pref');
      var st = document.getElementById('ck-stat');
      save({essential:true, pref: !!(pref && pref.checked), stat: !!(st && st.checked), all:false});
    };
  } catch(e) {}
})();
</script>
"""
    _bfcache_fix = """
<script>
// Corrige el botón "atrás": si el navegador restaura esta página desde su caché
// (bfcache) en vez de pedirla de nuevo al servidor, puede mostrar una vista de
// OTRO portal/rol (ej. Gerencia viendo una página vieja de Soporte). Forzamos
// una recarga real contra el servidor cuando eso pasa.
window.addEventListener('pageshow', function (event) {
  if (event.persisted || (window.performance && performance.getEntriesByType &&
      performance.getEntriesByType('navigation')[0] &&
      performance.getEntriesByType('navigation')[0].type === 'back_forward')) {
    window.location.reload();
  }
});
</script>"""
