        ("auditoria", "navegador", "ALTER TABLE auditoria ADD COLUMN navegador VARCHAR(120) DEFAULT ''"),
        ("auditoria", "sistema_os", "ALTER TABLE auditoria ADD COLUMN sistema_os VARCHAR(120) DEFAULT ''"),
