def _txt_a_html_lista(texto):
    """Convierte texto con viñetas o párrafos a HTML simple."""
    if not texto:
        return ""
    partes = []
    for bloque in texto.replace("\r\n", "\n").split("\n\n"):
        bloque = bloque.strip()
        if not bloque:
            continue
        lineas = [ln.strip() for ln in bloque.split("\n") if ln.strip()]
        if all(ln.startswith(("•", "-", "*")) for ln in lineas):
            items = "".join(f"<li>{ln.lstrip('•-* ').strip()}</li>" for ln in lineas)
            partes.append(f"<ul>{items}</ul>")
        elif len(lineas) > 1 and any(ln.startswith(("•", "-", "*")) for ln in lineas):
            buf = []
            for ln in lineas:
                if ln.startswith(("•", "-", "*")):
                    buf.append(f"<li>{ln.lstrip('•-* ').strip()}</li>")
                else:
                    if buf:
                        partes.append(f"<ul>{''.join(buf)}</ul>"); buf = []
                    partes.append(f"<p>{ln}</p>")
            if buf:
                partes.append(f"<ul>{''.join(buf)}</ul>")
        else:
            partes.append("<p>" + "<br>".join(lineas) + "</p>")
    return "".join(partes)


