def flag_activo(clave, inst_id=None):
    """¿Está activo un feature flag para el tenant (o global)?"""
    try:
        iid = inst_id if inst_id is not None else institucion_id_actual()
        q = FeatureFlag.query.filter_by(clave=clave, activo=True)
        # Prioridad: flag del tenant, luego global
        if iid:
            f = q.filter_by(institucion_id=iid).first()
            if f:
                return True
        f = FeatureFlag.query.filter_by(clave=clave, activo=True, institucion_id=None).first()
        return bool(f)
    except Exception:
        return False



def guardar_foto_estudiante(file_storage, estudiante_id, institucion_id=None):
    """
    Guarda foto de estudiante optimizada: máx 200x200 px, JPEG ~40 KB.
    Ruta: /static/uploads/fotos_estudiantes/est_{id}.jpg
    Cuenta en el medidor global de almacenamiento (disco real).
    """
    if not file_storage or not getattr(file_storage, "filename", ""):
        return None
    nombre = (file_storage.filename or "").lower()
    if not any(nombre.endswith(ext) for ext in (".jpg", ".jpeg", ".png", ".webp", ".gif", ".bmp")):
        # permitir sin extensión si content-type imagen
        ct = (getattr(file_storage, "content_type", None) or "").lower()
        if "image" not in ct:
            return None
    folder = os.path.join(app.root_path, "static", "uploads", "fotos_estudiantes")
    os.makedirs(folder, exist_ok=True)
    fname = f"est_{int(estudiante_id)}.jpg"
    dest = os.path.join(folder, fname)
    try:
        from PIL import Image
        from io import BytesIO
        raw = file_storage.read()
        if not raw:
            return None
        im = Image.open(BytesIO(raw))
        if im.mode in ("RGBA", "P", "LA"):
            background = Image.new("RGB", im.size, (255, 255, 255))
            if im.mode == "P":
                im = im.convert("RGBA")
            background.paste(im, mask=im.split()[-1] if im.mode in ("RGBA", "LA") else None)
            im = background
        elif im.mode != "RGB":
            im = im.convert("RGB")
        # Cuadrado centrado + 200x200
        w, h = im.size
        side = min(w, h)
        left = (w - side) // 2
        top = (h - side) // 2
        im = im.crop((left, top, left + side, top + side))
        im = im.resize((200, 200), Image.Resampling.LANCZOS)
        # Calidad adaptativa para ~40 KB
        quality = 82
        buf = BytesIO()
        im.save(buf, "JPEG", quality=quality, optimize=True)
        data = buf.getvalue()
        if len(data) > 55 * 1024:
            buf = BytesIO()
            im.save(buf, "JPEG", quality=65, optimize=True)
            data = buf.getvalue()
        with open(dest, "wb") as f:
            f.write(data)
        return f"/static/uploads/fotos_estudiantes/{fname}"
    except Exception as ex:
        print("guardar_foto_estudiante error:", ex)
        try:
            file_storage.seek(0)
            file_storage.save(dest)
            return f"/static/uploads/fotos_estudiantes/{fname}"
        except Exception:
            return None


def _comprimir_imagen_bytes(raw, max_side=200, max_kb=50):
    """Comprime bytes de imagen (biometría, evidencias)."""
    try:
        from PIL import Image
        from io import BytesIO
        im = Image.open(BytesIO(raw))
        if im.mode in ("RGBA", "P", "LA"):
            bg = Image.new("RGB", im.size, (255, 255, 255))
            if im.mode == "P":
                im = im.convert("RGBA")
            bg.paste(im, mask=im.split()[-1] if im.mode in ("RGBA", "LA") else None)
            im = bg
        elif im.mode != "RGB":
            im = im.convert("RGB")
        im.thumbnail((max_side, max_side), Image.Resampling.LANCZOS)
        q = 80
        buf = BytesIO()
        im.save(buf, "JPEG", quality=q, optimize=True)
        data = buf.getvalue()
        if len(data) > max_kb * 1024:
            buf = BytesIO()
            im.save(buf, "JPEG", quality=60, optimize=True)
            data = buf.getvalue()
        return data
    except Exception:
        return raw


def guardar_logo_institucional(file_storage, institucion_id=None):
    """Guarda logo subido (png/jpg/webp) y devuelve ruta web /static/uploads/logos/..."""
    if not file_storage or not getattr(file_storage, "filename", ""):
        return None
    nombre = file_storage.filename or ""
    ext = os.path.splitext(nombre)[1].lower()
    if ext not in [".png", ".jpg", ".jpeg", ".webp", ".gif"]:
        return None
    seguro = f"logo_{institucion_id or 'inst'}_{fecha_hoy().replace('-', '')}_{random.randint(1000,9999)}{ext}"
    dest = os.path.join(LOGO_DIR, seguro)
    file_storage.save(dest)
    return "/" + dest.replace("\\", "/")


