ROLES_INTERNOS = ("Soporte", "Superadmin", "Administrador", "Gerente", "Comercial", "Cobranza")
# Cuota de almacenamiento por colegio (GB)
ALMACENAMIENTO_GB_POR_COLEGIO = 10
