def _reto_vigente(ch):
    if not ch or ch.estado != "pendiente":
        return False
    try:
        from datetime import datetime
        now = ahora()
        if hasattr(now, "strftime") and ch.expira:
            # compare string YYYY-MM-DD HH:MM:SS
            return now.strftime("%Y-%m-%d %H:%M:%S") <= ch.expira
    except Exception:
        return True
    return True



