def requiere_confirmacion_sensible():
    """True si la ruta actual implica acción sensible (export/delete/permisos)."""
    path = (request.path or "").lower()
    method = (request.method or "").upper()
    if method in ("POST", "DELETE", "PUT"):
        for k in ACCIONES_SENSIBLES:
            if k in path:
                return True
        # form flags
        if request.form.get("accion_sensible") or request.form.get("confirmar_sensible"):
            return True
    return False



def login_usuario(usuario, password, rol_requerido=None, institucion_id=None):
    """Busca usuario. Si hay institucion_id, prioriza el de ese colegio (y Soporte global)."""
    usuario = (usuario or "").strip()
    password = (password or "").strip()
    if not usuario or not password:
        return None

    candidatos = Usuario.query.filter(func.lower(Usuario.usuario) == usuario.lower()).all()
    if not candidatos:
        return None

    u = None
    if institucion_id is not None:
        try:
            iid = int(institucion_id)
        except (TypeError, ValueError):
            iid = None
        if iid is not None:
            # 1) Usuario del colegio elegido
            for c in candidatos:
                if c.institucion_id is not None and int(c.institucion_id) == iid:
                    u = c
                    break
            pass
    else:
        # Priorizar cuenta interna (Soporte/Admin) si hay varias con el mismo nombre
        u = None
        for c in candidatos:
            if (c.rol or "").strip() in ROLES_INTERNOS:
                u = c
                break
        if u is None:
            u = candidatos[0]

    if u is None:
        return None
    if not verificar_password(u.password, password):
        return None
    if institucion_id is not None:
        rol_u = (u.rol or "").strip()
        if rol_u in ROLES_INTERNOS or rol_u == "Soporte":
            return None
    if rol_requerido and u.rol.lower().strip() != rol_requerido.lower().strip():
        return None
    if not es_hash_password(u.password):
        u.password = crear_hash(password)
        db.session.commit()
    return u



def es_gerente_pqr():
    u = (session.get("usuario") or "").strip().lower()
    return u in GERENTES_PQR or u in ("soporte", "gerente", "admin")


def registrar_historial_pqr(ticket_id, accion, detalle="", estado_nuevo=""):
    db.session.add(HistorialPQR(
        ticket_id=ticket_id,
        fecha=fecha_hoy(),
        hora=hora_actual(),
        usuario=session.get("usuario") or "Sistema",
        accion=accion,
        detalle=detalle or "",
        estado_nuevo=estado_nuevo or "",
    ))




def _asegurar_token_pqr(t):
    """Genera (una sola vez) un token seguro para el link público de notificación,
    para no exponer el radicado interno en la URL que recibe el cliente."""
    if not (t.token_notificacion or "").strip():
        import secrets
        t.token_notificacion = secrets.token_urlsafe(24)
        db.session.commit()
    return t.token_notificacion



def _fecha_limite_pqr_habiles(fecha_inicio=None, dias_habiles=15):
    """Suma N días hábiles (lun–vie) desde fecha_inicio (YYYY-MM-DD).
    Aproxima el plazo de respuesta del CPACA / Ley 1755 (sin festivos locales)."""
    from datetime import datetime as _dt, timedelta as _td
    try:
        base = _dt.strptime((fecha_inicio or fecha_hoy())[:10], "%Y-%m-%d")
    except Exception:
        base = _dt.utcnow()
    agregados = 0
    cur = base
    while agregados < int(dias_habiles):
        cur = cur + _td(days=1)
        if cur.weekday() < 5:  # 0=lun … 4=vie
            agregados += 1
    return cur.strftime("%Y-%m-%d")



def _cargar_hero_pqr():
    """Devuelve (bytes, mime_subtype, filename) de la foto hero PROCSIS, o (None, None, None)."""
    candidates = []
    base = os.path.dirname(os.path.abspath(__file__))
    for name in (
        "pqr-respuesta-hero.png",
        "pqr-respuesta-hero.jpg",
        "pqr-respuesta-hero.jpeg",
        "pqr-respuesta-hero.png.jpeg",
        "pqr-respuesta-hero.PNG",
        "pqr-respuesta-hero.JPG",
    ):
        candidates.append(os.path.join(base, "static", "img", name))
        candidates.append(os.path.join("static", "img", name))
    for p in candidates:
        try:
            if not (p and os.path.isfile(p) and os.path.getsize(p) > 500):
                continue
            with open(p, "rb") as fh:
                raw = fh.read()
            # magic bytes
            if raw[:3] == b"\xff\xd8\xff":
                return raw, "jpeg", "pqr-respuesta-hero.jpg"
            if raw[:8] == b"\x89PNG\r\n\x1a\n":
                return raw, "png", "pqr-respuesta-hero.png"
            # fallback por extensión
            ext = os.path.splitext(p)[1].lower()
            if "jpg" in ext or "jpeg" in ext:
                return raw, "jpeg", "pqr-respuesta-hero.jpg"
            return raw, "png", "pqr-respuesta-hero.png"
        except Exception as e:
            print("hero load skip", p, e)
    return None, None, None


def _nombre_destinatario_pqr(t):
    """Nombre para saludar en correos/landing: razón social del ticket o usuario en sesión."""
    nom = (getattr(t, "razon_social", None) or "").strip()
    if nom:
        return nom
    try:
        if session.get("nombre_completo"):
            return str(session.get("nombre_completo")).strip()
        if session.get("usuario"):
            return str(session.get("usuario")).strip()
    except Exception:
        pass
    return "Usuario"


def enviar_notificacion_pqr_estilo_tigo(destino, t):
    """Correo de notificación con el mismo patrón que usan las telcos (Tigo, Claro,
    etc.): un aviso corto con botón 'Ver respuesta' que lleva a una página del propio
    sistema donde el cliente ve los datos de su PQR y descarga el PDF — en vez de
    mandar el PDF pesado directo por correo."""
    if not destino:
        return False
    correo_envio, password = _credenciales_smtp("notificaciones")
    resend_key = (os.environ.get("RESEND_API_KEY") or "").strip()
    # Railway Hobby: solo RESEND_API_KEY. Plan Pro: Gmail SMTP también sirve.
    if not resend_key and (not correo_envio or not password):
        print("PQR notificación: falta RESEND_API_KEY (Hobby) o SOPORTE_EMAIL/PASSWORD (Pro)")
        return False
    from_addr = (
        (os.environ.get("RESEND_FROM") or "").strip()
        or correo_envio
        or "EduTrack <onboarding@resend.dev>"
    )
    if not correo_envio:
        correo_envio = from_addr
    token = _asegurar_token_pqr(t)
    base_url = (os.environ.get("APP_BASE_URL") or request.url_root or "").rstrip("/")
    link = f"{base_url}/pqr/notificacion/{token}"
    nombre = _nombre_destinatario_pqr(t)
    empresa = nombre_empresa()
    producto = nombre_producto()
    try:
        pp = plataforma()
        wa_num = "".join(c for c in (getattr(pp, "contacto_whatsapp_ventas", None) or "") if c.isdigit())
        email_ayuda = (getattr(pp, "contacto_publico_email", None) or SOPORTE_EMAIL).strip()
    except Exception:
        wa_num, email_ayuda = "", SOPORTE_EMAIL
    wa_link = f"https://wa.me/{wa_num}" if wa_num else f"mailto:{email_ayuda}"
    # Foto hero PROCSIS como CID (Resend attachment content_id). Gmail bloquea data-URI.
    hero_img = "cid:hero_procsis"
    _hero_bytes, _hero_mime, _hero_fname = _cargar_hero_pqr()
    if not _hero_bytes:
        # Fallback URL pública por si el archivo no está en el contenedor
        hero_img = f"{base_url}/static/img/pqr-respuesta-hero.png"
        print("PQR hero: sin archivo local, se usará URL", hero_img)

    html = f"""
<div style="font-family:Segoe UI,Arial,sans-serif;max-width:600px;margin:0 auto;background:#fff;border:1px solid #e2e8f0;border-radius:14px;overflow:hidden">
  <!-- Cabecera visual tipo telco: saludo + foto PROCSIS + chip amarillo -->
  <div style="position:relative;background:#b8d4f0;overflow:hidden">
    <div style="position:absolute;top:0;right:0;width:120px;height:72px;background:#0B2D57;border-bottom-left-radius:56px;z-index:2;display:flex;align-items:center;justify-content:center">
      <span style="color:#fff;font-weight:800;font-size:13px;letter-spacing:1.2px;font-family:Georgia,Times New Roman,serif">PROCSIS</span>
    </div>
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse">
      <tr>
        <td style="vertical-align:middle;padding:28px 20px 28px 26px;width:42%">
          <p style="margin:0;color:#0B2D57;font-size:15px">Hola,</p>
          <p style="margin:4px 0 16px;color:#0B2D57;font-weight:800;font-size:18px;line-height:1.25">{_esc(nombre)}</p>
          <span style="background:#facc15;color:#0f172a;font-weight:800;padding:8px 14px;border-radius:6px;font-size:15px;display:inline-block;line-height:1.3">Esta información<br>es para ti</span>
        </td>
        <td style="vertical-align:bottom;padding:0;width:58%;text-align:right">
          <img src="{hero_img}" alt="PROCSIS" width="280" style="display:block;width:100%;max-width:280px;height:auto;margin:0 0 0 auto;border:0">
        </td>
      </tr>
    </table>
  </div>
  <div style="padding:22px 26px 8px;color:#0B2D57;font-size:15px;line-height:1.6">
    <p style="margin:0 0 8px">Por medio de este correo electrónico certificado, te compartimos de forma oportuna y efectiva, <b>la respuesta a la solicitud que nos realizaste</b>, para verla haz clic en el botón a continuación:</p>
    <div style="text-align:center;margin:26px 0 18px">
      <a href="{link}" style="background:#38bdf8;color:#fff;text-decoration:none;font-weight:800;padding:14px 40px;border-radius:999px;display:inline-block;font-size:15px;letter-spacing:.4px">VER RESPUESTA</a>
    </div>
  </div>
  <div style="padding:0 26px 20px">
    <div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px;padding:12px 14px;font-size:11.5px;color:#475569">
      <b>Ten en cuenta:</b> con la recepción de este correo se entiende que has sido notificado para todos los efectos, según las normas aplicables vigentes, en especial los artículos 12 y 20 de la Ley 527 de 1999 y sus normas reglamentarias sobre mensajes de datos.
    </div>
  </div>
  <div style="background:#0B2D57;color:#fff;padding:24px 26px;text-align:center">
    <div style="border:1px solid #f59e0b;border-radius:8px;padding:12px;font-size:12px;margin-bottom:16px">
      ⚠ Por favor no respondas este mensaje. Este buzón tiene como propósito el envío de información y no es un canal oficial para la recepción de solicitudes, peticiones, quejas y reclamos.
    </div>
    <p style="margin:0 0 10px;font-size:13px">¿Dudas? Te las resolvemos aquí</p>
    <a href="mailto:{email_ayuda}" style="display:inline-block;background:#fff;color:#0B2D57;text-decoration:none;font-weight:700;padding:8px 16px;border-radius:20px;font-size:12px;margin:0 6px">Centro de Ayuda</a>
    <a href="{wa_link}" style="display:inline-block;background:#25D366;color:#fff;text-decoration:none;font-weight:700;padding:8px 16px;border-radius:20px;font-size:12px;margin:0 6px">WhatsApp</a>
  </div>
  <div style="padding:14px 26px;font-size:10.5px;color:#94a3b8;text-align:center">
    {empresa} © {ahora().year} · Todos los derechos reservados
  </div>
</div>
"""
    try:
        msg = EmailMessage()
        msg["Subject"] = f"PROCSIS · Respuesta a su solicitud Radicado No. {formatear_radicado(t.radicado or t.nro_cun)}"
        msg["From"] = from_addr
        msg["To"] = destino
        msg.set_content(
            f"Hola {nombre},\n\n"
            f"Te compartimos la respuesta a tu solicitud (Radicado No. {formatear_radicado(t.radicado)}).\n"
            f"Consúltala en: {link}\n\n"
            f"Por favor no respondas este mensaje.\n{empresa} · {producto}"
        )
        msg.add_alternative(html, subtype="html")
        # Adjuntar foto hero como inline CID para Resend/Gmail
        try:
            if _hero_bytes:
                msg._resend_inline_attachments = [{
                    "content": _hero_bytes,
                    "filename": _hero_fname or "pqr-respuesta-hero.png",
                    "content_id": "hero_procsis",
                }]
                # También related part para SMTP clásico
                try:
                    msg.get_payload()[-1].add_related(
                        _hero_bytes,
                        maintype="image",
                        subtype=_hero_mime or "png",
                        cid="hero_procsis",
                    )
                except Exception as _rel_e:
                    print("related attach:", _rel_e)
            else:
                print("PQR hero: archivo no encontrado en static/img/ — el correo irá sin foto")
        except Exception as _att_e:
            print("PQR hero attach error:", _att_e)
        _smtp_enviar(msg, correo_envio, password)
        t.notificacion_enviada_en = f"{fecha_hoy()} {hora_actual()}"
        # Solo persistir si el ticket ya existe en BD (evitar commit de tickets de prueba en memoria)
        if getattr(t, "id", None):
            try:
                db.session.commit()
            except Exception as ce:
                db.session.rollback()
                print("PQR notificación: no se pudo guardar notificacion_enviada_en:", ce)
        return True
    except Exception as e:
        print("PQR notificación estilo Tigo error:", e)
        return False


