@app.route("/familia/certificado")
def familia_certificado():
    """Certificado de estudio membretado con código QR de verificación."""
    if not session.get("familia") or not session.get("familia_est_id"):
        return redirect("/familia-login")
    e = Estudiante.query.get(session.get("familia_est_id"))
    if not e:
        return redirect("/familia-login")
    if getattr(e, "mora_pension", False):
        return page(
            "Mora de pensión",
            "<div style='padding:40px;max-width:480px;margin:40px auto;font-family:Segoe UI,sans-serif'>"
            "<h2 style='color:#b91c1c'>Certificado bloqueado</h2>"
            "<p>Por favor, póngase al día en tesorería.</p>"
            "<a href='/familia'>Volver</a></div>",
        )
    import secrets
    codigo = "CERT-" + secrets.token_hex(6).upper()
    try:
        db.create_all()
    except Exception:
        pass
    cert = CertificadoEstudio(
        institucion_id=e.institucion_id,
        estudiante_id=e.id,
        codigo_verificacion=codigo,
        tipo="ESTUDIO",
        emitido_en=f"{fecha_hoy()} {hora_actual()}",
        emitido_por=session.get("usuario") or "acudiente",
        anio=str(ahora().year) if hasattr(ahora(), "year") else fecha_hoy()[:4],
    )
    db.session.add(cert)
    db.session.commit()
    from reportlab.lib.pagesizes import letter
    from reportlab.pdfgen import canvas
    from reportlab.lib.units import cm
    buf = BytesIO()
    pdf = canvas.Canvas(buf, pagesize=letter)
    w, h = letter
    try:
        nom_inst = INST_NOMBRE
    except Exception:
        nom_inst = "Institución educativa"
    pdf.setFont("Helvetica-Bold", 14)
    pdf.drawCentredString(w / 2, h - 2 * cm, str(nom_inst)[:70])
    pdf.setFont("Helvetica-Bold", 12)
    pdf.drawCentredString(w / 2, h - 2.8 * cm, "CERTIFICADO DE ESTUDIO")
    pdf.setFont("Helvetica", 10)
    y = h - 4 * cm
    texto = (
        f"La institución certifica que el(la) estudiante {estudiante_nombre(e)}, "
        f"identificado(a) con documento {e.documento or '—'}, código {e.codigo}, "
        f"se encuentra matriculado(a) en el grado {e.grado} durante el año lectivo {cert.anio}."
    )
    from reportlab.lib.utils import simpleSplit
    for ln in simpleSplit(texto, "Helvetica", 10, w - 4 * cm):
        pdf.drawString(2 * cm, y, ln)
        y -= 14
    y -= 20
    pdf.drawString(2 * cm, y, f"Código de verificación: {codigo}")
    y -= 14
    pdf.drawString(2 * cm, y, f"Emitido: {cert.emitido_en}")
    y -= 14
    try:
        base = request.host_url.rstrip("/")
    except Exception:
        base = ""
    pdf.drawString(2 * cm, y, f"Verifique autenticidad en: {base}/verificar-certificado/{codigo}")
    y -= 40
    pdf.drawString(2 * cm, y, "___________________________")
    y -= 12
    pdf.drawString(2 * cm, y, "Secretaría académica")
    pdf.setFont("Helvetica", 7)
    pdf.drawCentredString(w / 2, 1.5 * cm, f"EduTrack · QR/código {codigo} · No requiere firma manuscrita si el colegio valida en línea")
    pdf.save()
    buf.seek(0)
    return send_file(buf, as_attachment=True, download_name=f"certificado_{e.codigo}_{codigo}.pdf", mimetype="application/pdf")


