@app.route("/secretaria/editar-estudiante/<int:id>", methods=["GET", "POST"])
def secretaria_editar_estudiante(id):
    g = _guard_secretaria_docs()
    if g:
        return g
    if not _puede_editar_secretaria():
        return acceso_denegado("Solo Secretaría puede editar datos de estudiantes.")
    e = Estudiante.query.get_or_404(id)
    iid = institucion_id_actual()
    if iid is not None and e.institucion_id is not None and int(e.institucion_id) != int(iid):
        return acceso_denegado()
    mensaje = ""
    error = ""
    if request.method == "POST":
        nuevo_codigo = (request.form.get("codigo") or "").strip()
        # Acepta tanto nombre/apellido como nombre1/apellido1 (SIMAT)
        n1 = (request.form.get("nombre1") or request.form.get("nombre") or "").strip()
        a1 = (request.form.get("apellido1") or request.form.get("apellido") or "").strip()
        if not nuevo_codigo:
            error = "El código no puede quedar vacío."
        elif not n1 or not a1:
            error = "Primer nombre y primer apellido son obligatorios."
        else:
            if nuevo_codigo != e.codigo:
                choque = Estudiante.query.filter(Estudiante.codigo == nuevo_codigo, Estudiante.id != e.id).first()
                if choque:
                    error = f"El código {nuevo_codigo} ya lo tiene otro estudiante ({estudiante_nombre(choque)}). Elija otro."
            if not error:
                cambios = []
                old_nom = estudiante_nombre(e)
                e.codigo = nuevo_codigo
                _aplicar_nombres_estudiante(e, request.form)
                campos = [
                    "documento", "tipo_doc", "grado", "grupo", "sede", "jornada",
                    "director", "acudiente", "padre", "madre", "telefono_acudiente", "correo_acudiente",
                    "direccion", "fecha_nacimiento", "genero", "rh", "observacion",
                ]
                for campo in campos:
                    if not hasattr(e, campo):
                        continue
                    nuevo_val = (request.form.get(campo) or "").strip()
                    if str(getattr(e, campo, "") or "") != nuevo_val:
                        cambios.append(campo)
                        setattr(e, campo, nuevo_val)
                foto_f = request.files.get("foto")
                if foto_f and getattr(foto_f, "filename", ""):
                    ruta = guardar_foto_estudiante(foto_f, e.id, iid)
                    if ruta and hasattr(e, "foto_path"):
                        e.foto_path = ruta
                        cambios.append("foto")
                db.session.commit()
                if cambios or old_nom != estudiante_nombre(e):
                    registrar_auditoria("Editar estudiante", f"{e.codigo} - {estudiante_nombre(e)} - campos: {', '.join(cambios) or 'nombres'}")
                mensaje = "Datos actualizados correctamente."
    def v(campo):
        return _esc(getattr(e, campo, "") or "")
    # Valores precomputados para campos SIMAT (evitan lógica compleja dentro del f-string)
    _ap = (getattr(e, "apellido", None) or "").strip()
    _no = (getattr(e, "nombre", None) or "").strip()
