    _a2 = _esc(getattr(e, "apellido2", None) or (" ".join(_ap.split()[1:]) if _ap and len(_ap.split()) > 1 else ""))
    _n1 = _esc(getattr(e, "nombre1", None) or (_no.split()[0] if _no else ""))
    _n2 = _esc(getattr(e, "nombre2", None) or (" ".join(_no.split()[1:]) if _no and len(_no.split()) > 1 else ""))
    opciones_grado = "".join(f'<option value="{g}" {"selected" if g==e.grado else ""}>{g}</option>' for g in grados_disponibles())
