def _consolidado_siee_datos():
    iid = institucion_id_actual()
    q = Estudiante.query
    if iid is not None:
        q = q.filter(Estudiante.institucion_id == iid)
    estudiantes = q.order_by(Estudiante.grado.asc(), Estudiante.apellido.asc()).all()
    out = []
    for e in estudiantes:
        prom = _promedio_final_estudiante(e.id, iid)
        lbl, _ = desempeno_label(prom)
        out.append((e, prom, lbl))
    return out


@app.route("/secretaria/consolidado-siee/pdf")
def secretaria_consolidado_siee_pdf():
    g = _guard_secretaria_docs()
    if g:
        return g
    datos = _consolidado_siee_datos()
    iid = institucion_id_actual()
    inst = Institucion.query.get(iid) if iid else None
    nom_inst = (inst.nombre if inst else None) or INST_NOMBRE or "Institución educativa"
    from reportlab.lib.pagesizes import landscape, letter
    from reportlab.pdfgen import canvas as _canvas
    buf = BytesIO()
    pdf = _canvas.Canvas(buf, pagesize=landscape(letter))
    w, h = landscape(letter)
    pdf.setFont("Helvetica-Bold", 13)
    pdf.drawCentredString(w / 2, h - 30, str(nom_inst)[:80])
    pdf.setFont("Helvetica-Bold", 11)
    pdf.drawCentredString(w / 2, h - 46, f"LIBRO CALIFICADOR FINAL · Año lectivo {ahora().year if hasattr(ahora(),'year') else fecha_hoy()[:4]}")
    y = h - 74
    pdf.setFont("Helvetica-Bold", 9)
    pdf.drawString(30, y, "Código"); pdf.drawString(120, y, "Nombre"); pdf.drawString(420, y, "Grado")
    pdf.drawString(500, y, "Promedio"); pdf.drawString(580, y, "Desempeño")
    y -= 4
    pdf.line(30, y, w - 30, y)
    y -= 14
    pdf.setFont("Helvetica", 8.5)
    for e, prom, lbl in datos:
        if y < 40:
            pdf.showPage()
            y = h - 40
            pdf.setFont("Helvetica", 8.5)
        pdf.drawString(30, y, str(e.codigo)[:20])
        pdf.drawString(120, y, estudiante_nombre(e)[:55])
        pdf.drawString(420, y, str(e.grado))
        pdf.drawString(500, y, f"{prom:.2f}" if prom is not None else "—")
        pdf.drawString(580, y, lbl)
        y -= 13
    pdf.save()
    buf.seek(0)
    registrar_auditoria("Consolidado SIEE exportado (PDF)", f"{len(datos)} estudiante(s)")
    return send_file(buf, as_attachment=True, download_name=f"libro_calificador_final_{fecha_hoy()}.pdf", mimetype="application/pdf")


@app.route("/secretaria/consolidado-siee/excel")
def secretaria_consolidado_siee_excel():
    g = _guard_secretaria_docs()
    if g:
        return g
    datos = _consolidado_siee_datos()
    wb = Workbook()
    ws = wb.active
    ws.title = "Libro Calificador Final"
    encabezado = ["Código", "Documento", "Nombre completo", "Grado", "Promedio final", "Desempeño nacional"]
    ws.append(encabezado)
    for c in ws[1]:
        c.font = Font(bold=True, color="FFFFFF")
        c.fill = PatternFill(start_color="0B2D57", end_color="0B2D57", fill_type="solid")
    for e, prom, lbl in datos:
        ws.append([e.codigo, e.documento, estudiante_nombre(e), e.grado, round(prom, 2) if prom is not None else None, lbl])
    for i, colw in enumerate([14, 16, 34, 10, 14, 18], start=1):
        ws.column_dimensions[get_column_letter(i)].width = colw
    buf = BytesIO()
    wb.save(buf)
    buf.seek(0)
    registrar_auditoria("Consolidado SIEE exportado (Excel)", f"{len(datos)} estudiante(s)")
    return send_file(buf, as_attachment=True, download_name=f"libro_calificador_final_{fecha_hoy()}.xlsx",
                      mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")


