@app.route("/secretaria/piar", methods=["GET", "POST"])
def secretaria_piar():
    g = _guard_secretaria_docs()
    if g:
        return g
    iid = institucion_id_actual()
    mensaje = ""
    if request.method == "POST":
        sid = request.form.get("estudiante_id")
        e = Estudiante.query.get(int(sid)) if sid else None
        if e and (iid is None or e.institucion_id is None or int(e.institucion_id) == int(iid)):
            e.piar_activo = request.form.get("piar_activo") == "1"
            archivo = request.files.get("piar_pdf")
            if archivo and archivo.filename:
                if not archivo.filename.lower().endswith(".pdf"):
                    mensaje = "El seguimiento debe subirse en PDF."
                else:
                    up_dir = os.path.join(app.root_path, "static", "uploads", "piar")
                    os.makedirs(up_dir, exist_ok=True)
                    fname = f"piar_{e.id}_{int(__import__('time').time())}.pdf"
                    archivo.save(os.path.join(up_dir, fname))
                    e.piar_pdf = f"/static/uploads/piar/{fname}"
            db.session.commit()
            registrar_auditoria("PIAR actualizado", f"{estudiante_nombre(e)}: activo={e.piar_activo}")
            mensaje = mensaje or "Guardado."
    q = Estudiante.query
    if iid is not None:
        q = q.filter(Estudiante.institucion_id == iid)
    estudiantes = q.order_by(Estudiante.sede.asc(), Estudiante.grado.asc(), Estudiante.apellido.asc()).all()
    por_sede = {}
    for e in estudiantes:
        if getattr(e, "piar_activo", False):
            sede = e.sede or "Sin sede"
            por_sede[sede] = por_sede.get(sede, 0) + 1
    resumen = "".join(f"<tr><td>{_esc(s)}</td><td>{n}</td></tr>" for s, n in sorted(por_sede.items())) or '<tr><td colspan="2">Sin estudiantes con PIAR activo</td></tr>'
    filas = "".join(
        f"""<tr><td>{_esc(e.codigo)}</td><td>{_esc(estudiante_nombre(e))}</td><td>{_esc(e.grado)}</td><td>{_esc(e.sede) or '—'}</td>
        <td><form method="POST" enctype="multipart/form-data" style="display:flex;gap:6px;align-items:center;flex-wrap:wrap">
          <input type="hidden" name="estudiante_id" value="{e.id}">
          <label style="font-size:12px"><input type="checkbox" name="piar_activo" value="1" {"checked" if getattr(e,'piar_activo',False) else ""}> Requiere PIAR</label>
          <input type="file" name="piar_pdf" accept="application/pdf" style="width:140px">
          <button type="submit" class="small-action">Guardar</button>
          {"<a href='"+_esc(e.piar_pdf)+"' target='_blank' class='small-action'>Ver PDF</a>" if getattr(e,'piar_pdf',None) else ""}
        </form></td></tr>"""
        for e in estudiantes
    ) or '<tr><td colspan="5">Sin estudiantes</td></tr>'
    content = f"""
<header class="role-hero"><div>
  <h1>📈 PIAR · Índice de inclusión</h1>
  <p>Decreto 1421 de 2017 — Plan Individual de Ajustes Razonables por estudiante y reporte por sede.</p>
</div>
<a class="btn" href="/secretaria/documentos">Volver</a></header>
{"<div class='msg ok'>"+mensaje+"</div>" if mensaje else ""}
<section class="role-panel">
  <h2>Resumen por sede (estudiantes con PIAR activo)</h2>
  <table><tr><th>Sede</th><th>Cantidad</th></tr>{resumen}</table>
</section>
<section class="role-panel" style="margin-top:12px">
  <h2>Detalle por estudiante</h2>
  <div style="overflow-x:auto">
    <table>
      <tr><th>Código</th><th>Nombre</th><th>Grado</th><th>Sede</th><th>PIAR / seguimiento</th></tr>
      {filas}
    </table>
  </div>
</section>
"""
    return page("PIAR", shell(content))


