def _borrar_estudiante_y_relacionados(e):
    """Borra ingresos, asistencia, excusas, notas y faltas del estudiante."""
    eid = e.id
    try:
        IngresoPorteria.query.filter_by(estudiante_id=eid).delete(synchronize_session=False)
    except Exception:
        pass
    try:
        AsistenciaClase.query.filter_by(estudiante_id=eid).delete(synchronize_session=False)
    except Exception:
        pass
    try:
        Excusa.query.filter_by(estudiante_id=eid).delete(synchronize_session=False)
    except Exception:
        pass
    try:
        FaltaPlanilla.query.filter_by(estudiante_id=eid).delete(synchronize_session=False)
    except Exception:
        pass
    try:
        NotaRegistro.query.filter_by(estudiante_id=eid).delete(synchronize_session=False)
    except Exception:
        pass
    # otros modelos opcionales
    for model_name in ("NotaSiee", "LogroNota", "DefinitivaPeriodo"):
        try:
            m = globals().get(model_name)
            if m is not None:
                m.query.filter_by(estudiante_id=eid).delete(synchronize_session=False)
        except Exception:
            pass
    db.session.delete(e)


@app.route("/eliminar_estudiante/<int:id>")
def eliminar_estudiante(id):
    if not requiere_login():
        return redirect("/login")
    if not puede_estudiantes():
        return acceso_denegado()
    e = Estudiante.query.get_or_404(id)
    iid = institucion_id_actual()
    if iid is not None and e.institucion_id is not None and int(e.institucion_id) != int(iid) and rol_actual() != "Soporte":
        return acceso_denegado("No puedes eliminar estudiantes de otro colegio.")
    registrar_auditoria("Eliminar estudiante", f"{e.codigo} - {e.nombre} {e.apellido}")
    _borrar_estudiante_y_relacionados(e)
    db.session.commit()
    return redirect("/estudiantes")




@app.route("/secretaria/arreglar-nombres", methods=["GET", "POST"])
def secretaria_arreglar_nombres():
    """Reconstruye nombre/apellido desde nombre1/2 apellido1/2 cuando quedaron vacíos o 'SIN NOMBRE'."""
    if not requiere_login():
        return redirect("/login")
    if rol_actual() not in ("Secretaría", "Soporte", "Rectoría", "Superadmin", "Gerente"):
        return acceso_denegado()
    msg = ""
    if request.method == "POST":
        iid = institucion_id_actual()
        q = Estudiante.query
        if iid is not None:
            q = q.filter(Estudiante.institucion_id == iid)
        n = 0
        for e in q.all():
            no = (e.nombre or "").strip()
            ap = (e.apellido or "").strip()
            need = (not no or no.lower() in ("sin nombre", "sin nombres", "")) or (not ap or ap.lower() in ("sin apellido", "sin apellidos", ""))
            if need and (getattr(e, "nombre1", None) or getattr(e, "apellido1", None)):
                a1 = (getattr(e, "apellido1", None) or "").strip()
                a2 = (getattr(e, "apellido2", None) or "").strip()
                n1 = (getattr(e, "nombre1", None) or "").strip()
                n2 = (getattr(e, "nombre2", None) or "").strip()
                e.apellido = (f"{a1} {a2}".strip() or ap or "Sin apellido")[:120]
                e.nombre = (f"{n1} {n2}".strip() or no or "Sin nombre")[:120]
                n += 1
        db.session.commit()
        registrar_auditoria("Arreglar nombres estudiantes", f"{n} actualizados")
        msg = f"Se reconstruyeron nombres de {n} estudiante(s)."
    content = f"""
<header class="role-hero"><div>
  <h1>Reparar nombres de estudiantes</h1>
  <p>Si al registrar se guardaron vacíos, esta herramienta reconstruye nombre/apellido desde los campos SIMAT (nombre1, apellido1…).</p>
</div>
<a class="btn" href="/buscar_estudiantes">Volver</a></header>
{"<div class='msg ok'>"+msg+"</div>" if msg else ""}
<section class="role-panel" style="max-width:520px">
  <form method="POST" onsubmit="return confirm('¿Reconstruir nombres vacíos de esta institución?')">
    <button type="submit">Reparar nombres ahora</button>
  </form>
</section>
"""
    return page("Reparar nombres", shell(content))

@app.route("/estudiantes/eliminar_todos", methods=["GET", "POST"])
def eliminar_todos_estudiantes():
    """Secretaría / dirección: borrar todos los estudiantes del colegio actual."""
    if not requiere_login():
        return redirect("/login")
    if rol_actual() not in ("Secretaría", "Rectoría", "Administrador", "Soporte"):
        return acceso_denegado("Solo Secretaría o Rectoría pueden vaciar la lista de estudiantes.")
    iid = institucion_id_actual()
    if not iid and rol_actual() != "Soporte":
        return acceso_denegado("Debes estar en una institución.")
    q = q_estudiantes() if iid else Estudiante.query
    total = q.count()
    mensaje = ""
    if request.method == "POST":
        confirm = (request.form.get("confirmacion") or "").strip().upper()
        if confirm != "ELIMINAR":
            mensaje = 'Debes escribir exactamente la palabra ELIMINAR para confirmar.'
        else:
            lista = q.all()
            n = 0
            for e in lista:
                try:
                    _borrar_estudiante_y_relacionados(e)
                    n += 1
                except Exception as ex:
                    print("del est:", ex)
            db.session.commit()
            try:
                registrar_auditoria("Eliminar todos estudiantes", f"{n} registros · inst {iid}")
            except Exception:
                pass
            mensaje = f"Se eliminaron {n} estudiantes del colegio."
            total = 0
    content = f"""
<header class="role-hero"><div>
  <h1>Eliminar todos los estudiantes</h1>
  <p>Acción irreversible para este colegio. Se borran también ingresos, asistencias, notas y faltas asociadas.</p>
</div>
<a class="btn" href="/estudiantes">Volver</a></header>
{"<div class='msg ok'>"+mensaje+"</div>" if mensaje and "eliminaron" in mensaje else ""}
{"<div class='msg danger'>"+mensaje+"</div>" if mensaje and "eliminaron" not in mensaje else ""}
<section class="role-panel">
  <p>Estudiantes actuales en este colegio: <b>{total}</b></p>
  <p class="mini-text">Útil para limpiar datos de prueba antes de cargar la lista real.</p>
  <form method="POST" onsubmit="return confirm('¿Confirmas eliminar TODOS los estudiantes de este colegio?');">
    <label><b>Escribe ELIMINAR para confirmar</b></label>
    <input name="confirmacion" placeholder="ELIMINAR" autocomplete="off" required>
    <button type="submit" class="btn-red" style="margin-top:12px;background:#b91c1c">Eliminar todos los estudiantes</button>
  </form>
</section>
"""
    return page("Eliminar estudiantes", shell(content))


