@app.route("/reset_usuario/<int:id>", methods=["GET", "POST"])
def reset_usuario(id):
    if not requiere_login(): return redirect("/login")
    if not (puede_admin() or rol_actual() == "Soporte"): return acceso_denegado()
    u = Usuario.query.get_or_404(id)
    # Seguridad multi-tenant: admin solo del mismo colegio
    iid = institucion_id_actual()
    if rol_actual() != "Soporte" and iid is not None and u.institucion_id is not None and int(u.institucion_id) != int(iid):
        return acceso_denegado("No puedes restablecer usuarios de otro colegio.")
    nueva = "Colegio2026*"
    if request.method == "POST":
        nueva = (request.form.get("password") or nueva).strip() or nueva
    u.password = crear_hash(nueva)
    u.password_temporal = False  # puede entrar de una con esta clave
    db.session.commit()
    registrar_auditoria("Restablecer contraseña", f"{u.usuario} → clave temporal aplicada")
    session["flash_usuarios"] = f"Clave de '{u.usuario}' restablecida a: {nueva}"
    if rol_actual() == "Soporte" and u.institucion_id:
        return redirect(f"/soporte/usuarios/{u.institucion_id}")
    return redirect("/usuarios")


@app.route("/eliminar_usuario/<int:id>")
def eliminar_usuario(id):
    if not requiere_login():
        return redirect("/login")
    if rol_actual() == "Soporte":
        return acceso_denegado("Soporte no tiene permiso para eliminar usuarios. Escale el caso a Gerencia.")
    if not puede_usuarios():
        return acceso_denegado()
    u = Usuario.query.get_or_404(id)
    iid = institucion_id_actual()
    if iid is not None and u.institucion_id is not None and int(u.institucion_id) != int(iid):
        return acceso_denegado("No puedes eliminar usuarios de otro colegio.")
    if u.usuario == session.get("usuario"):
        session["flash_usuarios"] = "No puedes eliminarte a ti mismo."
        if u.institucion_id:
            return redirect(f"/soporte/usuarios/{u.institucion_id}")
        return redirect("/usuarios")
    # Permitir borrar demo, incluso si rol era raro; solo proteger la ÚLTIMA cuenta Soporte
    if (u.rol or "") == "Soporte":
        otros = Usuario.query.filter(Usuario.rol == "Soporte", Usuario.id != u.id).count()
        if otros < 1:
            session["flash_usuarios"] = "No se puede eliminar el único usuario Soporte del sistema."
            return redirect("/usuarios")
    inst_redir = u.institucion_id
    nombre = u.usuario
    try:
        # Limpiar dependencias que bloquean el DELETE
        try:
            AsignacionDocente.query.filter_by(usuario_id=u.id).delete(synchronize_session=False)
        except Exception:
            pass
        db.session.delete(u)
        db.session.commit()
        registrar_auditoria("Eliminar usuario", f"Eliminó {nombre}")
        session["flash_usuarios"] = f"Usuario '{nombre}' eliminado definitivamente."
    except Exception as ex:
        db.session.rollback()
        session["flash_usuarios"] = f"No se pudo eliminar: {ex}"
    if rol_actual() == "Soporte" and inst_redir:
        return redirect(f"/soporte/usuarios/{inst_redir}")
    return redirect("/usuarios")


@app.route("/soporte/limpiar_usuarios/<int:id>")
def soporte_limpiar_usuarios(id):
    """Elimina TODOS los usuarios del colegio (para dejar limpio antes de vender)."""
    if not requiere_login() or rol_actual() != "Soporte":
        return acceso_denegado()
    inst = Institucion.query.get_or_404(id)
    eliminados = 0
    for u in Usuario.query.filter(Usuario.institucion_id == inst.id).all():
        if (u.rol or "") == "Soporte":
            continue
        if u.usuario == session.get("usuario"):
            continue
        try:
            try:
                AsignacionDocente.query.filter_by(usuario_id=u.id).delete(synchronize_session=False)
            except Exception:
                pass
            db.session.delete(u)
            eliminados += 1
        except Exception:
            db.session.rollback()
    db.session.commit()
    registrar_auditoria("Limpiar usuarios colegio", f"Inst {inst.codigo}: {eliminados} eliminados")
    session["flash_usuarios"] = (
        f"Se eliminaron {eliminados} usuarios del colegio. "
        f"Crea solo los que necesite el cliente desde Soporte → Usuarios."
    )
    return redirect(f"/soporte/usuarios/{id}")



