@app.route("/backup")
@app.route("/backup_datos")
def backup():
    """Respaldo Excel de protección de datos (Secretaría / dirección / Soporte)."""
    if not requiere_login():
        return redirect("/login")
    if rol_actual() not in ("Secretaría", "Rectoría", "Coordinación", "Administrador", "Soporte"):
        return acceso_denegado("Solo Secretaría, dirección o Soporte pueden descargar respaldos.")
    # Página informativa si GET sin ?dl=1
    if request.args.get("dl") != "1" and request.path.endswith("backup_datos"):
        cfg = config()
        last = getattr(cfg, "last_backup", None) or "Nunca"
        aviso = ""
        try:
            from datetime import datetime as _dt
            if last and last != "Nunca":
                dias = (_dt.strptime(fecha_hoy(), "%Y-%m-%d") - _dt.strptime(last[:10], "%Y-%m-%d")).days
                if dias >= 15:
                    aviso = f'<div class="msg danger">Han pasado <b>{dias} días</b> desde el último respaldo. Descargue una copia ahora.</div>'
                else:
                    aviso = f'<div class="msg ok">Último respaldo hace {dias} día(s). Recomendado cada 15 días.</div>'
            else:
                aviso = '<div class="msg warn">Aún no hay respaldo registrado. Descargue la primera copia de seguridad.</div>'
        except Exception:
            pass
        content = f"""
<header class="role-hero"><div>
  <h1>Respaldo y protección de datos</h1>
  <p>Habeas data · Copia de seguridad del colegio · Cada 15 días</p>
</div></header>
{aviso}
<section class="role-panel">
  <p>Para proteger la información ante caídas del servidor, borrados accidentales o cambios de equipo,
  descargue periódicamente un archivo Excel con <b>estudiantes (SIMAT)</b>, ingresos y usuarios del colegio.</p>
  <ul>
    <li>Último respaldo registrado: <b>{last}</b></li>
    <li>Frecuencia recomendada: <b>cada 15 días</b></li>
    <li>Guarde el archivo en un disco seguro del colegio (no solo en este computador).</li>
  </ul>
  <p><a class="btn btn-green" href="/backup?dl=1">Descargar respaldo ahora (.xlsx)</a></p>
  <p class="mini-text">El sistema registra la fecha al descargar para recordarle el próximo ciclo de 15 días.</p>
</section>
"""
        return page("Respaldo", shell(content))

    wb = Workbook()
    ws = wb.active
    ws.title = "Estudiantes_SIMAT"
    headers = [
        "TIPO_DOC", "NRO_DOC", "EXP_DEPA", "EXP_MUNI", "APELLIDO1", "APELLIDO2", "NOMBRE1", "NOMBRE2",
        "FECHA_NAC", "GENERO", "RH", "CODIGO", "GRADO", "GRUPO", "JORNADA", "SEDE",
        "DIRECCION", "BARRIO", "ESTRATO", "ZONA", "MUN_RES", "DEP_RES",
        "SISBEN", "DISCAPACIDAD", "CAP_EXCEP", "VICTIMA", "ETNIA", "EPS",
        "ACUDIENTE", "ACUD_DOC", "ACUD_TEL", "ACUD_CORREO", "PADRE", "MADRE", "DIRECTOR", "ESTADO",
    ]
    ws.append(headers)
    for col in range(1, len(headers) + 1):
        ws.cell(1, col).number_format = "@"
    for e in q_estudiantes().order_by(Estudiante.grado.asc(), Estudiante.apellido.asc()).all():
        row = [
            getattr(e, "tipo_doc", None) or "TI",
            e.documento or "",
            getattr(e, "exp_depa", None) or "",
            getattr(e, "exp_muni", None) or "",
            getattr(e, "apellido1", None) or (e.apellido or "").split(" ")[0],
            getattr(e, "apellido2", None) or "",
            getattr(e, "nombre1", None) or (e.nombre or "").split(" ")[0],
            getattr(e, "nombre2", None) or "",
            getattr(e, "fecha_nacimiento", None) or "",
            getattr(e, "genero", None) or "",
            e.rh or "",
            e.codigo or "",
            e.grado or "",
            getattr(e, "grupo", None) or "",
            getattr(e, "jornada", None) or "",
            getattr(e, "sede", None) or "",
            e.direccion or "",
            getattr(e, "barrio", None) or "",
            getattr(e, "estrato", None) or "",
            getattr(e, "zona", None) or "",
            getattr(e, "mun_res", None) or "",
            getattr(e, "dep_res", None) or "",
            getattr(e, "sisben_grupo", None) or "",
            getattr(e, "discapacidad", None) or "",
            getattr(e, "capacidad_excep", None) or "",
            getattr(e, "victima", None) or "",
            getattr(e, "etnia", None) or "",
            getattr(e, "eps", None) or "",
            e.acudiente or "",
            getattr(e, "acudiente_doc", None) or "",
            e.telefono_acudiente or "",
            e.correo_acudiente or "",
            e.padre or "",
            e.madre or "",
            e.director or "",
            getattr(e, "estado", None) or "ACTIVO",
        ]
        ws.append(row)
        for col in range(1, len(row) + 1):
            ws.cell(ws.max_row, col).number_format = "@"

    ws2 = wb.create_sheet("Ingresos")
    ws2.append(["codigo", "estudiante", "grado", "fecha", "hora", "estado", "periodo", "registrado_por"])
    try:
        for i in IngresoPorteria.query.join(Estudiante).order_by(IngresoPorteria.id.desc()).limit(5000).all():
            ws2.append([
                i.estudiante.codigo,
                f"{i.estudiante.nombre} {i.estudiante.apellido}",
                i.estudiante.grado, i.fecha, i.hora, i.estado, i.periodo, i.registrado_por,
            ])
    except Exception:
        pass

    ws3 = wb.create_sheet("Usuarios")
    ws3.append(["usuario", "rol", "correo", "grupo_docente"])
    try:
        for u in q_usuarios().order_by(Usuario.rol.asc()).all():
            if u.rol == "Soporte":
                continue
            ws3.append([u.usuario, u.rol, u.correo, u.grupo_docente])
    except Exception:
        pass

    try:
        cfg = config()
        cfg.last_backup = fecha_hoy()
        db.session.commit()
    except Exception:
        db.session.rollback()

    try:
        registrar_auditoria("Backup", f"Respaldo Excel SIMAT · {session.get('usuario')}")
    except Exception:
        pass
    b = BytesIO()
    wb.save(b)
    b.seek(0)
    return send_file(b, as_attachment=True, download_name=f"backup_edutrack_{fecha_hoy()}.xlsx")


