@app.route("/importar_estudiantes", methods=["GET", "POST"])
def importar_estudiantes():
    if not requiere_login(): return redirect("/login")
    if not puede_estudiantes(): return acceso_denegado()
    mensaje = ""
    if request.method == "POST":
        archivo = request.files.get("archivo")
        if not archivo or not archivo.filename.lower().endswith(".xlsx"):
            mensaje = "Sube un archivo Excel .xlsx válido."
        else:
            wb = load_workbook(archivo, data_only=True)
            ws = wb.active
            headers = [str(c.value or "").strip().lower() for c in ws[1]]
            def val(row, names):
                for name in names:
                    if name in headers:
                        v = row[headers.index(name)].value
                        return str(v).strip() if v is not None else ""
                return ""
            creados = actualizados = saltados = 0
            for row in ws.iter_rows(min_row=2):
                codigo = val(row, ["codigo", "código", "cod"])
                if not codigo:
                    saltados += 1; continue
                e = Estudiante.query.filter_by(codigo=codigo).first()
                iid_imp = institucion_id_actual()
                if not e:
                    e = Estudiante(codigo=codigo, institucion_id=iid_imp)
                    db.session.add(e); creados += 1
                else:
                    # Solo actualizar si es del mismo colegio o está sin colegio
                    if iid_imp is not None and e.institucion_id is not None and int(e.institucion_id) != int(iid_imp):
                        saltados += 1
                        continue
                    e.institucion_id = iid_imp or e.institucion_id
                    actualizados += 1
                # Nombres: columnas simples o SIMAT (nombre1/apellido1)
                a1 = val(row, ["apellido1", "primer apellido", "primer_apellido"])
                a2 = val(row, ["apellido2", "segundo apellido", "segundo_apellido"])
                n1 = val(row, ["nombre1", "primer nombre", "primer_nombre"])
                n2 = val(row, ["nombre2", "segundo nombre", "segundo_nombre"])
                nombre = val(row, ["nombre", "nombres"])
                apellido = val(row, ["apellido", "apellidos"])
                if a1 or n1:
                    e.apellido1 = (a1 or "")[:80]
                    e.apellido2 = (a2 or "")[:80]
                    e.nombre1 = (n1 or "")[:80]
                    e.nombre2 = (n2 or "")[:80]
                    e.apellido = f"{a1} {a2}".strip()[:120] or apellido or "Sin apellido"
                    e.nombre = f"{n1} {n2}".strip()[:120] or nombre or "Sin nombre"
                else:
                    e.nombre = nombre or e.nombre or "Sin nombre"
                    e.apellido = apellido or e.apellido or "Sin apellido"
                    # rellenar desglose básico
                    parts_n = (e.nombre or "").split()
                    parts_a = (e.apellido or "").split()
                    e.nombre1 = (parts_n[0] if parts_n else "")[:80]
                    e.nombre2 = (" ".join(parts_n[1:]) if len(parts_n) > 1 else "")[:80]
                    e.apellido1 = (parts_a[0] if parts_a else "")[:80]
                    e.apellido2 = (" ".join(parts_a[1:]) if len(parts_a) > 1 else "")[:80]
                e.grado = val(row, ["grado"]) or e.grado or "11"
                e.grupo = val(row, ["grupo"]) or getattr(e, "grupo", "") or ""
                e.director = val(row, ["director", "director de grupo"]) or e.director or "Sin asignar"
                e.tipo_doc = val(row, ["tipo_doc", "tipo documento", "tipodoc"]) or getattr(e, "tipo_doc", None) or "TI"
                e.documento = val(row, ["documento", "nro_doc", "dni", "tarjeta", "ti"]) or e.documento
                e.exp_depa = val(row, ["exp_depa", "depto expedicion", "departamento expedicion"]) or getattr(e, "exp_depa", "") or ""
                e.exp_muni = val(row, ["exp_muni", "mpio expedicion", "municipio expedicion"]) or getattr(e, "exp_muni", "") or ""
                e.fecha_nacimiento = val(row, ["fecha_nacimiento", "fecha nac", "nacimiento"]) or getattr(e, "fecha_nacimiento", "") or ""
                e.genero = val(row, ["genero", "sexo"]) or getattr(e, "genero", "") or ""
                e.rh = val(row, ["rh", "sangre"]) or e.rh
