def eduaura_datos(periodo=None, rango_dias=30):
    periodo = periodo or periodo_actual()
    fecha_limite = (ahora() - timedelta(days=int(rango_dias))).strftime("%Y-%m-%d")
    estudiantes = q_estudiantes().order_by(Estudiante.grado.asc(), Estudiante.apellido.asc()).all()
    ids_est = [e.id for e in estudiantes]
    ingresos = q_ingresos().filter(IngresoPorteria.fecha >= fecha_limite).all()
    if ids_est:
        novedades = Novedad.query.filter(Novedad.fecha >= fecha_limite, Novedad.estudiante_id.in_(ids_est)).all()
        citaciones = Citacion.query.filter(Citacion.fecha_creacion >= fecha_limite, Citacion.estudiante_id.in_(ids_est)).all()
    else:
        novedades, citaciones = [], []
    fechas_actividad = sorted({i.fecha for i in ingresos})
    por_est = {}
    for e in estudiantes:
        regs = [i for i in ingresos if i.estudiante_id == e.id]
        tardes = sum(1 for i in regs if i.estado == "Tarde")
        no_llego_reg = sum(1 for i in regs if i.estado == "No llegó")
        fechas_e = {i.fecha for i in regs}
        aus_est = len([f for f in fechas_actividad if f not in fechas_e]) + no_llego_reg
        nov = [n for n in novedades if n.estudiante_id == e.id]
        cit = [c for c in citaciones if c.estudiante_id == e.id]
        score = min(100, tardes*8 + aus_est*14 + len(nov)*6 + len(cit)*12)
        if score >= 60:
            nivel, clase = "Alto", "risk-high"
        elif score >= 30:
            nivel, clase = "Medio", "risk-mid"
        else:
            nivel, clase = "Bajo", "risk-low"
        por_est[e.id] = {"e":e,"tardes":tardes,"ausencias":aus_est,"novedades":len(nov),"citaciones":len(cit),"score":score,"nivel":nivel,"clase":clase}
    total = len(estudiantes)
    registros = len(ingresos)
    tarde = sum(1 for i in ingresos if i.estado == "Tarde")
    temprano = sum(1 for i in ingresos if i.estado == "Temprano")
    tasa_puntualidad = round((temprano / registros) * 100, 1) if registros else 0
    criticos = sorted(por_est.values(), key=lambda x: x["score"], reverse=True)[:12]
    por_grado = {}
    for item in por_est.values():
        g = item["e"].grado
        por_grado.setdefault(g, {"est":0,"tardes":0,"aus":0,"score":0})
        por_grado[g]["est"] += 1
        por_grado[g]["tardes"] += item["tardes"]
        por_grado[g]["aus"] += item["ausencias"]
        por_grado[g]["score"] += item["score"]
    grados = sorted(por_grado.items(), key=lambda kv: kv[1]["score"], reverse=True)
    return {"periodo":periodo,"rango":rango_dias,"fecha_limite":fecha_limite,"estudiantes":estudiantes,"ingresos":ingresos,"novedades":novedades,"citaciones":citaciones,"por_est":por_est,"total":total,"registros":registros,"tarde":tarde,"temprano":temprano,"tasa_puntualidad":tasa_puntualidad,"criticos":criticos,"grados":grados,"dias_analizados":len(fechas_actividad)}

