@app.route("/eduaura/historial/<int:estudiante_id>")
def eduaura_historial(estudiante_id):
    if not requiere_login(): return redirect("/login")
    if rol_actual() not in ["Administrador", "Soporte", "Rectoría", "Coordinación", "Secretaría"]: return acceso_denegado()
    e = estudiante_del_tenant_or_404(estudiante_id)
    ingresos = IngresoPorteria.query.filter_by(estudiante_id=e.id).order_by(IngresoPorteria.fecha.desc(), IngresoPorteria.hora.desc()).limit(40).all()
    novedades = Novedad.query.filter_by(estudiante_id=e.id).order_by(Novedad.fecha.desc(), Novedad.hora.desc()).limit(30).all()
    citaciones = Citacion.query.filter_by(estudiante_id=e.id).order_by(Citacion.fecha_creacion.desc()).limit(20).all()
    tarde = sum(1 for i in ingresos if i.estado == "Tarde")
    temprano = sum(1 for i in ingresos if i.estado == "Temprano")
    no = sum(1 for i in ingresos if i.estado == "No llegó")
    score = min(100, tarde*8 + no*14 + len(novedades)*6 + len(citaciones)*12)
    nivel = "Alto" if score >= 60 else ("Medio" if score >= 30 else "Bajo")
    clase = "risk-high" if nivel == "Alto" else ("risk-mid" if nivel == "Medio" else "risk-low")
    rows_ing = ''.join(f"<tr><td>{i.fecha}</td><td>{i.hora}</td><td>{i.estado}</td><td>{i.registrado_por}</td></tr>" for i in ingresos)
    rows_nov = ''.join(f"<tr><td>{n.fecha}</td><td>{n.tipo}</td><td>{_esc(n.motivo)}</td><td>{n.estado}</td><td>{_esc(n.registrado_por)}</td></tr>" for n in novedades)
    rows_cit = ''.join(f"<tr><td>{c.fecha_creacion}</td><td>{c.fecha_citacion}</td><td>{_esc(c.motivo)}</td><td>{c.estado}</td><td>{_esc(c.generado_por)}</td></tr>" for c in citaciones)
    content = f"""
<section class='eduaura-hero'><span class='aura-badge'>Historial inteligente EduAura</span><h1>{estudiante_nombre(e)}</h1><p>Código {e.codigo} · Documento {e.documento or 'Sin documento'} · Grado {e.grado} · Acudiente {e.acudiente or 'No registrado'}</p></section>
<div class='role-cards'><div class='role-card green'><h3>{temprano}</h3><p>Temprano</p></div><div class='role-card yellow'><h3>{tarde}</h3><p>Tarde</p></div><div class='role-card red'><h3>{no}</h3><p>No llegó</p></div><div class='role-card purple'><h3><span class='{clase}'>{nivel}</span></h3><p>Índice EduAura {score}/100</p></div></div>
<section class='role-grid'><div class='role-panel'><h2>Ingresos recientes</h2><table><tr><th>Fecha</th><th>Hora</th><th>Estado</th><th>Reporta</th></tr>{rows_ing if rows_ing else '<tr><td colspan="4">Sin ingresos.</td></tr>'}</table></div><div class='role-panel'><h2>Novedades</h2><table><tr><th>Fecha</th><th>Tipo</th><th>Motivo</th><th>Estado</th><th>Reporta</th></tr>{rows_nov if rows_nov else '<tr><td colspan="5">Sin novedades.</td></tr>'}</table></div></section>
<section class='role-panel'><h2>Citaciones</h2><table><tr><th>Generada</th><th>Fecha citación</th><th>Motivo</th><th>Estado</th><th>Generado por</th></tr>{rows_cit if rows_cit else '<tr><td colspan="5">Sin citaciones.</td></tr>'}</table><br><a class='btn' href='/eduaura'>Volver a EduAura</a></section>
"""
    return page("Historial EduAura", shell(content))

