@app.route("/logout")
def logout():
    """Cierra sesión y devuelve al login del portal correcto (no mezcla paneles)."""
    rol = (session.get("rol") or "").strip()
    panel = (session.get("panel") or "").strip()
    session.clear()
    if panel == "ventas" or rol == "Comercial":
        return redirect("/ventas-login")
    if panel == "soporte" or rol == "Soporte":
        return redirect("/soporte-login")
    if panel == "cobranza" or rol == "Cobranza":
        return redirect("/cobranza-login")
    if panel == "gerencia" or rol in ("Gerente", "Superadmin", "Administrador"):
        return redirect("/gerencia-login")
    return redirect("/login")


def _usuario_actual_obj():
    """Objeto Usuario de la sesión actual (staff interno: soporte/ventas/gerencia), o None."""
    uid = session.get("uid")
    if not uid:
        return None
    try:
        return Usuario.query.get(int(uid))
    except Exception:
        return None


def nombre_mostrar_actual():
    """Nombre a mostrar del usuario logueado: nombre_completo si existe, si no el usuario de login."""
    u = _usuario_actual_obj()
    if u and (u.nombre_completo or "").strip():
        return u.nombre_completo.strip()
    return session.get("usuario") or ""


@app.route("/mi-perfil", methods=["GET", "POST"])
def mi_perfil():
    """Cambiar el nombre para mostrar (y opcionalmente el usuario de login) de cuentas internas
    de Soporte, Ventas y Gerencia — para que documentos y auditoría muestren su nombre real."""
    if not requiere_login() or rol_actual() not in ("Soporte", "Comercial", "Gerente", "Administrador", "Superadmin", "Cobranza"):
        return redirect("/login")
    u = _usuario_actual_obj()
    if not u:
        return acceso_denegado()
    mensaje = ""
    error = ""
    if request.method == "POST":
        nombre_completo = (request.form.get("nombre_completo") or "").strip()[:160]
        nuevo_usuario = (request.form.get("usuario") or "").strip()[:80]
        u.nombre_completo = nombre_completo
        if nuevo_usuario and nuevo_usuario != u.usuario:
            choque = Usuario.query.filter(Usuario.usuario == nuevo_usuario, Usuario.id != u.id).first()
            if choque:
                error = f'El usuario de acceso "{nuevo_usuario}" ya lo tiene otra cuenta.'
            else:
                anterior = u.usuario
                u.usuario = nuevo_usuario
                session["usuario"] = nuevo_usuario
                registrar_auditoria("Cambio de usuario de acceso", f"{anterior} → {nuevo_usuario}")
        if not error:
            db.session.commit()
            registrar_auditoria("Perfil actualizado", f"{u.usuario}: nombre a mostrar = {nombre_completo or '(vacío)'}")
            mensaje = "Datos guardados."
    volver = {"Soporte": "/soporte_admin", "Comercial": "/ventas/panel", "Gerente": "/gerencia/hq"}.get(rol_actual(), "/")
    content = f"""
<header class="role-hero"><div>
  <h1>👤 Mi perfil</h1>
  <p>Su nombre para mostrar aparece en boletines, contratos y auditoría en vez de su usuario de acceso.</p>
</div>
<a class="btn" href="{volver}">Volver</a></header>
{"<div class='msg ok'>"+mensaje+"</div>" if mensaje else ""}
{"<div class='msg err'>"+error+"</div>" if error else ""}
<section class="role-panel">
  <form method="POST">
    <label><b>Nombre para mostrar</b> (ej. "Laura Gómez")</label>
    <input name="nombre_completo" value="{_esc(u.nombre_completo)}" placeholder="Su nombre completo">
    <label style="margin-top:10px;display:block"><b>Usuario de acceso</b> (con el que inicia sesión)</label>
    <input name="usuario" value="{_esc(u.usuario)}">
    <p class="mini-text">Rol: <b>{_esc(u.rol)}</b> · Cambiar el usuario de acceso no borra su historial, solo cambia con qué texto entra al login.</p>
    <button type="submit" style="margin-top:12px">Guardar</button>
  </form>
</section>
"""
    return page("Mi perfil", shell(content))


def _guard_soporte():
    """True si OK; Response de redirect si no."""
    if not requiere_login():
        return redirect("/soporte-login")
    rol = rol_actual()
    # Portal Soporte SOLO para rol Soporte (y Superadmin emergencia).
    # Si hay otro rol logueado (misma pestaña o navegador), lo mandamos al LOGIN de
    # soporte (no de vuelta a su propio portal) para que pueda entrar con esas
    # credenciales si de verdad quiere cambiar de portal — así no se siente "atrapado"
    # en su rol actual al abrir otra pestaña.
    if rol in ("Cobranza", "Comercial", "Gerente", "Administrador"):
        return redirect("/soporte-login")
    if rol not in ("Soporte", "Superadmin"):
        return redirect("/soporte-login")
    # Soporte (rol exacto) tiene acceso a módulos operativos de soporte (tickets, usuarios,
    # base de conocimiento, permisos escolares, bugs, reset, impersonar). No elimina colegios
    # ni gestiona facturación/cobranza (eso es Gerencia / Cobranza).
    if rol == "Soporte":
        path = request.path or ""
        permitido = (
            path.startswith("/soporte")
            or path.startswith("/soporte_admin")
            or path.startswith("/mi-perfil")
            or path.startswith("/tenants")
            or path.startswith("/sedes")
            or path.startswith("/usuarios")
            or path.startswith("/auditoria")
            or path.startswith("/api/")
        )
        # Bloquear acciones destructivas de colegio y módulos de gerencia/cobranza/finanzas
        bloqueado = (
            path.startswith("/eliminar_institucion")
            or path.startswith("/gerencia")
            or path.startswith("/ventas/panel")
            or path.startswith("/ventas/comisiones")
            or path.startswith("/cobranza")
            or path.startswith("/soporte/licencias")
            or path.startswith("/soporte/cancelaciones")
            or path.startswith("/soporte/almacenamiento")
        )
        if bloqueado or not permitido:
            return acceso_denegado("Su cuenta de Soporte no tiene permiso para esta acción.")
    return None

def _guard_gerencia():
    if not requiere_login():
        return redirect("/gerencia-login")
    rol = rol_actual()
    if rol not in ("Gerente", "Superadmin", "Administrador"):
        # Igual que en Soporte: mandar al LOGIN del portal que se intenta abrir, no de
        # vuelta al portal actual — así se puede cambiar de rol abriendo otra pestaña.
        return redirect("/gerencia-login")
    return None

