# Modelos con datos académicos/operativos por colegio que se vacían en el reinicio de datos.
# NO incluye: Usuario (logins), Institucion (registro de colegios), Configuracion, Plataforma,
# FeatureFlag, PlanComercial/AddonComercial, DocumentoCorp (documentos legales), LiderEmpresa,
# DirectorioMEN (catálogo de referencia).
_MODELOS_RESET_DATOS = [
    Estudiante, ConsentimientoHabeas, IngresoPorteria, AsistenciaClase, Excusa, Recuperacion,
    Asignatura, DirectorGrupo, HorarioBloque, AsignacionDocente, HistorialPQR, TicketPQR,
    SolicitudCancelacion, SieeDimension, SieeCriterio, NotaRegistro, FaltaPlanilla,
    AnotacionEstudiante, FaltaConvivencia, HistorialMatricula, LogroAcademico, RefuerzoAcademico,
    InventarioItem, ActividadAsignada, EntregaEstudiante, EntregaArchivo, LogAuditoriaNota,
    CierrePeriodo, ObservacionBoletin, CertificadoEstudio, LeadCRM, DemoColegio, LogErrorSistema,
    InvitacionDemo, MetaVendedor, GastoOperativo, FacturaCobro, NotaInteraccion, CasoRetencion,
    LoginChallenge, AccesoExtraordinario, SesionEmpleado, Novedad, Citacion, PreMatricula,
    Auditoria,
]


@app.route("/gerencia/reinicio-datos", methods=["GET", "POST"])
def gerencia_reinicio_datos():
    """Botón de reinicio: vacía datos académicos/operativos de TODOS los colegios antes del lanzamiento
    público. No borra cuentas de acceso (Usuario), el registro de colegios (Institucion) ni la
    configuración/documentos legales de la plataforma. Solo Gerente/Superadmin, con frase de confirmación."""
    rol = (rol_actual() or "").strip()
    if not requiere_login() or rol not in ("Gerente", "Superadmin"):
        return redirect("/gerencia-login")
    FRASE = "ELIMINAR TODO"
    mensaje = ""
    error = ""
    if request.method == "POST":
        confirmar = (request.form.get("confirmar") or "").strip()
        if confirmar != FRASE:
            error = f'Debe escribir exactamente "{FRASE}" para confirmar. No se borró nada.'
        else:
            try:
                total = 0
                for modelo in _MODELOS_RESET_DATOS:
                    total += modelo.query.delete(synchronize_session=False)
                db.session.commit()
                try:
                    registrar_auditoria(
                        "REINICIO DE DATOS (gerencia)",
                        f"{session.get('usuario') or rol}: {total} registros eliminados en {len(_MODELOS_RESET_DATOS)} tablas",
                    )
                except Exception:
                    pass
                mensaje = f"Listo: se eliminaron {total} registros académicos/operativos de todos los colegios. Cuentas, colegios registrados, configuración y documentos legales NO se tocaron."
            except Exception as ex:
                db.session.rollback()
                error = f"No se pudo completar el reinicio: {ex}"
    content = f"""
<header class="role-hero"><div>
  <h1>⚠ Reinicio de datos · Gerencia</h1>
  <p>Vacía la información académica y operativa de <b>todos</b> los colegios (estudiantes, notas, asistencia, PQR,
  facturas, inventario, etc.) para dejar la plataforma lista antes de salir al público.</p>
</div>
<a class="btn" href="/gerencia/hq">Volver</a></header>
{"<div class='msg ok'>"+mensaje+"</div>" if mensaje else ""}
{"<div class='msg err'>"+error+"</div>" if error else ""}
<section class="role-panel">
  <h2 style="color:#b91c1c">Esta acción es irreversible</h2>
  <p class="mini-text">Se eliminan permanentemente los registros de estas {len(_MODELOS_RESET_DATOS)} tablas para
  todos los colegios: estudiantes, matrículas, notas, asistencia, excusas, PQR, cancelaciones, inventario,
  actividades/entregas, facturación, gastos, CRM/leads, sesiones y auditoría de pruebas.</p>
  <p class="mini-text"><b>NO se eliminan:</b> usuarios y contraseñas (logins), el registro de colegios (Institución),
  configuración de la plataforma, planes comerciales ni la biblioteca de documentos legales/corporativos.</p>
  <form method="POST" style="margin-top:14px">
    <label><b>Para confirmar, escriba exactamente:</b> <code>{FRASE}</code></label>
    <input name="confirmar" placeholder="{FRASE}" autocomplete="off">
    <button type="submit" style="background:#b91c1c;margin-top:10px">Eliminar toda la información académica/operativa</button>
  </form>
</section>
"""
    return page("Reinicio de datos", content)


