def _seed_documentos_corp():
    try:
        db.create_all()
    except Exception:
        pass
    for d in _catalogo_documentos_corp():
        row = DocumentoCorp.query.filter_by(clave=d["clave"]).first()
        if not row:
            row = DocumentoCorp(
                clave=d["clave"],
                titulo=d["titulo"],
                cuerpo_html=d["cuerpo"],
                publico=bool(d.get("publico")),
                categoria=d.get("categoria") or "interno",
                actualizado_en=f"{fecha_hoy()} {hora_actual()}",
                actualizado_por="sistema",
            )
            db.session.add(row)
    try:
        db.session.commit()
    except Exception:
        db.session.rollback()


def _doc_html_to_plain_lines(html_body):
    """
    HTML del editor → líneas con párrafos separados.
    Negrita del editor se marca con [[B]]...[[/B]] para PDF/PNG.
    """
    import re
    import html as html_mod
    text = html_body or ""
    # Negrita / strong → marcadores (antes de quitar tags)
    text = re.sub(
        r"<\s*(?:b|strong)(?:\s[^>]*)?>(.*?)</\s*(?:b|strong)\s*>",
        lambda m: "[[B]]" + m.group(1) + "[[/B]]",
        text,
        flags=re.I | re.S,
    )
    text = re.sub(
        r'<\s*span[^>]*font-weight\s*:\s*(?:bold|700|800|900)[^>]*>(.*?)</\s*span\s*>',
        lambda m: "[[B]]" + m.group(1) + "[[/B]]",
        text,
        flags=re.I | re.S,
    )
    text = re.sub(r"<\s*br\s*/?\s*>", "\n", text, flags=re.I)
    text = re.sub(r"</\s*p\s*>", "\n\n", text, flags=re.I)
    text = re.sub(r"<\s*p[^>]*>", "", text, flags=re.I)
    text = re.sub(r"</\s*div\s*>", "\n\n", text, flags=re.I)
    text = re.sub(r"<\s*div[^>]*>", "", text, flags=re.I)
    text = re.sub(r"</\s*h1\s*>", "\n\n", text, flags=re.I)
    text = re.sub(r"<\s*h1[^>]*>", "\n# ", text, flags=re.I)
    text = re.sub(r"</\s*h2\s*>", "\n\n", text, flags=re.I)
    text = re.sub(r"<\s*h2[^>]*>", "\n## ", text, flags=re.I)
    text = re.sub(r"</\s*h3\s*>", "\n\n", text, flags=re.I)
    text = re.sub(r"<\s*h3[^>]*>", "\n## ", text, flags=re.I)
    text = re.sub(r"</\s*li\s*>", "\n", text, flags=re.I)
    text = re.sub(r"<\s*li[^>]*>", "• ", text, flags=re.I)
    text = re.sub(r"</\s*(ul|ol)\s*>", "\n\n", text, flags=re.I)
    text = re.sub(r"<\s*(ul|ol)[^>]*>", "\n", text, flags=re.I)
    text = re.sub(r"<[^>]+>", "", text)
    try:
        text = html_mod.unescape(text)
    except Exception:
        text = text.replace("&nbsp;", " ").replace("&amp;", "&").replace("&lt;", "<").replace("&gt;", ">")
    # Reparar mojibake frecuente si el texto ya venía mal
    for bad, good in (
        ("Ã¡", "á"), ("Ã©", "é"), ("Ã­", "í"), ("Ã³", "ó"), ("Ãº", "ú"),
        ("Ã±", "ñ"), ("Ã‘", "Ñ"), ("Â", ""), ("�", ""),
    ):
        text = text.replace(bad, good)
    text = text.replace("\r\n", "\n").replace("\r", "\n")
    text = re.sub(r"[ \t]+\n", "\n", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    lines = [ln.strip() for ln in text.split("\n")]
    rebuilt = []
    for ln in lines:
        if not ln:
            rebuilt.append("")
            continue
        one = ln
        # Fecha…Lugar pegados (con o sin acentos)
        one = re.sub(
            r"(publicaci[oó]?n\s*:\s*[^\n]*?20\d{2})\s*(Lugar\s*:)",
            r"\1\n\n\2",
            one,
            flags=re.I,
        )
        one = re.sub(r"(20\d{2})\s*(Lugar\s*:)", r"\1\n\n\2", one, flags=re.I)
        one = re.sub(r"(20\d{2})(Lugar\s*:)", r"\1\n\n\2", one, flags=re.I)
        # Firma: NOMBRE + cargo pegados (con o sin acentos / caracteres raros)
        one = re.sub(
            r"(L[OÓ]PEZ|Lopez|López)(\s*)(Fundador|Directora|Director|Gerente)",
            r"\1\n\n\3",
            one,
            flags=re.I,
        )
        one = re.sub(
            r"([A-ZÁÉÍÓÚÑ][A-ZÁÉÍÓÚÑ\s\.]{2,50}?)(Fundador|Directora|Director|Gerente|Y todo el equipo)",
            r"\1\n\n\2",
            one,
        )
        one = re.sub(
            r"(Fundador[^\n]{0,100}?)(Y todo el equipo)",
            r"\1\n\n\2",
            one,
            flags=re.I,
        )
        one = re.sub(
            r"(PROCSIS)\s*[–\-—]?\s*(Innovaci)",
            r"\1 — \2",
            one,
            flags=re.I,
        )
        for marker in (
            "Asunto:", "Fecha de publicación:", "Fecha de publicacion:", "Fecha:",
            "Lugar:", "Atentamente,", "Atentamente.",
            "Hoy queremos", "En nombre de", "Sabemos perfectamente",
            "Acompañamos", "Con todo nuestro",
        ):
            pos = one.find(marker)
            # No partir si el marcador está justo después de [[B]] (negrita del editor)
            if pos > 0 and not one[max(0, pos - 5):pos].endswith("[[B]]"):
                # solo partir si no hay ya salto
                if "\n" not in one[:pos][-2:]:
                    one = one[:pos] + "\n\n" + one[pos:]
        # No partir dentro de marcadores de negrita
        def _split_sentences(s):
            out = []
            i = 0
            while i < len(s):
                if s.startswith("[[B]]", i):
                    j = s.find("[[/B]]", i)
                    if j < 0:
                        out.append(s[i:])
                        break
                    out.append(s[i:j + 6])
                    i = j + 6
                    continue
                j = i
                while j < len(s):
                    if s.startswith("[[B]]", j):
                        break
                    if s[j] == "." and j + 1 < len(s) and s[j + 1] in " \t" and j + 2 < len(s) and s[j + 2].isupper():
                        out.append(s[i:j + 1])
                        out.append("\n\n")
                        i = j + 1
                        while i < len(s) and s[i] in " \t":
                            i += 1
                        j = i
                        continue
                    j += 1
                else:
                    out.append(s[i:])
                    break
                if j > i and j < len(s) and s.startswith("[[B]]", j):
                    out.append(s[i:j])
                    i = j
            return "".join(out)
        one = _split_sentences(one)
        for part in one.split("\n"):
            rebuilt.append(part.strip())
    out, empty_run = [], 0
    for ln in rebuilt:
        if not ln:
            empty_run += 1
            if empty_run <= 2:
                out.append("")
        else:
            empty_run = 0
            out.append(ln)
    return out


def _doc_line_is_bold(line):
    """True si la línea va en negrita (marcadores o estilo firma/meta)."""
    if not line:
        return False
    if "[[B]]" in line:
        return True
    low = line.lower()
    if low.startswith(("asunto:", "fecha", "lugar:", "atentamente")):
        return True
    if line.startswith(("# ", "## ")):
        return True
    # Nombre en mayúsculas corto = firma
    plain = line.replace("[[B]]", "").replace("[[/B]]", "").strip()
    if plain.isupper() and 3 < len(plain) < 55:
        return True
    return False


def _doc_strip_bold_marks(line):
    return (line or "").replace("[[B]]", "").replace("[[/B]]", "")


def _resolve_logo_filesystem():
    """Ruta de archivo local del logo de empresa para PDF/PNG."""
    import os
    logo_url = ""
    try:
        logo_url = logo_plataforma() or ""
    except Exception:
        logo_url = ""
    candidates = []
    if logo_url and not str(logo_url).startswith("data:"):
        path = str(logo_url).split("?")[0]
        if path.startswith("/static/"):
            candidates.append(os.path.join(app.root_path, path.lstrip("/")))
            candidates.append(os.path.join(os.getcwd(), path.lstrip("/")))
        elif path.startswith("static/"):
            candidates.append(os.path.join(app.root_path, path))
    for d in (
        "static/img/logo-edutrack.png",
        "static/img/logo-procsis.png",
        "static/logo.png",
        "static/uploads/logo_plataforma.png",
    ):
        candidates.append(os.path.join(app.root_path, d))
        candidates.append(os.path.join(os.getcwd(), d))
    for c in candidates:
        try:
            if c and os.path.isfile(c):
                return c
        except Exception:
            pass
    return None


def _doc_font_paths():
    """Fuentes con acentos: fonts_data.py embebido > static > /tmp > descarga."""
    import os
    import tempfile
    import base64
    import zlib

    tmp = os.path.join(tempfile.gettempdir(), "edutrack_fonts")
    r_tmp = os.path.join(tmp, "DejaVuSans.ttf")
    b_tmp = os.path.join(tmp, "DejaVuSans-Bold.ttf")
    if os.path.isfile(r_tmp) and os.path.isfile(b_tmp) and os.path.getsize(r_tmp) > 10000:
        return r_tmp, b_tmp

    # 1) Módulo embebido (viaja siempre junto a app.py / fonts_data.py)
    try:
        import fonts_data
        os.makedirs(tmp, exist_ok=True)
        open(r_tmp, "wb").write(zlib.decompress(base64.b64decode(fonts_data.FONT_REGULAR_B64)))
        open(b_tmp, "wb").write(zlib.decompress(base64.b64decode(fonts_data.FONT_BOLD_B64)))
        if os.path.isfile(r_tmp) and os.path.getsize(r_tmp) > 10000:
            return r_tmp, b_tmp
    except Exception:
        pass

    here = os.path.dirname(os.path.abspath(__file__))
    roots = [here, getattr(app, "root_path", "") or "", os.getcwd()]
    pairs = []
    for root in roots:
        if not root:
            continue
        pairs.append((
            os.path.join(root, "static", "fonts", "DejaVuSans.ttf"),
            os.path.join(root, "static", "fonts", "DejaVuSans-Bold.ttf"),
        ))
        pairs.append((os.path.join(root, "DejaVuSans.ttf"), os.path.join(root, "DejaVuSans-Bold.ttf")))
    pairs.extend([
        ("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
         "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf"),
    ])
    for r, b in pairs:
        if os.path.isfile(r) and os.path.isfile(b) and os.path.getsize(r) > 10000:
            return r, b

    # b64.txt en static/fonts
    try:
        os.makedirs(tmp, exist_ok=True)
        for root in roots:
            if not root:
                continue
            br = os.path.join(root, "static", "fonts", "DejaVuSans.ttf.b64.txt")
            bb = os.path.join(root, "static", "fonts", "DejaVuSans-Bold.ttf.b64.txt")
            if os.path.isfile(br) and os.path.isfile(bb):
                open(r_tmp, "wb").write(zlib.decompress(base64.b64decode(open(br).read().strip())))
                open(b_tmp, "wb").write(zlib.decompress(base64.b64decode(open(bb).read().strip())))
                return r_tmp, b_tmp
    except Exception:
        pass

    try:
        import urllib.request
        os.makedirs(tmp, exist_ok=True)
        for name, url in {
            "DejaVuSans.ttf": "https://github.com/dejavu-fonts/dejavu-fonts/raw/version_2_37/ttf/DejaVuSans.ttf",
            "DejaVuSans-Bold.ttf": "https://github.com/dejavu-fonts/dejavu-fonts/raw/version_2_37/ttf/DejaVuSans-Bold.ttf",
        }.items():
            dest = os.path.join(tmp, name)
            if not os.path.isfile(dest) or os.path.getsize(dest) < 10000:
                urllib.request.urlretrieve(url, dest)
        if os.path.isfile(r_tmp) and os.path.getsize(r_tmp) > 10000:
            return r_tmp, b_tmp
    except Exception:
        pass
    return None, None


def _doc_register_fonts():
    """Fuentes con acentos españoles (Helvetica NO soporta áéíóúñ)."""
    from reportlab.pdfbase import pdfmetrics
    from reportlab.pdfbase.ttfonts import TTFont
    path_r, path_b = _doc_font_paths()
    if path_r and path_b:
        try:
            if "DocSans" not in pdfmetrics.getRegisteredFontNames():
                pdfmetrics.registerFont(TTFont("DocSans", path_r))
                pdfmetrics.registerFont(TTFont("DocSans-Bold", path_b))
            return "DocSans", "DocSans-Bold"
        except Exception:
            pass
    return "Helvetica", "Helvetica-Bold"


def _doc_pdf_bytes(titulo, html_body, confidencial=True):
    """PDF corporativo con acentos correctos, párrafos y firma legible en móvil."""
    import io
    from reportlab.lib.pagesizes import letter
    from reportlab.pdfgen import canvas as pdf_canvas
    from reportlab.lib.units import cm
    from reportlab.lib.utils import simpleSplit, ImageReader

    font_r, font_b = _doc_register_fonts()
    buf = io.BytesIO()
    c = pdf_canvas.Canvas(buf, pagesize=letter)
    w, h = letter
    margin = 2.0 * cm
    navy = (0.043, 0.176, 0.341)
    gray = (0.35, 0.40, 0.45)

    def header_block(y0):
        y = y0
        logo_path = _resolve_logo_filesystem()
        if logo_path:
            try:
                c.drawImage(ImageReader(logo_path), margin, y - 40, width=46, height=46, mask="auto", preserveAspectRatio=True)
            except Exception:
                pass
        c.setFillColorRGB(*navy)
        c.setFont(font_b, 11)
        c.drawString(margin + 56, y - 10, "PROCSIS")
        c.setFont(font_r, 8)
        c.setFillColorRGB(*gray)
        c.drawString(margin + 56, y - 24, "DOCUMENTO CORPORATIVO · EDUTRACK")
        c.setFillColorRGB(*navy)
        c.setFont(font_r, 9)
        c.drawRightString(w - margin, y - 10, "Colombia")
        c.setFont(font_r, 8)
        c.setFillColorRGB(*gray)
        tipo = "CONFIDENCIAL" if confidencial else "DOCUMENTO PÚBLICO"
        c.drawRightString(w - margin, y - 24, f"{tipo} · {fecha_hoy()}")
        y -= 56
        c.setStrokeColorRGB(*navy)
        c.setLineWidth(2.4)
        c.line(margin, y, w - margin, y)
        return y - 26

    y = header_block(h - 1.3 * cm)
    c.setFillColorRGB(*navy)
    c.setFont(font_b, 18)
    for line in simpleSplit((titulo or "DOCUMENTO").upper(), font_b, 18, w - 2 * margin):
        c.drawString(margin, y, line)
        y -= 24
    y -= 8
    c.setStrokeColorRGB(0.85, 0.88, 0.92)
    c.setLineWidth(0.9)
    c.line(margin, y, w - margin, y)
    y -= 20

    lines = _doc_html_to_plain_lines(html_body)
    for line in lines:
        if not line:
            y -= 16
            continue
        plain = _doc_strip_bold_marks(line)
        low = plain.lower()
        is_meta = low.startswith(("asunto:", "fecha", "lugar:", "atentamente"))
        is_sign_name = plain.isupper() and 3 < len(plain) < 55
        is_sign_role = low.startswith(("fundador", "director", "dirección", "direccion", "y todo el equipo", "gerente"))
        use_bold = _doc_line_is_bold(line) or is_meta or is_sign_name
        if plain.startswith("# "):
            y -= 12
            c.setFillColorRGB(*navy)
            content, size, font = plain[2:], 14, font_b
        elif plain.startswith("## "):
            y -= 14
            c.setFillColorRGB(*navy)
            content, size, font = plain[3:], 13, font_b
        elif is_meta or is_sign_name:
            c.setFillColorRGB(*navy)
            content, size, font = plain, 13 if is_sign_name else 12, font_b
        elif is_sign_role:
            c.setFillColorRGB(*gray)
            content, size, font = plain, 11, font_r
        else:
            c.setFillColorRGB(0.12, 0.16, 0.22)
            content, size, font = plain, 12, (font_b if use_bold else font_r)
        c.setFont(font, size)
        for chunk in simpleSplit(content, font, size, w - 2 * margin):
            if y < margin + 44:
                c.showPage()
                y = header_block(h - 1.3 * cm)
                c.setFont(font, size)
            c.drawString(margin, y, chunk)
            y -= size + 7
        # Firma: menos espacio entre nombre y cargos
        y -= 4 if is_sign_name or is_sign_role else 10

    c.setFont(font_r, 8)
    c.setFillColorRGB(*gray)
    c.drawString(margin, 1.15 * cm, "PROCSIS — Innovación que gestiona · EduTrack")
    c.drawRightString(w - margin, 1.15 * cm, "Dirección General y Gerencia HQ")
    c.save()
    buf.seek(0)
    return buf.read()


def _doc_png_bytes(titulo, html_body, confidencial=True):
    """
    PNG compacto tipo comunicado (2ª foto del usuario):
    poco espacio entre párrafos, legible en celular, acentos con DejaVu embebida.
    """
    import io
    import os
    from PIL import Image, ImageDraw, ImageFont

    # Ancho tipo pantalla de celular (2x para nitidez)
    W = 900
    margin = 40
    black = (25, 25, 25)
    gray = (90, 90, 90)
    navy = (11, 45, 87)
    bg = (255, 255, 255)

    path_r, path_b = _doc_font_paths()
    if not path_r:
        # Sin fuente Unicode la imagen sale ilegible: avisar en la propia imagen
        img = Image.new("RGB", (W, 200), bg)
        d = ImageDraw.Draw(img)
        d.text((20, 80), "Error: no se encontraron fuentes. Suba el ZIP completo (static/fonts).", fill=(180, 0, 0))
        out = io.BytesIO()
        img.save(out, format="PNG")
        out.seek(0)
        return out.read()

    def font(size, bold=False):
        path = path_b if bold else path_r
        return ImageFont.truetype(path, size)

    f_logo = font(13, True)
    f_logo_sub = font(10)
    f_title = font(20, True)
    f_meta = font(13, True)
    f_body = font(14)
    f_body_b = font(14, True)
    f_sign = font(15, True)
    f_role = font(13)
    f_foot = font(10)

    lines = _doc_html_to_plain_lines(html_body)
    skip_prefixes = (
        "procsis — documento", "procsis - documento", "procsis – documento",
        "procsis documento corporativo",
        "documento corporativo / opinión", "documento corporativo / opinion",
    )
    clean = []
    for ln in lines:
        plain = _doc_strip_bold_marks(ln).strip()
        if plain and plain.lower().startswith(skip_prefixes):
            continue
        clean.append(ln)
    lines = clean

    # altura compacta
    est = 180 + sum(22 + (len(_doc_strip_bold_marks(L)) // 55) * 20 for L in lines if L) + 60
    H = max(1100, min(est, 5000))
    img = Image.new("RGB", (W, H), bg)
    d = ImageDraw.Draw(img)
    y = margin
    max_w = W - 2 * margin

    logo_path = _resolve_logo_filesystem()
    if logo_path:
        try:
            logo = Image.open(logo_path).convert("RGBA")
            logo.thumbnail((52, 52))
            img.paste(logo, (margin, y), logo if logo.mode == "RGBA" else None)
            d.text((margin + 60, y + 8), "PROCSIS", fill=navy, font=f_logo)
            d.text((margin + 60, y + 26), "EduTrack · Colombia", fill=gray, font=f_logo_sub)
            y += 60
        except Exception:
            d.text((margin, y), "PROCSIS", fill=navy, font=f_logo)
            y += 28
    else:
        d.text((margin, y), "PROCSIS", fill=navy, font=f_logo)
        y += 28

    y += 12
    # Título centrado
    title = (titulo or "COMUNICADO").strip().upper()
    words = title.split()
    cur = ""
    for w_ in words:
        test = (cur + " " + w_).strip()
        if d.textlength(test, font=f_title) > max_w:
            if cur:
                tw = d.textlength(cur, font=f_title)
                d.text(((W - tw) / 2, y), cur, fill=black, font=f_title)
                y += 26
            cur = w_
        else:
            cur = test
    if cur:
        tw = d.textlength(cur, font=f_title)
        d.text(((W - tw) / 2, y), cur, fill=black, font=f_title)
        y += 26
    y += 16  # poco aire bajo el título

    def wrap_draw(text, fnt, fill, leading, extra_after=6):
        nonlocal y
        words = text.split()
        cur = ""
        for w_ in words:
            test = (cur + " " + w_).strip()
            if d.textlength(test, font=fnt) > max_w:
                d.text((margin, y), cur, fill=fill, font=fnt)
                y += leading
                cur = w_
            else:
                cur = test
        if cur:
            d.text((margin, y), cur, fill=fill, font=fnt)
            y += leading
        y += extra_after

    for line in lines:
        if y > H - 80:
            break
        if not line:
            y += 4  # casi sin hueco por líneas vacías
            continue
        plain = _doc_strip_bold_marks(line).strip()
        if not plain:
            y += 4
            continue
        low = plain.lower()
        is_meta = low.startswith(("asunto:", "fecha", "lugar:", "atentamente", "bogotá", "bogota", "caracolí", "caracoli"))
        is_sign_name = plain.isupper() and 3 < len(plain) < 55
        is_sign_role = low.startswith(("fundador", "director", "dirección", "direccion", "y todo el equipo", "gerente"))
        use_bold = _doc_line_is_bold(line)

        if plain.startswith("# "):
            wrap_draw(plain[2:], f_title, black, 24, 8)
        elif plain.startswith("## "):
            wrap_draw(plain[3:], f_body_b, black, 22, 6)
        elif is_meta:
            wrap_draw(plain, f_meta, navy, 20, 4)
        elif is_sign_name:
            y += 8
            wrap_draw(plain, f_sign, black, 22, 2)
        elif is_sign_role:
            wrap_draw(plain, f_role, gray, 20, 2)
        else:
            # cuerpo: interlineado 20, poco espacio entre párrafos (como 2ª foto)
            wrap_draw(plain, f_body_b if use_bold else f_body, black, 20, 8)

    y += 12
    d.line([(margin, y), (W - margin, y)], fill=(220, 220, 220), width=1)
    y += 10
    d.text((margin, y), "PROCSIS — Innovación que gestiona · EduTrack", fill=gray, font=f_foot)
    y += 28

    img = img.crop((0, 0, W, min(H, y + 12)))
    out = io.BytesIO()
    img.save(out, format="PNG", optimize=True)
    out.seek(0)
    return out.read()


def _doc_extract_lugar(html_body, default="Colombia"):
    """Toma el lugar del texto del editor (Lugar: ...)."""
    import re
    plain = _doc_html_to_plain_lines(html_body or "")
    for ln in plain:
        s = _doc_strip_bold_marks(ln).strip()
        m = re.match(r"^Lugar\s*:\s*(.+)$", s, flags=re.I)
        if m:
            val = m.group(1).strip()
            if val:
                return val[:120]
    return default


