def _doc_word_bytes(titulo, html_body, confidencial=True, lugar=None):
    """Exporta documento corporativo a Word (.docx)."""
    import io
    from docx import Document
    from docx.shared import Pt, RGBColor, Inches
    from docx.enum.text import WD_ALIGN_PARAGRAPH

    lugar = lugar or _doc_extract_lugar(html_body, "Colombia")
    doc = Document()
    # Márgenes
    for section in doc.sections:
        section.top_margin = Inches(0.7)
        section.bottom_margin = Inches(0.7)
        section.left_margin = Inches(0.85)
        section.right_margin = Inches(0.85)

    navy = RGBColor(0x0B, 0x2D, 0x57)
    cyan = RGBColor(0x00, 0xA3, 0xE0)

    p = doc.add_paragraph()
    r = p.add_run("PROCSIS")
    r.bold = True
    r.font.size = Pt(14)
    r.font.color.rgb = navy
    p2 = doc.add_paragraph()
    r2 = p2.add_run("DOCUMENTO CORPORATIVO · EDUTRACK")
    r2.font.size = Pt(9)
    r2.font.color.rgb = navy

    badge = doc.add_paragraph()
    rb = badge.add_run(
        "DOCUMENTO CONFIDENCIAL" if confidencial else f"DOCUMENTO PÚBLICO · {fecha_hoy()}"
    )
    rb.bold = True
    rb.font.size = Pt(10)
    rb.font.color.rgb = RGBColor(0xB9, 0x1C, 0x1C) if confidencial else cyan

    t = doc.add_paragraph()
    t.alignment = WD_ALIGN_PARAGRAPH.LEFT
    rt = t.add_run((titulo or "DOCUMENTO").upper())
    rt.bold = True
    rt.font.size = Pt(18)
    rt.font.color.rgb = navy

    meta = doc.add_paragraph()
    rm = meta.add_run(f"Fecha de publicación: {fecha_hoy()}  |  Lugar: {lugar}")
    rm.font.size = Pt(10)
    rm.font.color.rgb = RGBColor(0x33, 0x41, 0x55)

    k = doc.add_paragraph()
    rk = k.add_run(
        "PROCSIS — DOCUMENTO CORPORATIVO / "
        + ("CONFIDENCIAL" if confidencial else "OPINIÓN PÚBLICA")
    )
    rk.bold = True
    rk.font.size = Pt(10)
    rk.font.color.rgb = navy

    for line in _doc_html_to_plain_lines(html_body or ""):
        plain = _doc_strip_bold_marks(line).strip()
        if not plain:
            doc.add_paragraph("")
            continue
        # no repetir bloque de lugar/fecha del cuerpo si ya va en meta
        low = plain.lower()
        if low.startswith(("lugar:", "fecha de publicación:", "fecha de publicacion:")):
            continue
        if plain.upper().startswith("PROCSIS — DOCUMENTO") or plain.upper().startswith("PROCSIS - DOCUMENTO"):
            continue
        para = doc.add_paragraph()
        run = para.add_run(plain)
        run.font.size = Pt(11)
        if _doc_line_is_bold(line) or plain.isupper() and len(plain) < 55:
            run.bold = True
            run.font.color.rgb = navy

    doc.add_paragraph("")
    s = doc.add_paragraph()
    rs = s.add_run("Con visión, tecnología y compromiso,")
    rs.bold = True
    rs.font.color.rgb = navy
    n = doc.add_paragraph()
    rn = n.add_run("Sebastián López")
    rn.italic = True
    rn.bold = True
    rn.font.size = Pt(14)
    rn.font.color.rgb = navy
    doc.add_paragraph("Fundador y Dirección General")
    foot = doc.add_paragraph()
    rf = foot.add_run("Y todo el equipo de PROCSIS – Innovación que gestiona")
    rf.font.size = Pt(10)
    rf.font.color.rgb = RGBColor(0x64, 0x74, 0x8B)

    buf = io.BytesIO()
    doc.save(buf)
    buf.seek(0)
    return buf.read()


