def _logo_as_data_uri():
    """Logo en base64 para que html2canvas no se cuelgue por CORS."""
    import os
    import base64
    candidates = []
    try:
        src = logo_plataforma() or ""
        if str(src).startswith("data:"):
            return src
        p = str(src).split("?")[0]
        if p.startswith("/"):
            p = p.lstrip("/")
        candidates.append(os.path.join(app.root_path, p))
        candidates.append(os.path.join(os.getcwd(), p))
    except Exception:
        pass
    here = os.path.dirname(os.path.abspath(__file__))
    for rel in (
        "static/img/logo-edutrack.jpeg",
        "static/img/logo-edutrack.png",
        "static/img/logo-procsis.png",
    ):
        candidates.append(os.path.join(here, rel))
        try:
            candidates.append(os.path.join(app.root_path, rel))
        except Exception:
            pass
    for p in candidates:
        try:
            if p and os.path.isfile(p):
                raw = open(p, "rb").read()
                ext = p.lower().rsplit(".", 1)[-1]
                mime = "image/jpeg" if ext in ("jpg", "jpeg") else "image/png"
                return "data:%s;base64,%s" % (mime, base64.b64encode(raw).decode("ascii"))
        except Exception:
            continue
    return ""


@app.route("/gerencia/documentos/<clave>/imagen")
def gerencia_documento_imagen(clave):
    """Página de captura + botón de descarga directa del servidor."""
    _g = _guard_gerencia()
    if _g is not None:
        return _g
    row = DocumentoCorp.query.filter_by(clave=clave).first_or_404()
    logo_src = _logo_as_data_uri() or "/static/img/logo-edutrack.jpeg"
    shell = _doc_corp_shell_html(
        row.titulo,
        row.cuerpo_html or "",
        logo_src,
        confidencial=not bool(row.publico),
        fecha=(row.actualizado_en or fecha_hoy())[:10] if row.actualizado_en else fecha_hoy(),
    )
    html_doc = f"""<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{row.titulo or 'Documento'}</title>
<script src="https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js" crossorigin="anonymous"></script>
<style>
  body {{ margin: 0; background: #e8eef5; }}
  .bar {{ max-width: 720px; margin: 0 auto; padding: 12px 14px; display: flex; gap: 8px; flex-wrap: wrap; align-items: center; font-family: Segoe UI, system-ui, sans-serif; }}
  .bar button, .bar a {{
    background: #0B2D57; color: #fff; border: 0; padding: 10px 16px; border-radius: 8px;
    font-weight: 700; font-size: 14px; cursor: pointer; text-decoration: none; display: inline-block;
  }}
  .bar button.green {{ background: #15803d; }}
  .bar a.teal {{ background: #0f766e; }}
  .bar a.gray {{ background: #64748b; }}
  #msg {{ font-size: 13px; color: #475569; flex: 1; min-width: 140px; }}
  .wrap {{ max-width: 720px; margin: 0 auto 32px; padding: 0 8px; }}
</style>
</head>
<body>
  <div class="bar">
    <button type="button" class="green" id="btnDl">Descargar imagen PNG</button>
    <a class="teal" id="btnDirect" href="/gerencia/documentos/{clave}/imagen.png">Descarga directa (recomendada)</a>
    <a class="gray" href="/gerencia/documentos/{clave}">← Editor</a>
    <a href="/gerencia/documentos/{clave}/pdf">PDF</a>
    <span id="msg">Si el verde se queda en «Generando…», usa el botón turquesa.</span>
  </div>
  <div class="wrap">{shell}</div>
  <script>
  (function() {{
    var btn = document.getElementById('btnDl');
    var msg = document.getElementById('msg');
    var busy = false;
    function done(t) {{ busy = false; btn.disabled = false; msg.textContent = t; }}
    btn.addEventListener('click', function() {{
      if (busy) return;
      if (typeof html2canvas !== 'function') {{
        msg.textContent = 'html2canvas no cargó. Usa «Descarga directa».';
        window.location.href = '/gerencia/documentos/{clave}/imagen.png';
        return;
      }}
      var el = document.getElementById('capture');
      if (!el) {{ msg.textContent = 'No hay documento'; return; }}
      busy = true; btn.disabled = true; msg.textContent = 'Generando imagen…';
      var killed = false;
      var timer = setTimeout(function() {{
        killed = true;
        done('Tardó mucho. Redirigiendo a descarga directa…');
        window.location.href = '/gerencia/documentos/{clave}/imagen.png';
      }}, 12000);
      html2canvas(el, {{
        scale: 1.5,
        useCORS: true,
        allowTaint: true,
        backgroundColor: '#ffffff',
        logging: false,
        imageTimeout: 3000
      }}).then(function(canvas) {{
        if (killed) return;
        clearTimeout(timer);
        try {{
          var a = document.createElement('a');
          a.download = '{clave}.png';
          a.href = canvas.toDataURL('image/png');
          document.body.appendChild(a);
          a.click();
          a.remove();
          done('Listo · revisa tu carpeta de descargas');
        }} catch (e) {{
          done('Error al guardar. Usa descarga directa.');
          window.location.href = '/gerencia/documentos/{clave}/imagen.png';
        }}
      }}).catch(function(e) {{
        if (killed) return;
        clearTimeout(timer);
        done('Error canvas. Usando descarga directa…');
        window.location.href = '/gerencia/documentos/{clave}/imagen.png';
      }});
    }});
  }})();
  </script>
</body>
</html>"""
    return html_doc


