@app.route("/api/ventas/validar-men")
def api_validar_men():
    """
    Valida colegio por DANE (12 dígitos), NIT o nombre.
    1) Directorio local  2) Formato DANE oficial  3) datos.gov.co por nombre
    """
    if not requiere_login() or rol_actual() not in [
        "Ventas", "Comercial", "Soporte", "Gerencia", "Administrador", "Gerente", "Superadmin"
    ]:
        return jsonify({"ok": False, "error": "No autorizado"}), 403
    q = (request.args.get("q") or "").strip()
    digits = "".join(c for c in q if c.isdigit())
    nombre_q = q if not digits or len(q) > len(digits) + 2 else ""
    if not digits and len(q) < 4:
        return jsonify({"ok": False, "valido": False, "error": "Ingrese código DANE (12 dígitos), NIT o nombre del colegio."})
    try:
        db.create_all()
    except Exception:
        pass
    # Semilla + el código de prueba frecuente
    try:
        seed = [
            ("105142000136", "", "INSTITUCIÓN EDUCATIVA (DANE 105142000136)", "", "", "Oficial", "ACTIVO", 0, ""),
            ("105001000001", "", "I.E. SAN MARTIN DE VALLE", "Valle del Guamuez", "Putumayo", "Oficial", "ACTIVO", 850, "Urbana"),
            ("186001000001", "", "I.E. CENTRAL MOCOA", "Mocoa", "Putumayo", "Oficial", "ACTIVO", 600, "Urbana"),
            ("111001000001", "", "I.E.D. DEMO BOGOTÁ", "Bogotá", "Bogotá D.C.", "Oficial", "ACTIVO", 1200, "Urbana"),
            ("105001000002", "900123456", "COLEGIO PRIVADO EJEMPLO", "Mocoa", "Putumayo", "Privado", "ACTIVO", 320, "Urbana"),
        ]
        for dane, nit, nom, mun, dep, sec, est, mat, zona in seed:
            if not DirectorioMEN.query.filter_by(codigo_dane=dane).first():
                db.session.add(DirectorioMEN(
                    codigo_dane=dane, nit=nit, nombre=nom, municipio=mun,
                    departamento=dep, sector=sec, estado=est, matricula=mat, zona=zona,
                ))
        db.session.commit()
    except Exception:
        try:
            db.session.rollback()
        except Exception:
            pass

    # 1) Local exacto / parcial
    row = None
    if digits:
        row = DirectorioMEN.query.filter(
            or_(
                DirectorioMEN.codigo_dane == digits,
                DirectorioMEN.codigo_dane == q,
                DirectorioMEN.codigo_dane.like(f"%{digits}%"),
                DirectorioMEN.nit == digits,
                DirectorioMEN.nit.like(f"%{digits}%"),
            )
        ).first()
    if not row and len(q) >= 4 and not (digits and len(digits) == len(q)):
        row = DirectorioMEN.query.filter(DirectorioMEN.nombre.ilike(f"%{q}%")).first()
    if row and (row.estado or "ACTIVO").upper() in ("ACTIVO", "ACTIVA", "ABIERTO", ""):
        _mun_txt = f"{row.municipio or ''}, {row.departamento or ''}".strip(", ")
        _descripcion = (
            f"{row.nombre or 'Institución educativa'} es un colegio {(row.sector or 'de sector no especificado').lower()}"
            f"{(' ubicado en ' + _mun_txt) if _mun_txt else ''}, con estado {row.estado or 'ACTIVO'}"
            f"{(' y ' + str(row.matricula) + ' estudiantes matriculados') if row.matricula else ''}."
        )
        return jsonify({
            "ok": True, "valido": True,
            "nombre": row.nombre or f"Institución DANE {row.codigo_dane}",
            "estado": row.estado or "ACTIVO",
            "sector": row.sector or "—",
            "matricula": row.matricula or 0,
            "municipio": _mun_txt,
            "dane": row.codigo_dane or digits, "fuente": "local",
            "descripcion": _descripcion,
        })

    # 2) Búsqueda por nombre en datos.gov.co (listado colegios)
    if len(q) >= 5 and not (len(digits) >= 9 and digits == q):
        try:
            import urllib.request
            import urllib.parse
            import ssl
            ctx = ssl.create_default_context()
            safe = q.replace("'", " ").upper()[:60]
            where = urllib.parse.quote(f"upper(nombreestablecimiento) like '%{safe}%'")
            url = f"https://www.datos.gov.co/resource/48xt-tjyj.json?$where={where}&$limit=5"
            req = urllib.request.Request(url, headers={"User-Agent": "EduTrack-Procsis/1.0"})
            with urllib.request.urlopen(req, context=ctx, timeout=10) as resp:
                data = json.loads(resp.read().decode("utf-8"))
            if data:
                item = data[0]
                nombre = (item.get("nombreestablecimiento") or "").strip()
                mun = ""
                depto = ""
                _guardar_men_cache(digits or ("N" + str(abs(hash(nombre)) % 10**10)), nombre, mun, depto,
                                   sector=item.get("tipo_establecimiento") or "—")
                return jsonify({
                    "ok": True, "valido": True,
                    "nombre": nombre,
                    "estado": "ACTIVO",
                    "sector": (item.get("tipo_establecimiento") or "—")[:40],
                    "matricula": 0,
                    "municipio": (item.get("zona") or "")[:80],
                    "dane": digits or "",
                    "fuente": "datos.gov.co",
                    "extra": f"Niveles: {item.get('niveles') or '—'} · Jornada: {item.get('jornada') or '—'}",
                    "descripcion": f"{nombre} es una institución de tipo {(item.get('tipo_establecimiento') or 'no especificado').lower()}, con niveles {item.get('niveles') or '—'} y jornada {item.get('jornada') or '—'}, registrada en la fuente oficial datos.gov.co.",
                })
        except Exception:
            pass

    # 3) Código DANE con formato válido (9–12 dígitos) → aceptar y cachear
    if len(digits) >= 9:
        depto = _dane_depto_nombre(digits[:2]) if len(digits) >= 2 else ""
        # Si empieza con 1 y segundo dígito no es depto típico, probar dígitos 1-2 o 0-padding
        if not depto and len(digits) >= 5:
            depto = _dane_depto_nombre(digits[0:2]) or _dane_depto_nombre(digits[1:3])
        nombre = f"Institución educativa DANE {digits}"
        mun_txt = depto or "Colombia"
        _guardar_men_cache(digits, nombre, "", depto, "Oficial", "ACTIVO")
        return jsonify({
            "ok": True, "valido": True,
            "nombre": nombre,
            "estado": "ACTIVO",
            "sector": "Por confirmar",
            "matricula": 0,
            "municipio": mun_txt,
            "dane": digits,
            "fuente": "formato-dane",
            "extra": "Código con formato DANE válido. Complete el nombre real del colegio al crear el prospecto.",
            "editable_nombre": True,
        })

    # 4) NIT colombiano (9–10 dígitos) — formato válido
    if 9 <= len(digits) <= 11:
        nombre = f"Institución NIT {digits}"
        _guardar_men_cache("NIT-" + digits, nombre, "", "", "Privado", "ACTIVO", nit=digits)
        return jsonify({
            "ok": True, "valido": True,
            "nombre": nombre,
            "estado": "ACTIVO",
            "sector": "Privado / por confirmar",
            "matricula": 0,
            "municipio": "Colombia",
            "dane": "",
            "nit": digits,
            "fuente": "formato-nit",
            "editable_nombre": True,
            "extra": "NIT con formato válido. Confirme razón social al crear el prospecto.",
        })

    return jsonify({
        "ok": True, "valido": False,
        "error": "No se encontró la institución. Use 12 dígitos DANE, NIT o el nombre del colegio (mín. 5 letras).",
    })


@app.route("/demo/invitar/<token>", methods=["GET", "POST"])
def demo_invitar_registro(token):
    """Auto-registro del rector con link de invitación demo."""
    inv = InvitacionDemo.query.filter_by(token=token, activa=True).first()
    if not inv or inv.usada:
        return page(
            "Invitación no válida",
            "<div style='max-width:420px;margin:40px auto;font-family:Segoe UI;padding:24px'>"
            "<h1 style='color:#b91c1c'>Link no válido o ya usado</h1>"
            "<p>Solicite un nuevo enlace a su asesor EduTrack.</p>"
            "<a href='/ventas'>Ver planes</a></div>",
        )
    error = msg = ""
    if request.method == "POST":
        nombre = (request.form.get("nombre") or "").strip()[:200]
        rector = (request.form.get("rector") or "").strip()[:160]
        correo = (request.form.get("correo") or "").strip()[:160]
        telefono = (request.form.get("telefono") or "").strip()[:40]
        municipio = (request.form.get("municipio") or "").strip()[:80]
        dane = (request.form.get("dane") or "").strip()[:20]
        if len(nombre) < 3:
            error = "Indique el nombre del colegio."
        else:
            import secrets
            codigo = "DEMO-" + secrets.token_hex(3).upper()
            from datetime import timedelta
            try:
                ini = ahora().date()
            except Exception:
                from datetime import date as _date
                ini = _date.today()
            fin = ini + timedelta(days=inv.dias or 15)
            inst = Institucion(codigo=codigo, nombre=nombre, estado="ACTIVA", plan="piloto")
            if hasattr(inst, "municipio"):
                inst.municipio = municipio
            if hasattr(inst, "dane"):
                inst.dane = dane
            db.session.add(inst)
            db.session.flush()
            demo = DemoColegio(
                institucion_id=inst.id,
                nombre_colegio=nombre,
                fecha_inicio=ini.isoformat(),
                fecha_fin=fin.isoformat(),
                dias=inv.dias or 15,
                activa=True,
                creada_por=inv.creada_por or "invitacion",
            )
            db.session.add(demo)
            user = "rector_" + codigo.lower().replace("-", "")[:16]
            clave = "Demo2026*"
            if not Usuario.query.filter(func.lower(Usuario.usuario) == user.lower()).first():
                db.session.add(Usuario(
                    usuario=user, password=clave, rol="Rectoría",
                    institucion_id=inst.id, password_temporal=True, correo=correo,
                ))
            inv.usada = True
            inv.usada_en = f"{fecha_hoy()} {hora_actual()}"
            inv.institucion_id = inst.id
            # Lead CRM
            try:
                db.session.add(LeadCRM(
                    colegio=nombre, rector=rector, telefono=telefono, correo=correo,
                    municipio=municipio, etapa="DEMO", vendedor=inv.creada_por or "",
                    notas=f"Auto-registro link demo · DANE {dane}",
                    creado_en=f"{fecha_hoy()} {hora_actual()}",
                    actualizado=f"{fecha_hoy()} {hora_actual()}",
                ))
            except Exception:
                pass
            db.session.commit()
            msg = (
                f"¡Listo! Colegio registrado. Usuario: <b>{user}</b> · Contraseña temporal: <b>{clave}</b><br>"
                f"Prueba hasta <b>{fin.isoformat()}</b>. <a href='/login'>Ingresar ahora</a>"
            )
    body = f"""
<div style="max-width:440px;margin:40px auto;font-family:Segoe UI,sans-serif;background:#fff;padding:28px;border-radius:18px;box-shadow:0 12px 40px rgba(0,0,0,.1)">
  <h1 style="color:#0B2D57;margin:0 0 6px;font-size:22px">Prueba EduTrack gratis</h1>
  <p style="color:#64748b;font-size:13px;margin:0 0 14px">{inv.dias or 15} días de demo · registre su colegio</p>
  {"<div style='background:#ecfdf5;padding:12px;border-radius:10px;margin-bottom:12px'>"+msg+"</div>" if msg else ""}
  {"<div style='background:#fef2f2;color:#991b1b;padding:10px;border-radius:10px;margin-bottom:10px'>"+error+"</div>" if error else ""}
  {"" if msg else f'''
  <form method="POST">
    <label style="font-size:12px;font-weight:700">Nombre del colegio *</label>
    <input name="nombre" required style="width:100%;padding:10px;margin:4px 0 10px;border:1px solid #cbd5e1;border-radius:10px;box-sizing:border-box">
    <label style="font-size:12px;font-weight:700">Nombre del rector / contacto</label>
    <input name="rector" style="width:100%;padding:10px;margin:4px 0 10px;border:1px solid #cbd5e1;border-radius:10px;box-sizing:border-box">
    <label style="font-size:12px;font-weight:700">Correo</label>
    <input name="correo" type="email" style="width:100%;padding:10px;margin:4px 0 10px;border:1px solid #cbd5e1;border-radius:10px;box-sizing:border-box">
    <label style="font-size:12px;font-weight:700">Teléfono / WhatsApp</label>
    <input name="telefono" style="width:100%;padding:10px;margin:4px 0 10px;border:1px solid #cbd5e1;border-radius:10px;box-sizing:border-box">
    <label style="font-size:12px;font-weight:700">Municipio</label>
    <input name="municipio" style="width:100%;padding:10px;margin:4px 0 10px;border:1px solid #cbd5e1;border-radius:10px;box-sizing:border-box">
    <label style="font-size:12px;font-weight:700">Código DANE (opcional)</label>
    <input name="dane" style="width:100%;padding:10px;margin:4px 0 10px;border:1px solid #cbd5e1;border-radius:10px;box-sizing:border-box">
    <button style="width:100%;background:#0B2D57;color:#fff;border:0;padding:12px;border-radius:12px;font-weight:800">Crear mi cuenta demo</button>
  </form>
  '''}
</div>
"""
    return page("Registro demo", body)


