@app.route("/ventas/comisiones")
def ventas_comisiones():
    """Historial de comisiones del asesor: metas por mes + colegios cerrados (GANADO)."""
    _g = _guard_ventas()
    if _g is not None:
        return _g
    asesor = (session.get("usuario") or "").strip()
    rol = (session.get("rol") or "").strip()
    es_jefe = rol in ("Gerente", "Superadmin", "Administrador")
    metas_q = MetaVendedor.query if es_jefe else MetaVendedor.query.filter_by(usuario=asesor)
    metas = metas_q.order_by(MetaVendedor.mes.desc()).all()
    total_comision = sum(float(m.comision_cop or 0) for m in metas)
    filas_meta = "".join(
        f"<tr><td>{m.mes}</td>"
        + (f"<td>{m.usuario}</td>" if es_jefe else "")
        + f"<td>{m.cerrados} / {m.meta_colegios}</td><td>{_cop(m.comision_por_cierre or 0)} c/u</td>"
        f"<td><b>{_cop(m.comision_cop or 0)}</b></td></tr>"
        for m in metas
    ) or '<tr><td colspan="5">Sin historial todavía</td></tr>'
    leads_q = LeadCRM.query.filter_by(etapa="GANADO")
    if not es_jefe:
        leads_q = leads_q.filter_by(vendedor=asesor)
    ganados = leads_q.order_by(LeadCRM.actualizado.desc()).all()
    filas_col = "".join(
        f"<tr><td>{_esc(g.colegio)}</td><td>{_esc(g.rector) or '—'}</td><td>{_esc(g.municipio) or '—'}</td>"
        f"<td>{_esc(g.plan_interes) or '—'}</td><td>{_esc(g.vendedor) or '—'}</td><td>{_esc(g.actualizado) or '—'}</td></tr>"
        for g in ganados
    ) or '<tr><td colspan="6">Aún no hay colegios cerrados</td></tr>'
    content = f"""
<header class="role-hero"><div>
  <h1>Historial de comisiones</h1>
  <p>{"Vista de gerencia: todos los asesores." if es_jefe else "Detalle de comisiones y colegios cerrados por " + (asesor or "usted") + "."}</p>
</div>
<a class="btn" href="/ventas/panel">Volver</a></header>
<section class="role-panel">
  <h2>Comisión acumulada{" (todos)" if es_jefe else ""}: {_cop(total_comision)}</h2>
  <div style="overflow-x:auto">
    <table>
      <tr><th>Mes</th>{"<th>Asesor</th>" if es_jefe else ""}<th>Colegios (cerrados/meta)</th><th>Valor por cierre</th><th>Comisión del mes</th></tr>
      {filas_meta}
    </table>
  </div>
</section>
<section class="role-panel" style="margin-top:12px">
  <h2>Colegios cerrados (GANADO)</h2>
  <div style="overflow-x:auto">
    <table>
      <tr><th>Colegio</th><th>Rector</th><th>Municipio</th><th>Plan</th><th>Asesor</th><th>Fecha</th></tr>
      {filas_col}
    </table>
  </div>
  <p class="mini-text" style="margin-top:8px">Nota: "cerrado" refleja el estado del embudo (CRM); confirme el pago real en <a href="/soporte/licencias">Licencias y cobros</a> antes de reportarlo como pagado.</p>
</section>
"""
    return page("Comisiones", shell(content))


@app.route("/ventas/propuesta-pdf")
def ventas_propuesta_pdf():
    """Propuesta comercial en PDF con los precios vigentes, para enviar al rector en el momento."""
    _g = _guard_ventas()
    if _g is not None:
        return _g
    ok_rl, espera = _rate_limit("propuesta-pdf", max_veces=15, ventana_seg=60)
    if not ok_rl:
        return _rate_limit_response(espera)
    try:
        try:
            _seed_planes_comerciales()
        except Exception:
            pass
        planes = PlanComercial.query.filter_by(activo=True).order_by(PlanComercial.orden.asc()).all()
        addons = AddonComercial.query.filter_by(activo=True).all()
        partes = [
            "<p><b>Propuesta comercial — Plataforma EduTrack</b></p>",
            "<p>Preparada por Procsis para su institución educativa. Precios en pesos colombianos (COP), sujetos a los planes vigentes.</p>",
            "<h2>Planes disponibles</h2>",
        ]
        for p in planes:
            feats = []
            try:
                feats = json.loads(p.features_json or "[]")
            except Exception:
                feats = []
            feats_txt = " · ".join(feats[:6]) if feats else ""
            partes.append(
                f"<p><b>{p.nombre}</b> — Mensualidad: {_cop(p.precio_mensual)} · "
                f"Implementación (pago único): {_cop(p.fee_implementacion)} · "
                f"Hasta {p.max_estudiantes} estudiantes, {p.max_sedes} sede(s)."
                + (f"<br>{feats_txt}" if feats_txt else "") + "</p>"
            )
        if addons:
            partes.append("<h2>Módulos adicionales (add-ons)</h2>")
            for a in addons:
                partes.append(f"<p><b>{a.nombre}</b> — {_cop(a.precio_mensual)}/mes. {a.descripcion or ''}</p>")
        partes.append("<h2>Condiciones</h2>")
        partes.append(
            "<p>Renovación mensual automática. Implementación, migración de datos y capacitación incluidas en el fee. "
            "Tratamiento de datos conforme a la Ley 1581 de 2012. Propuesta válida por 15 días desde su emisión.</p>"
        )
        partes.append(f"<p>Atentamente<br>Equipo comercial EduTrack — Procsis<br>Asesor: {(session.get('usuario') or '').title()}</p>")
        html_body = "".join(partes)
        data = _doc_pdf_bytes("Propuesta comercial EduTrack", html_body, confidencial=False)
    except Exception as ex:
        import traceback
        return f"<pre style='white-space:pre-wrap;font-family:monospace;padding:20px;color:#b91c1c'>ERROR REAL:\n{traceback.format_exc()}</pre>", 500
    from flask import Response
    return Response(
        data,
        mimetype="application/pdf",
        headers={"Content-Disposition": "attachment; filename=propuesta-comercial-edutrack.pdf"},
    )


@app.route("/ventas/contrato-digital", methods=["GET", "POST"])
def ventas_contrato_digital():
    """Genera el contrato de licenciamiento SaaS con los datos del colegio, listo para firma.
    No reemplaza revisión jurídica; es una plantilla precargada con las cláusulas estándar de Procsis."""
    _g = _guard_ventas()
    if _g is not None:
        return _g
    if request.method == "POST":
        ok_rl, espera = _rate_limit("contrato-digital", max_veces=8, ventana_seg=60)
        if not ok_rl:
            return _rate_limit_response(espera)
    try:
        _seed_planes_comerciales()
    except Exception:
        pass
    planes = PlanComercial.query.filter_by(activo=True).order_by(PlanComercial.orden.asc()).all()
    opciones_plan = "".join(f'<option value="{p.nombre}|{int(p.precio_mensual)}">{p.nombre} — {_cop(p.precio_mensual)}/mes</option>' for p in planes)
    if request.method == "POST":
        colegio = (request.form.get("colegio") or "").strip()[:200]
        nit = (request.form.get("nit") or "").strip()[:40]
        rector = (request.form.get("rector") or "").strip()[:160]
        ciudad = (request.form.get("ciudad") or "").strip()[:120]
        plan_raw = (request.form.get("plan") or "").strip()
        plan_nombre, _, plan_valor = plan_raw.partition("|")
        if not colegio or not nit:
            return page("Contrato digital", shell(f"""
<header class="role-hero"><div><h1>Generar contrato digital</h1></div>
<a class="btn" href="/ventas/contrato-digital">Volver</a></header>
<div class="msg err">Colegio y NIT son obligatorios. <a href="/ventas/contrato-digital">Volver a intentar</a></div>"""))
        html_body = (
            "<p><b>CONTRATO DE LICENCIAMIENTO SAAS — PLATAFORMA EDUTRACK</b></p>"
            "<p>Contrato entre PROCSIS (Proveedor) y la institución educativa (Cliente) que se identifica a continuación. "
            "Documento generado desde el panel comercial; se recomienda revisión jurídica antes de la firma definitiva.</p>"
            "<h2>1. Partes y objeto</h2>"
            "<p>Licencia de uso no exclusiva, intransferible y temporal de EduTrack según el plan contratado, "
            "más implementación y soporte.</p>"
            "<h2>2. Información del cliente</h2>"
            f"<p>Nombre / razón social: <b>{colegio}</b> &nbsp; NIT: <b>{nit}</b> &nbsp; Ciudad: <b>{ciudad or '—'}</b> &nbsp; Rector / representante legal: <b>{rector or '—'}</b></p>"
            "<h2>3. Plan y valor</h2>"
            f"<p>Plan: <b>{plan_nombre or '—'}</b> &nbsp; Valor mensual: <b>{_cop(float(plan_valor or 0))}</b></p>"
            "<h2>4. Vigencia y renovación</h2>"
            "<p>Renovación automática mensual salvo preaviso de cancelación con al menos cinco (5) días hábiles "
            "de anticipación al corte.</p>"
            "<h2>5. Datos personales</h2>"
            "<p>Tratamiento conforme a la Ley 1581 de 2012 y la Política de Tratamiento de Datos de PROCSIS.</p>"
            "<h2>6. Firmas</h2>"
            f"<p>Fecha: {fecha_hoy()}</p>"
            "<p>Por PROCSIS: ____________ &nbsp; Por el Cliente: ____________</p>"
        )
        data = _doc_pdf_bytes(f"Contrato EduTrack — {colegio}", html_body, confidencial=True)
        # Activar institución + facturación: el contrato firmado es el disparador real del cobro.
        info_fact = ""
        try:
            pc_match = PlanComercial.query.filter_by(nombre=plan_nombre).first()
            fee_valor = float(pc_match.fee_implementacion) if pc_match and pc_match.fee_implementacion else 0.0
            inst = Institucion.query.filter(
                (Institucion.nit == nit) | (Institucion.nombre == colegio)
            ).first()
            if not inst:
                codigo_auto = ("NIT" + "".join(ch for ch in nit if ch.isalnum()))[:40] or f"COL{int(__import__('time').time())}"
                inst = Institucion(
                    codigo=codigo_auto, nombre=colegio[:200], nit=nit[:40],
                    municipio=ciudad[:120], estado="ACTIVA", plan=(plan_nombre or "Basico")[:40],
                    fecha_creacion=fecha_hoy(),
                    notas=(f"Alta por contrato digital · asesor: {nombre_mostrar_actual()}")[:250],
                )
                db.session.add(inst)
                db.session.flush()
            else:
                if plan_nombre:
                    inst.plan = plan_nombre[:40]
            r = _activar_facturacion_institucion(inst, fee_valor=fee_valor)
            dias = _dias_facturando(inst) or 0
            n_fact = len(r.get("facturas_creadas") or [])
            info_fact = f" Facturación activada: día {dias + 1} desde hoy, {n_fact} recibo(s) generado(s)."
            registrar_auditoria("Contrato digital generado", f"{session.get('usuario')}: {colegio} (NIT {nit}) plan {plan_nombre}.{info_fact}")
        except Exception as ex:
            print("activar facturacion contrato:", ex)
            try:
                db.session.rollback()
            except Exception:
                pass
        try:
            up_dir = os.path.join(app.root_path, "static", "uploads", "contratos")
            os.makedirs(up_dir, exist_ok=True)
            safe_name = "".join(c for c in colegio if c.isalnum() or c in (" ", "-", "_")).strip().replace(" ", "_") or "colegio"
            fname = f"{safe_name}_{int(__import__('time').time())}.pdf"
            with open(os.path.join(up_dir, fname), "wb") as f:
                f.write(data)
            registrar_auditoria("Contrato PDF guardado", f"{fname}")
            pdf_url = f"/static/uploads/contratos/{fname}"
        except Exception as ex:
            print("contrato guardado:", ex)
            pdf_url = ""
        return page("Contrato generado", shell(f"""
<header class="role-hero"><div>
  <h1>✅ Contrato generado — {_esc(colegio)}</h1>
  <p>{info_fact or "Facturación registrada."}</p>
</div>
<a class="btn" href="/ventas/contrato-digital">Generar otro</a></header>
<section class="role-panel">
  <p><b>Colegio:</b> {_esc(colegio)} &nbsp; <b>NIT:</b> {_esc(nit)} &nbsp; <b>Plan:</b> {_esc(plan_nombre) or '—'}</p>
  <p>{info_fact or ""}</p>
  <div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:14px">
    {"<a class='btn' href='" + pdf_url + "' download>⬇ Descargar contrato (PDF)</a>" if pdf_url else "<span style='color:#b91c1c'>No se pudo guardar el PDF en el servidor, pero puede volver a generarlo.</span>"}
    <a class="btn" href="/ventas/comisiones">Ver historial de comisiones</a>
    <a class="btn" href="/gerencia/facturacion">Ver estado de facturación</a>
  </div>
</section>
"""))
    content = f"""
<header class="role-hero"><div>
  <h1>Generar contrato digital</h1>
  <p>Complete los datos del colegio y el plan acordado. Se genera el PDF listo para firma con las cláusulas
  estándar de Procsis (Ley 1581 de 2012, renovación, vigencia).</p>
</div>
<a class="btn" href="/ventas/panel">Volver</a></header>
<section class="role-panel">
  <form method="POST">
    <label><b>Colegio / razón social</b></label>
    <input name="colegio" required placeholder="I.E. Ejemplo">
    <label><b>NIT</b></label>
    <input name="nit" required placeholder="900123456-7">
    <label><b>Rector / representante legal</b></label>
    <input name="rector" placeholder="Nombre completo">
    <label><b>Ciudad</b></label>
    <input name="ciudad" placeholder="Ciudad / municipio">
    <label><b>Plan</b></label>
    <select name="plan">{opciones_plan}</select>
    <button type="submit" style="margin-top:14px">Generar y descargar PDF</button>
  </form>
  <p class="mini-text" style="margin-top:10px">Esta plantilla no sustituye la revisión de un abogado antes de la firma definitiva. Cada contrato generado queda guardado en el servidor y registrado en auditoría.</p>
</section>
"""
    return page("Contrato digital", shell(content))



