@app.route("/ventas/demos", methods=["GET", "POST"])
def ventas_demos():
    """Crear demo de colegio con fecha de caducidad (bloqueo automático)."""
    _g = _guard_ventas()
    if _g is not None:
        return _g
    try:
        db.create_all()
    except Exception:
        pass
    msg = err = ""
    if request.method == "POST":
        nombre = (request.form.get("nombre") or "").strip()[:200]
        try:
            dias = int(request.form.get("dias") or 15)
        except Exception:
            dias = 15
        dias = max(1, min(dias, 90))
        if not nombre:
            err = "Indique el nombre del colegio demo."
        else:
            from datetime import timedelta
            try:
                ini = ahora().date()
            except Exception:
                from datetime import date as _date
                ini = _date.today()
            fin = ini + timedelta(days=dias)
            # Crear institución demo
            import secrets
            codigo = "DEMO-" + secrets.token_hex(3).upper()
            inst = Institucion(
                codigo=codigo,
                nombre=nombre,
                estado="ACTIVA",
                plan="piloto",
            )
            # campos opcionales si existen
            if hasattr(inst, "municipio"):
                inst.municipio = (request.form.get("municipio") or "")[:80]
            db.session.add(inst)
            db.session.flush()
            demo = DemoColegio(
                institucion_id=inst.id,
                nombre_colegio=nombre,
                fecha_inicio=ini.isoformat(),
                fecha_fin=fin.isoformat(),
                dias=dias,
                activa=True,
                creada_por=session.get("usuario") or "",
            )
            db.session.add(demo)
            # Usuario rector demo
            user = "demo_" + codigo.lower().replace("-", "")
            if not Usuario.query.filter(func.lower(Usuario.usuario) == user.lower()).first():
                u = Usuario(
                    usuario=user,
                    password="Demo2026*",
                    rol="Rectoría",
                    institucion_id=inst.id,
                    password_temporal=True,
                )
                db.session.add(u)
            db.session.commit()
            msg = (
                f"Demo creada: {nombre}. Código inst. {codigo}. "
                f"Usuario: {user} / Demo2026* · Caduca: {fin.isoformat()} ({dias} días)."
            )
            registrar_auditoria("Demo creada", f"{nombre} hasta {fin}")
    # Caducar demos vencidas
    try:
        hoy = fecha_hoy()
        for d in DemoColegio.query.filter_by(activa=True).all():
            if d.fecha_fin and d.fecha_fin < hoy:
                d.activa = False
                inst = Institucion.query.get(d.institucion_id)
                if inst and (inst.plan or "").lower() in ("piloto", "demo", ""):
                    inst.estado = "SUSPENDIDA"
                    inst.motivo_bloqueo = (
                        "Prueba demo finalizada. ¿Te gustó? Adquiere un plan en /ventas"
                    )
                db.session.commit()
    except Exception:
        pass
    filas = ""
    for d in DemoColegio.query.order_by(DemoColegio.id.desc()).limit(50).all():
        filas += f"""<tr>
          <td>{d.id}</td><td>{d.nombre_colegio}</td>
          <td>{d.fecha_inicio} → <b>{d.fecha_fin}</b></td>
          <td>{d.dias} d</td>
          <td>{"Activa" if d.activa else "Caducada"}</td>
          <td>{d.creada_por}</td></tr>"""
    body = f"""
<div style="max-width:800px;margin:0 auto;padding:20px;font-family:Segoe UI,sans-serif">
  <p><a href="/ventas/crm">← CRM</a> · <a href="/ventas/panel">Panel ventas</a></p>
  <h1 style="color:#0B2D57">Crear demo con caducidad</h1>
  <p style="font-size:13px;color:#64748b">Al vencer la fecha, el acceso se bloquea y el rector ve: «¿Te gustó la prueba? Adquiere un plan aquí».</p>
  {"<div style='background:#ecfdf5;padding:10px;border-radius:10px'>"+msg+"</div>" if msg else ""}
  {"<div style='background:#fef2f2;padding:10px;border-radius:10px'>"+err+"</div>" if err else ""}
  <form method="POST" style="background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:16px;margin:12px 0">
    <label style="font-weight:700;font-size:12px">Nombre del colegio</label>
    <input name="nombre" required style="width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:8px;margin-bottom:8px">
    <label style="font-weight:700;font-size:12px">Municipio</label>
    <input name="municipio" style="width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:8px;margin-bottom:8px">
    <label style="font-weight:700;font-size:12px">Días de prueba</label>
    <select name="dias"><option value="7">7 días</option><option value="15" selected>15 días</option><option value="30">30 días</option></select>
    <button style="display:block;margin-top:12px;background:#0B2D57;color:#fff;border:0;padding:12px 18px;border-radius:10px;font-weight:800">Crear Demo</button>
  </form>
  <table style="width:100%;border-collapse:collapse;font-size:13px;background:#fff">
    <tr style="background:#0B2D57;color:#fff"><th style="padding:8px">ID</th><th>Colegio</th><th>Vigencia</th><th>Días</th><th>Estado</th><th>Creó</th></tr>
    {filas or '<tr><td colspan=6>Sin demos</td></tr>'}
  </table>
</div>
"""
    return page("Demos", body)




@app.route("/soporte/periodos-colegio", methods=["GET", "POST"])
def soporte_periodos_colegio():
    """Soporte ajusta cuántos periodos (3 o 4) maneja un colegio cuando el rector lo solicita."""
    if not requiere_login() or rol_actual() not in ("Soporte", "Superadmin", "Gerente", "Administrador"):
        return redirect("/soporte-login")
    msg = err = ""
    insts = Institucion.query.order_by(Institucion.nombre.asc()).limit(200).all()
    if request.method == "POST":
        try:
            iid = int(request.form.get("institucion_id") or 0)
        except Exception:
            iid = 0
        try:
            nper = int(request.form.get("num_periodos") or 3)
        except Exception:
            nper = 3
        if nper not in (3, 4):
            err = "Solo se permiten 3 o 4 periodos."
        elif not iid:
            err = "Seleccione el colegio."
        else:
            inst = Institucion.query.get(iid)
            if not inst:
                err = "Institución no encontrada."
            else:
                cfg = Configuracion.query.filter_by(institucion_id=iid).first()
                if not cfg:
                    cfg = Configuracion(institucion_id=iid)
                    db.session.add(cfg)
                cfg.num_periodos = nper
                cfg.periodos_lista = "|".join([f"Periodo {i}" for i in range(1, nper + 1)])
                # Si el periodo actual queda fuera de rango, resetear
                actual = (cfg.periodo_actual or "").strip()
                permitidos = [f"Periodo {i}" for i in range(1, nper + 1)]
                if actual not in permitidos and not actual.startswith("Final"):
                    cfg.periodo_actual = "Periodo 1"
                db.session.commit()
                registrar_auditoria("Soporte cambió periodos", f"{inst.nombre} → {nper} periodos")
                msg = f"Colegio <b>{inst.nombre}</b> configurado con <b>{nper} periodos</b> al año."
    filas = ""
    for inst in insts:
        cfg = Configuracion.query.filter_by(institucion_id=inst.id).first()
        n = getattr(cfg, "num_periodos", None) if cfg else None
        n = n or 3
        actual = (cfg.periodo_actual if cfg else None) or "—"
        filas += f"<tr><td>{inst.id}</td><td>{_esc(inst.nombre)}</td><td>{n}</td><td>{_esc(actual)}</td></tr>"
    opts = "".join(f'<option value="{i.id}">{_esc(i.nombre)}</option>' for i in insts)
    body = f"""
<div style="max-width:820px;margin:20px auto;font-family:Segoe UI,sans-serif;padding:16px">
  <p><a href="/soporte_admin">← Soporte</a></p>
  <h1 style="color:#0B2D57">Periodos académicos por colegio</h1>
  <p style="color:#64748b;font-size:14px">Cuando un rector solicita cambiar de 3 a 4 periodos (o al revés), aplique el cambio aquí. Afecta planillas, boletines y listados de periodo.</p>
  {"<p style='background:#f0fdf4;padding:10px;border-radius:8px;color:#166534'>"+msg+"</p>" if msg else ""}
  {"<p style='background:#fef2f2;padding:10px;border-radius:8px;color:#b91c1c'>"+err+"</p>" if err else ""}
  <form method="POST" style="background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:16px;margin-bottom:20px">
    <label><b>Colegio</b></label>
    <select name="institucion_id" required style="width:100%;padding:10px;margin:6px 0;border:1px solid #e2e8f0;border-radius:8px">{opts}</select>
    <label><b>Número de periodos al año</b></label>
    <select name="num_periodos" required style="width:100%;padding:10px;margin:6px 0;border:1px solid #e2e8f0;border-radius:8px">
      <option value="3">3 periodos</option>
      <option value="4">4 periodos</option>
    </select>
    <button type="submit" style="margin-top:10px;padding:12px 18px;background:#0B2D57;color:#fff;border:0;border-radius:10px;font-weight:800">Aplicar cambio</button>
  </form>
  <table style="width:100%;border-collapse:collapse;background:#fff;font-size:13px">
    <tr style="background:#0B2D57;color:#fff"><th style="padding:8px">ID</th><th>Colegio</th><th>Periodos</th><th>Periodo actual</th></tr>
    {filas or '<tr><td colspan="4">Sin instituciones</td></tr>'}
  </table>
</div>
"""
    return page("Periodos por colegio", body)


@app.route("/soporte/reset-clave", methods=["GET", "POST"])
def soporte_reset_clave():
    """Buscar por usuario/cédula y restablecer clave temporal (cédula o Colegio2026*)."""
    if not requiere_login() or rol_actual() not in ("Soporte", "Administrador", "Superadmin", "Gerente"):
        return redirect("/soporte-login")
    msg = err = ""
    resultados = []
    q = (request.values.get("q") or "").strip()
    if request.method == "POST" and request.form.get("accion") == "reset":
        try:
            uid = int(request.form.get("user_id") or 0)
        except Exception:
            uid = 0
        u = Usuario.query.get(uid)
        if not u:
            err = "Usuario no encontrado."
        elif (u.rol or "") in ("Soporte", "Gerencia", "Administrador") and rol_actual() == "Soporte":
            err = "No puede resetear cuentas internas de Gerencia/Soporte desde aquí."
        else:
            # Clave temporal: documento/usuario o por defecto — obligatoria nota de lo realizado
            nota = (request.form.get("nota") or "").strip()
            if not nota or len(nota) < 5:
                err = "Debe indicar una nota breve de lo que hizo (mín. 5 caracteres). Queda en auditoría."
            else:
                nueva = (request.form.get("nueva") or "").strip()
                if not nueva:
                    nueva = (u.usuario or "Colegio2026*").strip() or "Colegio2026*"
                u.password = crear_hash(nueva)
                if hasattr(u, "password_temporal"):
                    u.password_temporal = True
                db.session.commit()
