@app.route("/soporte/dejar-impersonar")
def soporte_dejar_impersonar():
    """Volver a la sesión real de soporte tras suplantar."""
    imp = session.get("impersonator")
    if not imp:
        return redirect("/soporte_admin")
    session["usuario"] = imp.get("usuario")
    session["rol"] = imp.get("rol")
    session["user_id"] = imp.get("user_id")
    session["institucion_id"] = imp.get("institucion_id")
    session.pop("impersonator", None)
    session.pop("impersonating", None)
    try:
        sincronizar_inst_globals()
    except Exception:
        pass
    return redirect("/soporte_admin")


