        mes_per = ["Enero","Febrero","Marzo","Abril","Mayo","Junio","Julio","Agosto","Septiembre","Octubre","Noviembre","Diciembre"]
        d0 = _dt.strptime(exped[:10], "%Y-%m-%d")
        periodo_txt = f"{mes_per[d0.month-1]} {d0.year}"
