def _cfg_tesoreria_path():
    folder = os.path.join(app.root_path, "config")
    os.makedirs(folder, exist_ok=True)
    return os.path.join(folder, "tesoreria.json")

def _leer_tesoreria():
    path = _cfg_tesoreria_path()
    default = {
        "banco": "", "tipo_cuenta": "Ahorros", "numero_cuenta": "",
        "titular": "", "nit": "", "pasarela": "Wompi", "pasarela_public_key": "",
        "link_pago": "",
        "wompi_events_secret": "",
        "notas": "Solo gerencia modifica datos de recaudo.",
    }
    try:
        if os.path.isfile(path):
            with open(path, encoding="utf-8") as f:
                data = json.load(f)
            default.update(data)
    except Exception:
        pass
    return default

def _guardar_tesoreria(data):
    with open(_cfg_tesoreria_path(), "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)


def _cop(n):
    try:
        v = float(n or 0)
    except Exception:
        v = 0.0
    return f"$ {v:,.0f} COP".replace(",", ".")

def _calcular_almacenamiento_global(cap_mb=5120):
    """
    Medidor EN VIVO del disco real (fotos estudiantes, biometría, logos, uploads de docentes/rectoría).
    cap_mb = capacidad de referencia del plan (default 5 GB = 5120 MB).
    Retorna (used_mb, pct) y deja desglose en _calcular_almacenamiento_global.last_breakdown
    """
    import os as _os
    breakdown = {
        "fotos_estudiantes": 0,
        "biometria": 0,
        "logos": 0,
        "otros_uploads": 0,
        "static_app": 0,
        "instance_db": 0,
    }
    bases = []
    try:
        bases.append(_os.path.dirname(_os.path.abspath(__file__)))
    except Exception:
        bases.append(".")
    total = 0
    for base in bases:
        # Carpetas de datos generados por uso real (docente, secretaría, rectoría, soporte)
        scan = [
            (_os.path.join(base, "static", "uploads", "fotos_estudiantes"), "fotos_estudiantes"),
            (_os.path.join(base, "static", "uploads", "biometria"), "biometria"),
            (_os.path.join(base, "static", "uploads", "logos"), "logos"),
            (_os.path.join(base, "static", "uploads"), "otros_uploads"),
            (_os.path.join(base, "uploads"), "otros_uploads"),
            (_os.path.join(base, "static", "img", "novedades"), "otros_uploads"),
            (_os.path.join(base, "instance"), "instance_db"),
            (_os.path.join(base, "media"), "otros_uploads"),
            (_os.path.join(base, "storage"), "otros_uploads"),
        ]
        seen_files = set()
        for root, key in scan:
            if not _os.path.isdir(root):
                continue
            for dirpath, _, filenames in _os.walk(root):
                # Evitar contar dos veces subcarpetas ya desglosadas dentro de static/uploads
                if key == "otros_uploads" and (
                    f"{_os.sep}fotos_estudiantes" in dirpath
                    or f"{_os.sep}biometria" in dirpath
                    or f"{_os.sep}logos" in dirpath
                ):
                    continue
                for fn in filenames:
                    fp = _os.path.join(dirpath, fn)
                    if fp in seen_files:
                        continue
                    seen_files.add(fp)
                    try:
                        sz = _os.path.getsize(fp)
                    except Exception:
                        continue
                    total += sz
                    breakdown[key] = breakdown.get(key, 0) + sz
    used_mb = round(total / (1024 * 1024), 1)
    pct = min(100, round(100.0 * used_mb / max(cap_mb, 1), 1))
    # Desglose en MB para el panel
    _calcular_almacenamiento_global.last_breakdown = {
        k: round(v / (1024 * 1024), 2) for k, v in breakdown.items()
    }
    _calcular_almacenamiento_global.last_breakdown["total_mb"] = used_mb
    _calcular_almacenamiento_global.last_breakdown["cap_mb"] = cap_mb
    # Estimación: con fotos 40 KB, ~35 colegios de 1000 alumnos en 5 GB
    _calcular_almacenamiento_global.last_breakdown["nota"] = (
        "Fotos comprimidas a 200×200 (~40 KB). PDFs de boletines se generan en vivo (0 MB en disco)."
    )
    return used_mb, pct

_calcular_almacenamiento_global.last_breakdown = {}


def _gerencia_metricas():
    """KPIs completos de Gerencia: financiero, crecimiento, producto/soporte."""
    try:
        _migrate_facturas_cobro_columns()
    except Exception:
        pass
    mes = ahora().strftime("%Y-%m") if hasattr(ahora(), "strftime") else ""
    activas = Institucion.query.filter(Institucion.estado == "ACTIVA").count()
    suspendidas = Institucion.query.filter(Institucion.estado == "SUSPENDIDA").count()
    total_inst = max(activas + suspendidas, 1)

    planes = {p.nombre.lower(): float(p.precio_mensual or 0) for p in PlanComercial.query.filter_by(activo=True).all()}
    if not planes:
        planes = {
            "demo": 0, "piloto": 0,
            "básico": 149000, "basico": 149000,
            "estándar": 249000, "estandar": 249000,
            "pro": 349000,
            "premium": 499000,
        }
    mrr = 0.0
    for inst in Institucion.query.filter_by(estado="ACTIVA").all():
        pn = (inst.plan or "basico").lower().replace("á", "a")
        mrr += float(planes.get(pn, planes.get((inst.plan or "").lower(), 249000)) or 0)
    arr = mrr * 12

    pend = FacturaCobro.query.filter(FacturaCobro.estado.in_(["PENDIENTE", "VENCIDA"])).all()
    cartera = sum(float(f.valor or 0) for f in pend)
    cobrado = sum(float(f.valor or 0) for f in FacturaCobro.query.filter(FacturaCobro.estado.in_(["PAGADA", "PAGADO"])).all())

    gastos_q = GastoOperativo.query
    if mes:
        gastos_mes_list = gastos_q.filter_by(mes=mes).all()
    else:
        gastos_mes_list = gastos_q.limit(50).all()
    total_gastos = sum(float(g.valor or 0) for g in gastos_mes_list)
    gastos_anio = sum(float(g.valor or 0) for g in GastoOperativo.query.all())

    neto = mrr - total_gastos
    margen = round(100.0 * neto / mrr, 1) if mrr > 0 else 0.0
    churn = round(100.0 * suspendidas / total_inst, 1)

    # CAC aproximado: gastos marketing+salarios del mes / altas del mes (si no hay altas, 0)
    altas_mes = 0
    try:
        # instituciones creadas no tienen created_at siempre; usar facturas one_time del mes
        if mes:
            altas_mes = FacturaCobro.query.filter_by(tipo="one_time").filter(FacturaCobro.creado_en.like(f"{mes}%")).count()
    except Exception:
        altas_mes = 0
    gasto_adq = sum(float(g.valor or 0) for g in gastos_mes_list if (g.categoria or "") in ("salarios", "api", "otro", "marketing"))
    cac = (gasto_adq / altas_mes) if altas_mes else 0.0

    # LTV aproximado: ARPU / (churn mensual fraction) — si churn 0, LTV = ARPU * 24
    arpu = (mrr / activas) if activas else 0.0
    churn_f = (suspendidas / total_inst) if total_inst else 0.0
    if churn_f > 0.001:
        ltv = arpu / churn_f
    else:
        ltv = arpu * 24

    # Embudo ventas: notas por motivo
    try:
        embudo = {
            "cotizacion": NotaInteraccion.query.filter(NotaInteraccion.motivo.in_(["Cotización", "Demo"])).count(),
            "seguimiento": NotaInteraccion.query.filter_by(motivo="Seguimiento").count(),
            "renovacion": NotaInteraccion.query.filter_by(motivo="Renovación").count(),
            "cierres": FacturaCobro.query.filter_by(tipo="one_time", estado="PAGADA").count(),
        }
    except Exception:
        embudo = {"cotizacion": 0, "seguimiento": 0, "renovacion": 0, "cierres": 0}

    # DAU/MAU proxy: usuarios con session recientes + auditoria
    try:
        mau = Usuario.query.filter(Usuario.rol.in_(["Docente", "Rectoría", "Coordinación", "Secretaría"])).count()
        dau = min(mau, max(1, int(mau * 0.15))) if mau else 0
        # mejor si hay SesionEmpleado o auditoria
        try:
            from datetime import timedelta
            # count audit login today
            hoy = ahora().strftime("%Y-%m-%d") if hasattr(ahora(), "strftime") else ""
            if hoy and "Auditoria" in dir() or True:
                dau = Auditoria.query.filter(Auditoria.accion.like("%Login%") | Auditoria.accion.like("%sesión%") | Auditoria.accion.like("%Inicio%")).filter(Auditoria.fecha.like(f"{hoy}%")).count() if hasattr(Auditoria, "fecha") else dau
        except Exception:
            pass
    except Exception:
        dau = mau = 0

    # PQR tiempo promedio (placeholder si no hay timestamps de cierre)
    try:
        pqr_abiertas = TicketPQR.query.filter(~TicketPQR.estado.in_(["RESUELTA", "CERRADA", "CERRADO"])).count()
        pqr_cerradas = TicketPQR.query.filter(TicketPQR.estado.in_(["RESUELTA", "CERRADA", "CERRADO"])).count()
        pqr_total = pqr_abiertas + pqr_cerradas
    except Exception:
        pqr_abiertas = pqr_cerradas = pqr_total = 0
    sla_horas = 24  # meta
    # Servidores: verde si activas < 50, amarillo < 150, rojo >= 150
    if activas < 30:
        srv, srv_label = "verde", "Estable"
    elif activas < 80:
        srv, srv_label = "amarillo", "Carga media"
    else:
        srv, srv_label = "rojo", "Alta demanda"

    # Cashflow simple: cobrado - gastos totales registrados
    cashflow = cobrado - gastos_anio

    
    # Tiempo real: sin primera venta (factura pagada) los KPIs comerciales van en cero
    tiene_venta = FacturaCobro.query.filter(FacturaCobro.estado.in_(["PAGADA", "PAGADO"])).count() > 0
    if not tiene_venta:
        mrr = arr = cartera = cobrado = neto = margen = cac = ltv = arpu = cashflow = 0.0
        altas_mes = 0
        embudo = {"cotizacion": 0, "seguimiento": 0, "renovacion": 0, "cierres": 0}

    # Almacenamiento global (uploads + static + instance)
    storage_used_mb, storage_pct = _calcular_almacenamiento_global()

    return {
        "mes": mes,
        "activas": activas,
        "suspendidas": suspendidas,
        "mrr": mrr,
        "arr": arr,
        "cartera": cartera,
        "cobrado": cobrado,
        "gastos": total_gastos,
        "gastos_anio": gastos_anio,
        "neto": neto,
        "storage_used_mb": storage_used_mb,
        "storage_pct": storage_pct,
        "storage_breakdown": getattr(_calcular_almacenamiento_global, "last_breakdown", {}) or {},
        "margen": margen,
        "churn": churn,
        "cac": cac,
        "ltv": ltv,
        "arpu": arpu,
        "altas_mes": altas_mes,
        "embudo": embudo,
        "dau": dau,
        "mau": mau,
        "pqr_abiertas": pqr_abiertas,
        "pqr_cerradas": pqr_cerradas,
        "pqr_total": pqr_total,
        "sla_horas": sla_horas,
        "srv": srv,
        "srv_label": srv_label,
        "cashflow": cashflow,
        "facturas_pend": len(pend),
    }


def _gerencia_serie_mensual(meses=6):
    """Serie de cobrado / gastos / altas por mes (últimos N meses) para gráficas."""
    try:
        hoy = ahora().date() if hasattr(ahora(), "date") else datetime.now().date()
    except Exception:
        hoy = datetime.now().date()
    labels, cobrados, gastos, altas = [], [], [], []
    for i in range(meses - 1, -1, -1):
        y = hoy.year
        m = hoy.month - i
        while m <= 0:
            m += 12
            y -= 1
        key = f"{y:04d}-{m:02d}"
        labels.append(key)
        try:
            cob = sum(
                float(f.valor or 0)
                for f in FacturaCobro.query.filter(
                    FacturaCobro.estado.in_(["PAGADA", "PAGADO"]),
                    or_(
                        FacturaCobro.pagada_en.like(f"{key}%"),
                        FacturaCobro.creado_en.like(f"{key}%"),
                    ),
                ).all()
            )
        except Exception:
            cob = 0.0
        try:
            gas = sum(float(g.valor or 0) for g in GastoOperativo.query.filter_by(mes=key).all())
        except Exception:
            gas = 0.0
        try:
            alt = FacturaCobro.query.filter_by(tipo="one_time").filter(FacturaCobro.creado_en.like(f"{key}%")).count()
        except Exception:
            alt = 0
        cobrados.append(round(cob, 0))
        gastos.append(round(gas, 0))
        altas.append(alt)
    return {"labels": labels, "cobrado": cobrados, "gastos": gastos, "altas": altas}


def _gerencia_periodo_info(periodo="mensual"):
    """Devuelve etiqueta y rango para mensual o quincenal."""
    try:
        hoy = ahora().date() if hasattr(ahora(), "date") else datetime.now().date()
    except Exception:
        hoy = datetime.now().date()
    periodo = (periodo or "mensual").strip().lower()
    if periodo == "quincenal":
        if hoy.day <= 15:
            ini = hoy.replace(day=1)
            fin = hoy.replace(day=15)
            etiqueta = f"1.ª quincena {hoy.strftime('%B %Y')}"
        else:
            ini = hoy.replace(day=16)
            fin = hoy
            etiqueta = f"2.ª quincena {hoy.strftime('%B %Y')}"
        return {
            "periodo": "quincenal",
            "etiqueta": etiqueta,
            "desde": ini.isoformat(),
            "hasta": fin.isoformat(),
            "mes": hoy.strftime("%Y-%m"),
        }
    return {
        "periodo": "mensual",
        "etiqueta": hoy.strftime("%B %Y").capitalize(),
        "desde": hoy.replace(day=1).isoformat(),
        "hasta": hoy.isoformat(),
        "mes": hoy.strftime("%Y-%m"),
    }


