@app.route("/gerencia/reportes/excel")
def gerencia_reportes_excel():
    """Descarga Excel empresarial (estilo tabla profesional) mensual o quincenal."""
    _g = _guard_gerencia()
    if _g is not None:
        return _g
    periodo = (request.args.get("periodo") or "mensual").strip().lower()
    if periodo not in ("mensual", "quincenal"):
        periodo = "mensual"
    info = _gerencia_periodo_info(periodo)
    m = _gerencia_metricas()
    serie = _gerencia_serie_mensual(6)
    e = m.get("embudo") or {}

    wb = Workbook()
    # Estilos
    header_fill = PatternFill("solid", fgColor="0B2D57")
    header_font = Font(bold=True, color="FFFFFF", name="Calibri", size=11)
    title_font = Font(bold=True, color="0B2D57", name="Calibri", size=16)
    sub_font = Font(color="64748B", name="Calibri", size=10)
    kpi_fill = PatternFill("solid", fgColor="F1F5F9")
    money_font = Font(bold=True, name="Calibri", size=12, color="0F172A")
    thin = Border(
        left=Side(style="thin", color="CBD5E1"),
        right=Side(style="thin", color="CBD5E1"),
        top=Side(style="thin", color="CBD5E1"),
        bottom=Side(style="thin", color="CBD5E1"),
    )
    center = Alignment(horizontal="center", vertical="center", wrap_text=True)
    left = Alignment(horizontal="left", vertical="center")

    # Hoja 1: Resumen KPIs
    ws = wb.active
    ws.title = "Resumen KPIs"
    ws.merge_cells("A1:D1")
    ws["A1"] = "EduTrack · Reporte gerencial"
    ws["A1"].font = title_font
    ws.merge_cells("A2:D2")
    ws["A2"] = f"Periodo: {info['etiqueta']} ({info['desde']} → {info['hasta']}) · Tipo: {periodo.upper()}"
    ws["A2"].font = sub_font
    ws.append([])
    headers = ["Indicador", "Valor", "Unidad / nota", "Bloque"]
    ws.append(headers)
    for col in range(1, 5):
        c = ws.cell(row=4, column=col)
        c.fill = header_fill
        c.font = header_font
        c.alignment = center
        c.border = thin

    filas_kpi = [
        ("MRR", m["mrr"], "COP · ingreso recurrente mes", "Financiero"),
        ("ARR", m["arr"], "COP · proyección 12 meses", "Financiero"),
        ("Churn", m["churn"], "% cancelación / suspensión", "Financiero"),
        ("Cashflow", m["cashflow"], "COP · cobrado − gastos", "Financiero"),
        ("Margen", m["margen"], "% MRR − gastos del mes", "Financiero"),
        ("Cartera", m["cartera"], f"COP · {m['facturas_pend']} facturas abiertas", "Financiero"),
        ("Gastos periodo", m["gastos"], "COP · nómina, servidores, APIs", "Financiero"),
        ("Colegios activos", m["activas"], f"Suspendidos: {m['suspendidas']}", "Financiero"),
        ("CAC", m["cac"], "COP · costo por colegio nuevo", "Crecimiento"),
        ("LTV", m["ltv"], "COP · valor vida estimado", "Crecimiento"),
        ("ARPU", m["arpu"], "COP · ingreso medio / colegio", "Crecimiento"),
        ("Altas", m["altas_mes"], "Implementaciones generadas", "Crecimiento"),
        ("Cotización/Demo", e.get("cotizacion", 0), "Notas comerciales", "Crecimiento"),
        ("Seguimiento", e.get("seguimiento", 0), "Negociación activa", "Crecimiento"),
        ("Cierres", e.get("cierres", 0), "One-time pagados", "Crecimiento"),
        ("DAU", m["dau"], "Actividad de acceso hoy", "Producto"),
        ("MAU", m["mau"], "Usuarios institucionales", "Producto"),
        ("PQR abiertas", m["pqr_abiertas"], f"Cerradas: {m['pqr_cerradas']}", "Producto"),
        ("SLA meta", m["sla_horas"], "Horas objetivo de respuesta", "Producto"),
        ("Servidores", m["srv_label"], "Estado de carga", "Producto"),
    ]
    for i, (ind, val, nota, bloque) in enumerate(filas_kpi, start=5):
        ws.cell(row=i, column=1, value=ind).border = thin
        cell_v = ws.cell(row=i, column=2, value=val)
        cell_v.border = thin
        cell_v.font = money_font
        if isinstance(val, float):
            cell_v.number_format = '#,##0'
        ws.cell(row=i, column=3, value=nota).border = thin
        ws.cell(row=i, column=4, value=bloque).border = thin
        if i % 2 == 0:
            for col in range(1, 5):
                ws.cell(row=i, column=col).fill = kpi_fill

    ws.column_dimensions["A"].width = 18
    ws.column_dimensions["B"].width = 16
    ws.column_dimensions["C"].width = 36
    ws.column_dimensions["D"].width = 14

    # Hoja 2: Serie mensual
    ws2 = wb.create_sheet("Serie 6 meses")
    ws2["A1"] = "Serie histórica · cobrado / gastos / altas"
    ws2["A1"].font = title_font
    ws2.merge_cells("A1:E1")
    ws2.append([])
    h2 = ["Mes", "Cobrado (COP)", "Gastos (COP)", "Neto (COP)", "Altas"]
    ws2.append(h2)
    for col in range(1, 6):
        c = ws2.cell(row=3, column=col)
        c.fill = header_fill
        c.font = header_font
        c.alignment = center
        c.border = thin
    for i, lab in enumerate(serie["labels"]):
        row = 4 + i
        neto = serie["cobrado"][i] - serie["gastos"][i]
        vals = [lab, serie["cobrado"][i], serie["gastos"][i], neto, serie["altas"][i]]
        for col, v in enumerate(vals, 1):
            cell = ws2.cell(row=row, column=col, value=v)
            cell.border = thin
            if col > 1 and col < 5:
                cell.number_format = '#,##0'
            if row % 2 == 0:
                cell.fill = kpi_fill
    for col, w in zip("ABCDE", (12, 16, 16, 16, 10)):
        ws2.column_dimensions[col].width = w

    # Hoja 3: Metadatos
    ws3 = wb.create_sheet("Información")
    ws3["A1"] = "Generado por EduTrack Gerencia"
    ws3["A1"].font = title_font
    ws3["A3"] = "Periodo"
    ws3["B3"] = info["etiqueta"]
    ws3["A4"] = "Tipo"
    ws3["B4"] = periodo
    ws3["A5"] = "Desde"
    ws3["B5"] = info["desde"]
    ws3["A6"] = "Hasta"
    ws3["B6"] = info["hasta"]
    ws3["A7"] = "Fecha generación"
    try:
        ws3["B7"] = ahora().strftime("%Y-%m-%d %H:%M")
    except Exception:
        ws3["B7"] = ""
    ws3.column_dimensions["A"].width = 20
    ws3.column_dimensions["B"].width = 28

    buf = BytesIO()
    wb.save(buf)
    buf.seek(0)
    fname = f"EduTrack_Reporte_Gerencial_{periodo}_{info['mes']}.xlsx"
    return send_file(
        buf,
        as_attachment=True,
        download_name=fname,
        mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    )


