    """PDF empresarial de indicadores (mensual o quincenal)."""
    _g = _guard_gerencia()
    if _g is not None:
        return _g
    periodo = (request.args.get("periodo") or "mensual").strip().lower()
    if periodo not in ("mensual", "quincenal"):
        periodo = "mensual"
    info = _gerencia_periodo_info(periodo)
    m = _gerencia_metricas()
    serie = _gerencia_serie_mensual(6)
    e = m.get("embudo") or {}

    buf = BytesIO()
    c = canvas.Canvas(buf, pagesize=letter)
    W, H = letter
    # Header band
    c.setFillColor(colors.HexColor("#0B2D57"))
    c.rect(0, H - 72, W, 72, fill=1, stroke=0)
    c.setFillColor(colors.white)
    c.setFont("Helvetica-Bold", 16)
    c.drawString(36, H - 36, "EduTrack · Reporte gerencial")
    c.setFont("Helvetica", 10)
    c.drawString(36, H - 52, f"Periodo: {info['etiqueta']}  |  {info['desde']} → {info['hasta']}  |  {periodo.upper()}")
    y = H - 100
    c.setFillColor(colors.HexColor("#0f172a"))
    c.setFont("Helvetica-Bold", 12)
    c.drawString(36, y, "Indicadores financieros")
    y -= 18

    def row(label, value, y):
        c.setFont("Helvetica", 10)
        c.setFillColor(colors.HexColor("#334155"))
        c.drawString(40, y, label)
        c.setFont("Helvetica-Bold", 10)
        c.setFillColor(colors.HexColor("#0B2D57"))
        c.drawRightString(W - 40, y, str(value))
        c.setStrokeColor(colors.HexColor("#e2e8f0"))
        c.line(40, y - 4, W - 40, y - 4)
        return y - 16

    fin = [
        ("MRR", _cop(m["mrr"])),
        ("ARR", _cop(m["arr"])),
        ("Churn", f"{m['churn']}%"),
        ("Cashflow", _cop(m["cashflow"])),
        ("Margen", f"{m['margen']}%"),
        ("Cartera", _cop(m["cartera"])),
        ("Gastos periodo", _cop(m["gastos"])),
        ("Colegios activos", f"{m['activas']} (suspendidos: {m['suspendidas']})"),
    ]
    for lab, val in fin:
        y = row(lab, val, y)
        if y < 80:
            c.showPage()
            y = H - 50

    y -= 10
    c.setFont("Helvetica-Bold", 12)
    c.setFillColor(colors.HexColor("#0f172a"))
    c.drawString(36, y, "Crecimiento y ventas")
    y -= 18
    crec = [
        ("CAC", _cop(m["cac"])),
        ("LTV", _cop(m["ltv"])),
        ("ARPU", _cop(m["arpu"])),
        ("Altas", str(m["altas_mes"])),
        ("Cotización/Demo", str(e.get("cotizacion", 0))),
        ("Seguimiento", str(e.get("seguimiento", 0))),
        ("Cierres", str(e.get("cierres", 0))),
    ]
    for lab, val in crec:
        y = row(lab, val, y)

    y -= 10
    c.setFont("Helvetica-Bold", 12)
    c.setFillColor(colors.HexColor("#0f172a"))
    c.drawString(36, y, "Producto y soporte")
    y -= 18
    for lab, val in [
        ("DAU", str(m["dau"])),
        ("MAU", str(m["mau"])),
        ("PQR abiertas", f"{m['pqr_abiertas']} (cerradas: {m['pqr_cerradas']})"),
        ("SLA meta", f"{m['sla_horas']} h"),
        ("Servidores", m["srv_label"]),
    ]:
        y = row(lab, val, y)

    y -= 14
    c.setFont("Helvetica-Bold", 12)
    c.setFillColor(colors.HexColor("#0f172a"))
    c.drawString(36, y, "Serie últimos 6 meses")
    y -= 16
    c.setFont("Helvetica-Bold", 9)
    c.setFillColor(colors.white)
    c.setFillColor(colors.HexColor("#0B2D57"))
    c.rect(36, y - 4, W - 72, 16, fill=1, stroke=0)
    c.setFillColor(colors.white)
    c.drawString(40, y, "Mes")
    c.drawString(120, y, "Cobrado")
    c.drawString(220, y, "Gastos")
    c.drawString(320, y, "Neto")
    c.drawString(420, y, "Altas")
    y -= 18
    c.setFillColor(colors.HexColor("#0f172a"))
    c.setFont("Helvetica", 9)
    for i, lab in enumerate(serie["labels"]):
        if y < 50:
            c.showPage()
            y = H - 50
        neto = serie["cobrado"][i] - serie["gastos"][i]
        c.drawString(40, y, lab)
        c.drawString(120, y, f"{serie['cobrado'][i]:,.0f}".replace(",", "."))
        c.drawString(220, y, f"{serie['gastos'][i]:,.0f}".replace(",", "."))
        c.drawString(320, y, f"{neto:,.0f}".replace(",", "."))
        c.drawString(420, y, str(serie["altas"][i]))
        y -= 14

    c.setFont("Helvetica", 8)
    c.setFillColor(colors.HexColor("#94a3b8"))
    c.drawString(36, 28, "Documento generado por EduTrack Gerencia · uso interno")
    c.save()
    buf.seek(0)
    fname = f"EduTrack_Reporte_Gerencial_{periodo}_{info['mes']}.pdf"
    return send_file(buf, as_attachment=True, download_name=fname, mimetype="application/pdf")


