@app.route("/nueva_institucion", methods=["GET", "POST"])
def nueva_institucion():
    if not requiere_soporte_global():
        return redirect("/login")
    mensaje = ""
    if request.method == "POST":
        codigo = (request.form.get("codigo") or "").strip().upper()
        nombre = (request.form.get("nombre") or "").strip()
        if not codigo or not nombre:
            mensaje = "Código y nombre son obligatorios."
        elif Institucion.query.filter_by(codigo=codigo).first():
            mensaje = f"Ya existe una institución con código {codigo}."
        else:
            fi = (request.form.get("fecha_inicio_licencia") or fecha_hoy()).strip()
            fv = (request.form.get("fecha_vencimiento") or "").strip()
            try:
                dias_av = int(request.form.get("dias_aviso") or 7)
            except Exception:
                dias_av = 7
            try:
                dias_cons = int(request.form.get("dias_conservacion") or 30)
            except Exception:
                dias_cons = 30
            inst = Institucion(
                codigo=codigo,
                nombre=nombre,
                sede=(request.form.get("sede") or "PRINCIPAL").strip(),
                dane=(request.form.get("dane") or "").strip(),
                nit=(request.form.get("nit") or "").strip(),
                direccion=(request.form.get("direccion") or "").strip(),
                resolucion=(request.form.get("resolucion") or "").strip(),
                municipio=(request.form.get("municipio") or "").strip(),
                departamento=(request.form.get("departamento") or "").strip(),
                estado=(request.form.get("estado") or "ACTIVA").strip(),
                plan=(request.form.get("plan") or "Basico").strip(),
                fecha_creacion=fecha_hoy(),
                notas=(request.form.get("notas") or "").strip(),
                logo=DEFAULT_LOGO,
                fecha_inicio_licencia=fi,
                fecha_vencimiento=fv,
                dias_aviso=dias_av,
                dias_conservacion=dias_cons,
                contacto_facturacion=(request.form.get("contacto_facturacion") or "").strip(),
            )
            db.session.add(inst)
            db.session.flush()

            logo_file = request.files.get("logo")
            logo_path = DEFAULT_LOGO
            if logo_file and logo_file.filename:
                nueva = guardar_logo_institucional(logo_file, inst.id)
                if nueva:
                    logo_path = nueva
                    inst.logo = nueva

            cfg = Configuracion(
                institucion_id=inst.id,
                periodo_actual="Periodo 1",
                jornada="Mañana",
                inst_nombre=inst.nombre,
                inst_sede=inst.sede,
                inst_dane=inst.dane,
                inst_nit=inst.nit,
                inst_direccion=inst.direccion,
                inst_resolucion=inst.resolucion,
                inst_municipio=inst.municipio,
                inst_departamento=inst.departamento,
                logo_path=logo_path,
            )
            db.session.add(cfg)

            admin_user = (request.form.get("admin_usuario") or f"admin_{codigo.lower()}").strip()
            admin_pass = (request.form.get("admin_password") or "Colegio2026*").strip() or "Colegio2026*"
            # Usuario único global: si ya existe, agregar sufijo del código
            base_user = admin_user
            n = 1
            while Usuario.query.filter(func.lower(Usuario.usuario) == admin_user.lower()).first():
                admin_user = f"{base_user}_{codigo.lower()}" if n == 1 else f"{base_user}_{codigo.lower()}_{n}"
                n += 1
                if n > 20:
                    break
            db.session.add(Usuario(
                usuario=admin_user,
                password=crear_hash(admin_pass),
                rol="Administrador",
                correo=(request.form.get("admin_correo") or "").strip(),
                institucion_id=inst.id,
                password_temporal=True,
            ))
            try:
                crear_institucion(codigo, nombre, inst.municipio, inst.departamento, inst.estado)
            except Exception as e:
                print("tenants.db legacy:", e)
            db.session.commit()
            registrar_auditoria("Crear institución", f"{codigo} - {nombre} admin={admin_user}")
            # Guardar credenciales en flash de sesión para mostrarlas
            session["nuevo_tenant_info"] = {
                "codigo": codigo,
                "nombre": nombre,
                "usuario": admin_user,
                "password": admin_pass,
                "id": inst.id,
            }
            return redirect("/tenants")
