@app.route("/editar_institucion/<int:id>", methods=["GET", "POST"])
def editar_institucion(id):
    if not requiere_soporte_global():
        return redirect("/login")
    inst = Institucion.query.get_or_404(id)
    mensaje = ""
    if request.method == "POST":
        inst.nombre = (request.form.get("nombre") or inst.nombre).strip()
        inst.sede = (request.form.get("sede") or inst.sede).strip()
        inst.dane = (request.form.get("dane") or "").strip()
        inst.nit = (request.form.get("nit") or "").strip()
        inst.direccion = (request.form.get("direccion") or "").strip()
        inst.resolucion = (request.form.get("resolucion") or "").strip()
        inst.municipio = (request.form.get("municipio") or "").strip()
        inst.departamento = (request.form.get("departamento") or "").strip()
        inst.estado = (request.form.get("estado") or inst.estado).strip()
        nuevo_plan = (request.form.get("plan") or inst.plan or "Basico").strip()
        fecha_corte = (request.form.get("fecha_corte_plan") or "").strip()
        aplicar_ya = (request.form.get("aplicar_plan_inmediato") or "") == "1"
        plan_actual = (inst.plan or "Basico").strip()
        if nuevo_plan != plan_actual:
            if aplicar_ya or not fecha_corte:
                # Cambio inmediato: sistema aplica el plan de una
                inst.plan = nuevo_plan
                inst.plan_pendiente = ""
                inst.fecha_corte_plan = ""
                try:
                    registrar_auditoria("Cambio de plan inmediato", f"{inst.codigo}: {plan_actual} → {nuevo_plan}")
                except Exception:
                    pass
            else:
                # Programado a fecha de corte
                inst.plan_pendiente = nuevo_plan
                inst.fecha_corte_plan = fecha_corte
                try:
                    registrar_auditoria(
                        "Cambio de plan programado",
                        f"{inst.codigo}: {plan_actual} → {nuevo_plan} el {fecha_corte}",
                    )
                except Exception:
                    pass
        else:
            # Mismo plan: limpiar pendiente si pedían cancelar
            if request.form.get("cancelar_plan_pendiente") == "1":
                inst.plan_pendiente = ""
                inst.fecha_corte_plan = ""
        inst.notas = (request.form.get("notas") or "").strip()
        logo_file = request.files.get("logo")
        if logo_file and logo_file.filename:
            nueva = guardar_logo_institucional(logo_file, inst.id)
            if nueva:
                inst.logo = nueva
        cfg = Configuracion.query.filter_by(institucion_id=inst.id).first()
        if cfg:
            cfg.inst_nombre = inst.nombre
            cfg.inst_sede = inst.sede
            cfg.inst_dane = inst.dane
            cfg.inst_nit = inst.nit
            cfg.inst_direccion = inst.direccion
            cfg.inst_resolucion = inst.resolucion
            cfg.inst_municipio = inst.municipio
            cfg.inst_departamento = inst.departamento
            if logo_file and logo_file.filename and inst.logo:
                cfg.logo_path = inst.logo
        db.session.commit()
        # Si la fecha de corte ya llegó, aplicar ahora
        try:
            aplicar_cambios_plan_pendientes()
        except Exception:
            pass
        registrar_auditoria("Editar institución", f"{inst.codigo} - {inst.nombre}")
        mensaje = "Institución actualizada (logo, datos y plan)."
        if getattr(inst, "plan_pendiente", None):
            mensaje += f" Plan pendiente: {inst.plan_pendiente} a partir de {inst.fecha_corte_plan}."
    logo = logo_actual(inst.id)
    pend = (getattr(inst, "plan_pendiente", None) or "").strip()
    fcorte = (getattr(inst, "fecha_corte_plan", None) or "").strip()
    aviso_pend = ""
    if pend:
        aviso_pend = f"""<div class="msg ok" style="background:#eff6ff;border-color:#3b82f6;color:#1e40af">
          Plan pendiente: <b>{pend}</b> se aplicará el <b>{fcorte or '—'}</b> (fecha de corte).
          <label style="display:inline-flex;align-items:center;gap:6px;margin-left:12px;font-weight:600">
            <input type="checkbox" name="cancelar_plan_pendiente" value="1" form="form-edit-inst"> Cancelar cambio pendiente
          </label>
        </div>"""
    content = f"""
<header class='role-hero'><div><h1>Editar {inst.codigo}</h1><p>{inst.nombre}</p></div><a class='btn' href='/tenants'>Volver</a></header>
{'<div class="msg ok">'+mensaje+'</div>' if mensaje else ''}
{aviso_pend}
<section class='role-panel'>
<form method='POST' enctype='multipart/form-data' id='form-edit-inst'>
  <div class='student-section-title'>Logo</div>
  <div style='display:flex;gap:16px;align-items:center;flex-wrap:wrap;margin-bottom:12px'>
    <img src='{logo}' style='width:90px;height:90px;object-fit:contain;background:#fff;border-radius:14px;padding:6px;border:1px solid #dbe3f0'>
    <div><label><b>Cambiar logo</b></label><input type='file' name='logo' accept='image/png,image/jpeg,image/webp,image/gif'></div>
  </div>
  <label><b>Nombre</b></label><input name='nombre' value='{(inst.nombre or "").replace(chr(39),"")}' required>
  <div class='form-row'>
    <div><label><b>Sede</b></label><input name='sede' value='{(inst.sede or "").replace(chr(39),"")}'></div>
    <div><label><b>Estado</b></label>
      <select name='estado'>
        <option {'selected' if inst.estado=='ACTIVA' else ''}>ACTIVA</option>
        <option {'selected' if inst.estado=='SUSPENDIDA' else ''}>SUSPENDIDA</option>
        <option {'selected' if inst.estado=='MANTENIMIENTO' else ''}>MANTENIMIENTO</option>
      </select>
    </div>
  </div>
  <div class='form-row'>
    <div><label><b>DANE</b></label><input name='dane' value='{(inst.dane or "").replace(chr(39),"")}'></div>
    <div><label><b>NIT</b></label><input name='nit' value='{(inst.nit or "").replace(chr(39),"")}'></div>
  </div>
  <div class='form-row'>
    <div><label><b>Municipio</b></label><input name='municipio' value='{(inst.municipio or "").replace(chr(39),"")}'></div>
    <div><label><b>Departamento</b></label><input name='departamento' value='{(inst.departamento or "").replace(chr(39),"")}'></div>
  </div>
  <label><b>Dirección</b></label><input name='direccion' value='{(inst.direccion or "").replace(chr(39),"")}'>
  <label><b>Resolución</b></label><input name='resolucion' value='{(inst.resolucion or "").replace(chr(39),"")}'>
  <div class='student-section-title'>Plan comercial</div>
  <p class='mini-text'>Plan actual: <b>{inst.plan or 'Basico'}</b>. Soporte puede cambiar de plan; el sistema aplica el cambio en la fecha de corte (o de inmediato si marcas la casilla).</p>
  <div class='form-row'>
    <div>
      <label><b>Nuevo plan</b></label>
      <select name='plan'>
        <option {'selected' if (inst.plan or '')=='Basico' else ''}>Basico</option>
        <option {'selected' if (inst.plan or '')=='Institucional' else ''}>Institucional</option>
        <option {'selected' if (inst.plan or '')=='Premium' else ''}>Premium</option>
      </select>
    </div>
    <div>
      <label><b>Fecha de corte</b></label>
      <input type='date' name='fecha_corte_plan' value='{fcorte}'>
      <p class='field-help' style='font-size:12px;color:#64748b'>Si dejas vacía o marcas “aplicar ya”, el cambio es inmediato.</p>
    </div>
  </div>
  <label style='display:flex;align-items:center;gap:8px;margin:10px 0;font-weight:600'>
    <input type='checkbox' name='aplicar_plan_inmediato' value='1'> Aplicar cambio de plan de inmediato (no esperar fecha de corte)
  </label>
  <label><b>Notas</b></label><textarea name='notas' rows='3'>{(inst.notas or "").replace(chr(39),"")}</textarea>
  <button>Guardar cambios</button>
</form>
</section>
"""
    return page("Editar institución", shell(content))


@app.route("/eliminar_institucion/<int:id>", methods=["GET", "POST"])
def eliminar_institucion(id):
    """Borrado definitivo de institución. Limpia tablas hijas con savepoints
    (un fallo en una tabla no deshace el resto). Solo Gerencia/Admin."""
    if not requiere_login():
        return redirect("/login")
    if rol_actual() not in ("Gerente", "Superadmin", "Administrador"):
        return acceso_denegado("Solo Gerencia/Administrador puede dar de baja una institución definitivamente.")
    inst = Institucion.query.get_or_404(id)
    codigo = inst.codigo or str(id)
    nombre = inst.nombre or ""
    from sqlalchemy import text, inspect as sa_inspect

    def _safe_delete(fn, label=""):
        try:
            fn()
            db.session.commit()
            return True
        except Exception as e:
            try:
                db.session.rollback()
            except Exception:
                pass
            print(f"eliminar_institucion [{label}]:", e)
            return False

    try:
        iid = inst.id
        ids_estudiantes = [e.id for e in Estudiante.query.filter_by(institucion_id=iid).all()]
        ids_usuarios_colegio = [
            u.id for u in Usuario.query.filter(Usuario.institucion_id == iid).all()
            if (u.rol or "") != "Soporte"
        ]

        # 1) Tablas ORM con estudiante_id
        for mapper in db.Model.registry.mappers:
            cls = mapper.class_
            if cls is Institucion or cls is Estudiante or cls is Usuario:
                continue
            if hasattr(cls, "estudiante_id") and ids_estudiantes:
                _safe_delete(
                    lambda c=cls: c.query.filter(c.estudiante_id.in_(ids_estudiantes)).delete(synchronize_session=False),
                    f"est:{getattr(cls, '__tablename__', cls.__name__)}",
                )
            if hasattr(cls, "institucion_id"):
                _safe_delete(
                    lambda c=cls: c.query.filter(c.institucion_id == iid).delete(synchronize_session=False),
                    f"inst:{getattr(cls, '__tablename__', cls.__name__)}",
                )
            if hasattr(cls, "usuario_id") and ids_usuarios_colegio:
                _safe_delete(
                    lambda c=cls: c.query.filter(c.usuario_id.in_(ids_usuarios_colegio)).delete(synchronize_session=False),
                    f"usr:{getattr(cls, '__tablename__', cls.__name__)}",
                )

        # 2) SQL directo por inspector (cubre tablas sin modelo o FK raras)
        try:
            insp = sa_inspect(db.engine)
            for tname in insp.get_table_names():
                if tname in ("instituciones", "alembic_version"):
                    continue
                try:
                    cols = [c["name"] for c in insp.get_columns(tname)]
                except Exception:
                    continue
                if "institucion_id" in cols:
                    _safe_delete(
                        lambda tn=tname: db.session.execute(
                            text(f'DELETE FROM "{tn}" WHERE institucion_id = :iid'),
                            {"iid": iid},
                        ),
                        f"sql:{tname}",
                    )
                if "estudiante_id" in cols and ids_estudiantes:
                    # borrar en lotes
                    def _del_est(tn=tname, ids=ids_estudiantes):
                        for i in range(0, len(ids), 200):
                            chunk = ids[i:i+200]
                            db.session.execute(
                                text(f'DELETE FROM "{tn}" WHERE estudiante_id IN :ids').bindparams(
                                    # fallback simple
                                )
                            ) if False else db.session.execute(
                                text(f'DELETE FROM "{tn}" WHERE estudiante_id = ANY(:ids)'),
                                {"ids": chunk},
                            )
                    # PostgreSQL ANY; si falla, fila a fila
                    try:
                        _safe_delete(lambda: _del_est(), f"sql-est:{tname}")
                    except Exception:
                        for eid in ids_estudiantes:
                            _safe_delete(
                                lambda e=eid, tn=tname: db.session.execute(
                                    text(f'DELETE FROM "{tn}" WHERE estudiante_id = :e'),
                                    {"e": e},
                                ),
                                f"sql-est1:{tname}",
                            )
        except Exception as ex_insp:
            print("inspector cleanup:", ex_insp)

        # 3) TicketPQR ligados por codigo/nit sin institucion_id
        try:
            if codigo:
                _safe_delete(
                    lambda: TicketPQR.query.filter(TicketPQR.codigo_colegio == str(codigo)).delete(synchronize_session=False),
                    "pqr-codigo",
                )
            nit = (inst.nit or "").strip()
            if nit:
                _safe_delete(
                    lambda: TicketPQR.query.filter(TicketPQR.nit_colegio == nit).delete(synchronize_session=False),
                    "pqr-nit",
                )
        except Exception as ex_p:
            print("pqr cleanup:", ex_p)

        # 4) Usuarios del colegio
        for u in Usuario.query.filter(Usuario.institucion_id == iid).all():
            if (u.rol or "") == "Soporte":
                u.institucion_id = None
            else:
                try:
                    db.session.delete(u)
                except Exception:
                    pass
        try:
            db.session.commit()
        except Exception:
            db.session.rollback()

        # 5) Estudiantes
        _safe_delete(
            lambda: Estudiante.query.filter_by(institucion_id=iid).delete(synchronize_session=False),
            "estudiantes",
        )

        # 6) Institución
        inst2 = Institucion.query.get(iid)
        if inst2:
            try:
                db.session.delete(inst2)
                db.session.commit()
            except Exception as ex_final:
                db.session.rollback()
                # último recurso: SQL
                try:
                    db.session.execute(text('DELETE FROM instituciones WHERE id = :iid'), {"iid": iid})
                    db.session.commit()
                except Exception as ex2:
                    db.session.rollback()
                    session["flash_tenants"] = f"Error al eliminar: {ex2}"
                    registrar_auditoria("Error eliminar institución", str(ex2)[:200])
                    return redirect("/tenants")

        if session.get("institucion_id") == id:
            session.pop("institucion_id", None)
        registrar_auditoria("Eliminar institución", f"Borró {codigo} · {nombre}")
        session["flash_tenants"] = f"Institución '{nombre}' eliminada definitivamente."
    except Exception as ex:
        try:
            db.session.rollback()
        except Exception:
            pass
        session["flash_tenants"] = f"Error al eliminar: {ex}"
        registrar_auditoria("Error eliminar institución", str(ex)[:200])
    return redirect("/tenants")



