@app.route("/soporte/cancelaciones", methods=["GET", "POST"])
@app.route("/gerencia/cancelaciones", methods=["GET", "POST"])
def soporte_cancelaciones():
    """Módulo cancelación de servicio: Soporte y Gerencia. Cuenta regresiva + corte facturación."""
    rol = (rol_actual() or "").strip()
    if not requiere_login() or rol not in ("Soporte", "Gerente", "Superadmin", "Administrador"):
        if session.get("soporte"):
            pass
        else:
            return redirect("/soporte-login" if "soporte" in (request.path or "") else "/gerencia-login")
    try:
        _procesar_cuenta_regresiva_cancelaciones()
    except Exception:
        pass
    mensaje = ""
    error = ""
    if request.method == "POST":
        accion = (request.form.get("accion") or "actualizar").strip()
        if accion == "nueva":
            try:
                iid = int(request.form.get("institucion_id") or 0)
            except Exception:
                iid = 0
            inst = Institucion.query.get(iid) if iid else None
            motivo = (request.form.get("motivo") or "").strip()
            try:
                dias = int(request.form.get("dias_anticipacion") or 5)
            except Exception:
                dias = 5
            fe = (request.form.get("fecha_efectiva") or "").strip() or None
            if not inst or not motivo:
                error = "Colegio y motivo son obligatorios."
            elif getattr(inst, "no_generar_facturas", False) and (inst.estado or "") == "CANCELACION_PENDIENTE":
                error = f"{inst.codigo} ya tiene cancelación en curso."
            else:
                canal = "GERENCIA" if rol in ("Gerente", "Superadmin") else "SOPORTE"
                sol = _activar_cancelacion_servicio(
                    inst,
                    motivo=motivo,
                    solicitado_por=session.get("usuario") or rol,
                    canal=canal,
                    dias_anticipacion=dias,
                    fecha_efectiva=fe,
                )
                mensaje = (
                    f"Cancelación #{sol.id} de {inst.codigo}: fin {sol.fecha_efectiva}. "
                    f"Facturación futura DETENIDA. Prorrateo: {sol.valor_prorrateo or 0:,.0f} COP."
                )
        else:
            sid = request.form.get("solicitud_id")
            s = SolicitudCancelacion.query.get(sid)
            if s:
                nuevo_estado = (request.form.get("estado") or s.estado).strip()
                s.respuesta_soporte = (request.form.get("respuesta") or "").strip()
                nueva_fe = (request.form.get("fecha_efectiva") or "").strip()
                if nueva_fe:
                    s.fecha_efectiva = nueva_fe
                inst = Institucion.query.get(s.institucion_id)
                if nuevo_estado == "RECHAZADA" and inst:
                    s.estado = "RECHAZADA"
                    if inst.estado == "CANCELACION_PENDIENTE":
                        inst.estado = "ACTIVA"
                    inst.no_generar_facturas = False
                    inst.fecha_fin_servicio = ""
                    # no borramos factura_final_generada por auditoría
                    mensaje = "Cancelación rechazada. Colegio reactivado y facturación habilitada de nuevo."
                elif nuevo_estado == "EJECUTADA" and inst:
                    s.estado = "EJECUTADA"
                    inst.estado = "SUSPENDIDA"
                    inst.fecha_suspension = fecha_hoy()
                    inst.motivo_bloqueo = "Cancelación ejecutada. Datos en periodo de conservación."
                    inst.no_generar_facturas = True
                    mensaje = "Cancelación ejecutada. No se generarán más facturas."
                elif nuevo_estado == "APROBADA" and inst:
                    s.estado = "EN_CUENTA_REGRESIVA"
                    inst.estado = "CANCELACION_PENDIENTE"
                    inst.no_generar_facturas = True
                    if nueva_fe:
                        inst.fecha_fin_servicio = nueva_fe
                    mensaje = "Aprobada: cuenta regresiva activa y facturación futura detenida."
                else:
                    s.estado = nuevo_estado
                    mensaje = "Solicitud actualizada."
                db.session.commit()
                try:
                    registrar_auditoria("Cancelaciones admin", f"sol={s.id} → {s.estado}")
                except Exception:
                    pass

    sols = SolicitudCancelacion.query.order_by(SolicitudCancelacion.id.desc()).limit(100).all()
    instituciones = Institucion.query.order_by(Institucion.nombre.asc()).limit(300).all()
    opts = "".join(
        f'<option value="{i.id}">{i.codigo} — {i.nombre} [{i.estado}]</option>'
        for i in instituciones
    )
    from datetime import datetime as _dt
    try:
        hoy = ahora().date() if hasattr(ahora(), "date") else datetime.now().date()
    except Exception:
        hoy = datetime.now().date()

    filas = ""
    for s in sols:
        inst = Institucion.query.get(s.institucion_id)
        fe = (s.fecha_efectiva or "")[:10]
        dias_rest = "—"
        if fe:
            try:
                d = (_dt.strptime(fe, "%Y-%m-%d").date() - hoy).days
                dias_rest = f"{d} d" if d >= 0 else "vencido"
            except Exception:
                pass
        no_fac = "Sí" if (inst and getattr(inst, "no_generar_facturas", False)) else "No"
        filas += f"""<tr>
          <td>{s.id}</td>
          <td>{inst.codigo if inst else s.institucion_id}<br><span style="font-size:11px;color:#64748b">{inst.nombre if inst else ''}</span></td>
          <td>{s.fecha} {s.hora}<br><span style="font-size:11px">{getattr(s,'canal',None) or '—'}</span></td>
          <td>{s.solicitado_por}</td>
          <td style="max-width:180px">{(s.motivo or '')[:100]}</td>
          <td><b>{s.estado}</b></td>
          <td>{fe}<br><span style="color:#b45309;font-weight:700">{dias_rest}</span></td>
          <td>{no_fac}<br><span style="font-size:11px">{(s.valor_prorrateo or 0):,.0f} COP</span></td>
          <td>
            <form method="POST" style="display:flex;flex-direction:column;gap:4px;min-width:160px">
              <input type="hidden" name="solicitud_id" value="{s.id}">
              <input type="hidden" name="accion" value="actualizar">
              <select name="estado" style="padding:4px;border-radius:6px;border:1px solid #cbd5e1">
                {''.join(f'<option {"selected" if s.estado==st else ""}>{st}</option>' for st in ("PENDIENTE","EN_CUENTA_REGRESIVA","APROBADA","RECHAZADA","EJECUTADA"))}
              </select>
              <input name="fecha_efectiva" type="date" value="{fe}" style="padding:4px;border-radius:6px;border:1px solid #cbd5e1">
              <input name="respuesta" placeholder="Respuesta" value="{(s.respuesta_soporte or '').replace(chr(34),'')}" style="padding:4px;border-radius:6px;border:1px solid #cbd5e1">
              <button style="background:#0B2D57;color:#fff;border:0;padding:6px;border-radius:6px;font-weight:700;cursor:pointer">Guardar</button>
            </form>
          </td>
        </tr>"""

    shell_fn = shell_soporte if rol == "Soporte" or session.get("soporte") else (lambda x: x)
    content = f"""
<style>
.cx .hero{{background:linear-gradient(135deg,#7c2d12,#9a3412);color:#fff;border-radius:16px;padding:18px 20px;margin-bottom:14px}}
.cx .box{{background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:16px;margin-bottom:14px}}
.cx table{{width:100%;border-collapse:collapse;font-size:12px}}
.cx th{{background:#7c2d12;color:#fff;padding:8px;text-align:left}}
.cx td{{padding:8px;border-bottom:1px solid #e2e8f0;vertical-align:top}}
.cx label{{font-weight:700;font-size:12px;display:block;margin:6px 0 4px}}
.cx input,.cx select,.cx textarea{{width:100%;padding:8px;border:1px solid #cbd5e1;border-radius:8px;box-sizing:border-box}}
.cx .row{{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px}}
@media(max-width:800px){{.cx .row{{grid-template-columns:1fr}}}}
</style>
<div class="cx">
  <div class="hero">
    <h1 style="margin:0">Cancelaciones de servicio</h1>
    <p style="margin:6px 0 0;opacity:.92;font-size:13px">Soporte y Gerencia. Al registrar/aprobar: <b>cuenta regresiva</b>,
    <b>no se generan más facturas</b> de ciclos futuros, y si cancela a mitad de mes se cobra solo el <b>prorrateo</b>.</p>
  </div>
  {"<div class='msg ok'>"+mensaje+"</div>" if mensaje else ""}
  {"<div class='msg danger'>"+error+"</div>" if error else ""}

  <div class="box">
    <h2 style="margin:0 0 10px;font-size:15px;color:#7c2d12">Iniciar cancelación (Soporte / Gerencia)</h2>
    <form method="POST">
      <input type="hidden" name="accion" value="nueva">
      <div class="row">
        <div>
          <label>Colegio *</label>
          <select name="institucion_id" required><option value="">— Seleccione —</option>{opts}</select>
        </div>
        <div>
          <label>Días anticipación</label>
          <input type="number" name="dias_anticipacion" value="5" min="5">
        </div>
        <div>
          <label>Fecha efectiva (opcional)</label>
          <input type="date" name="fecha_efectiva">
        </div>
      </div>
      <label>Motivo *</label>
      <textarea name="motivo" rows="3" required placeholder="Motivo de la cancelación..."></textarea>
      <button type="submit" style="margin-top:10px;background:#7c2d12;color:#fff;border:0;padding:10px 16px;border-radius:10px;font-weight:800;cursor:pointer">
        Iniciar cancelación + detener facturas futuras
      </button>
    </form>
  </div>

  <div class="box">
    <h2 style="margin:0 0 10px;font-size:15px;color:#7c2d12">Solicitudes y cuenta regresiva</h2>
    <div style="overflow-x:auto">
      <table>
        <tr>
          <th>ID</th><th>Colegio</th><th>Fecha / canal</th><th>Quién</th><th>Motivo</th>
          <th>Estado</th><th>Fin / countdown</th><th>Sin facturas / prorrateo</th><th>Acción</th>
        </tr>
        {filas or '<tr><td colspan="9">Sin solicitudes</td></tr>'}
      </table>
    </div>
  </div>
</div>
"""
    if rol == "Soporte" or session.get("soporte"):
        return page("Cancelaciones", shell_soporte(content))
    return page("Cancelaciones · Gerencia", content)


