@app.route("/notas/siee", methods=["GET", "POST"])
def notas_siee():
    if not requiere_login():
        return redirect("/login")
    if rol_actual() not in ["Administrador", "Rectoría", "Soporte"]:
        return acceso_denegado()
    iid = institucion_id_actual()
    mensaje = ""
    dims = SieeDimension.query.filter_by(institucion_id=iid).order_by(SieeDimension.orden.asc()).all()
    if not dims and iid:
        for nom, pct, ord_ in [("Cognitivo", 40, 1), ("Procedimental", 40, 2), ("Actitudinal", 20, 3)]:
            db.session.add(SieeDimension(institucion_id=iid, nombre=nom, porcentaje=pct, orden=ord_))
        db.session.commit()
        dims = SieeDimension.query.filter_by(institucion_id=iid).order_by(SieeDimension.orden.asc()).all()
    if request.method == "POST":
        for d in dims:
            try:
                d.porcentaje = float(request.form.get(f"pct_{d.id}") or d.porcentaje)
            except Exception:
                pass
        db.session.commit()
        mensaje = "SIEE actualizado."
        if request.form.get("nuevo_criterio"):
            try:
                did = int(request.form.get("dimension_id"))
                pct = float(request.form.get("criterio_pct") or 0)
            except Exception:
                did, pct = None, 0
            nom = (request.form.get("criterio_nombre") or "").strip()
            if did and nom:
                db.session.add(SieeCriterio(
                    institucion_id=iid, dimension_id=did, nombre=nom, porcentaje=pct,
                    asignatura=(request.form.get("asignatura") or "").strip(),
                    grado=(request.form.get("grado") or "").strip(),
                    periodo=periodo_actual(),
                ))
                db.session.commit()
                mensaje = "Criterio agregado."
    dims = SieeDimension.query.filter_by(institucion_id=iid).order_by(SieeDimension.orden.asc()).all()
    filas_d = "".join(
        f"<tr><td>{d.nombre}</td><td><input name='pct_{d.id}' type='number' step='0.1' value='{d.porcentaje}' style='width:90px'></td></tr>"
        for d in dims
    )
    opts_d = "".join(f"<option value='{d.id}'>{d.nombre}</option>" for d in dims)
    crits = SieeCriterio.query.filter_by(institucion_id=iid).order_by(SieeCriterio.id.desc()).limit(50).all()
    filas_c = "".join(
        f"<tr><td>{c.nombre}</td><td>{c.porcentaje}%</td><td>{c.asignatura or '—'}</td><td>{c.grado or '—'}</td></tr>"
        for c in crits
    ) or "<tr><td colspan='4'>Sin sub-criterios aún</td></tr>"
    content = f"""
<header class='role-hero'><div><h1>Configurador SIEE</h1><p>Cognitivo / Procedimental / Actitudinal + sub-casillas.</p></div>
<a class='btn' href='/notas'>Volver</a></header>
{'<div class="msg ok">'+mensaje+'</div>' if mensaje else ''}
<section class='role-grid'>
  <div class='role-panel'>
    <h2>Dimensiones</h2>
    <form method='POST'>
      <table><tr><th>Dimensión</th><th>%</th></tr>{filas_d}</table>
      <button>Guardar dimensiones</button>
    </form>
  </div>
  <div class='role-panel'>
    <h2>Sub-porcentaje</h2>
    <form method='POST'>
      <input type='hidden' name='nuevo_criterio' value='1'>
      <label><b>Dimensión</b></label><select name='dimension_id'>{opts_d}</select>
      <label><b>Nombre</b></label><input name='criterio_nombre' placeholder='Evaluación escrita 1' required>
      <label><b>% dentro de la dimensión</b></label><input name='criterio_pct' type='number' step='0.1' value='15'>
      <label><b>Asignatura</b></label><input name='asignatura' placeholder='Biología'>
      <label><b>Grado</b></label><input name='grado' placeholder='8'>
      <button>Agregar criterio</button>
    </form>
  </div>
</section>
<section class='table-card'><h2>Criterios</h2>
<table><tr><th>Criterio</th><th>%</th><th>Asignatura</th><th>Grado</th></tr>{filas_c}</table>
</section>
"""
    return page("SIEE", shell(content))




@app.route("/notas/componentes", methods=["GET", "POST"])
def notas_componentes():
    """Configura columnas tipo Excel: Cognitivo / Actitudinal / Procedimental + logros."""
    if not requiere_login():
        return redirect("/login")
    if rol_actual() not in ["Administrador", "Rectoría", "Coordinación", "Secretaría", "Soporte"]:
        return acceso_denegado("Solo Secretaría y dirección configuran los componentes de evaluación. El docente solo digita notas en la planilla.")
    iid = institucion_id_actual()
    asignatura = (request.values.get("asignatura") or "General").strip()
    mensaje = ""

    # Defaults SIEE Colombia
    DEFAULTS = [
        ("Cognitivo", 40, 1, ["Taller", "Quiz", "Trabajo", "Participación", "Evaluación Final"]),
        ("Actitudinal", 20, 2, ["Responsabilidad", "Puntualidad", "Convivencia", "Respeto", "Participación"]),
        ("Procedimental", 40, 3, ["Prácticas", "Proyectos", "Laboratorios", "Exposiciones", "Evidencias"]),
    ]

    def ensure_dims():
        dims = SieeDimension.query.filter_by(institucion_id=iid).order_by(SieeDimension.orden.asc()).all()
        if not dims and iid is not None:
            for nom, pct, ord_, cols in DEFAULTS:
                d = SieeDimension(institucion_id=iid, nombre=nom, porcentaje=pct, orden=ord_)
                db.session.add(d)
                db.session.flush()
                for cname in cols:
                    db.session.add(SieeCriterio(
                        institucion_id=iid, dimension_id=d.id,
                        nombre=cname, porcentaje=0, asignatura=asignatura,
                    ))
            # Logros
            d0 = SieeDimension.query.filter_by(institucion_id=iid).order_by(SieeDimension.orden.asc()).first()
            for i in range(1, 3):
                db.session.add(SieeCriterio(
                    institucion_id=iid, dimension_id=d0.id if d0 else None,
                    nombre=f"LOG{i}", porcentaje=0, asignatura=asignatura,
                ))
            db.session.commit()
            dims = SieeDimension.query.filter_by(institucion_id=iid).order_by(SieeDimension.orden.asc()).all()
        return dims

    dims = ensure_dims()

    if request.method == "POST":
        accion = request.form.get("accion") or "guardar"
        if accion == "guardar":
            total = 0
            for d in dims:
                nom = (request.form.get(f"dim_nombre_{d.id}") or d.nombre).strip()[:80]
                try:
                    pct = float(request.form.get(f"dim_pct_{d.id}") or d.porcentaje)
                except Exception:
                    pct = d.porcentaje
                d.nombre = nom
                d.porcentaje = max(0, min(100, pct))
                total += d.porcentaje
                # rename columns
                crits = SieeCriterio.query.filter(
                    SieeCriterio.institucion_id == iid,
                    SieeCriterio.dimension_id == d.id,
                    ~SieeCriterio.nombre.like("LOG%"),
                ).order_by(SieeCriterio.id.asc()).all()
                for c in crits:
                    newn = (request.form.get(f"col_{c.id}") or c.nombre).strip()[:120]
                    if newn:
                        c.nombre = newn
            # logros count rename
            logs = SieeCriterio.query.filter(
                SieeCriterio.institucion_id == iid, SieeCriterio.nombre.like("LOG%")
            ).order_by(SieeCriterio.nombre.asc()).all()
            for c in logs:
                newn = (request.form.get(f"col_{c.id}") or c.nombre).strip()[:120]
                if newn:
                    c.nombre = newn
            db.session.commit()
            if abs(total - 100) > 0.5:
                mensaje = f"Guardado. Suma de % = {total:g} (ideal 100)."
            else:
                mensaje = "Componentes y nombres de columnas guardados."
        elif accion == "add_col":
            try:
                did = int(request.form.get("dimension_id"))
            except Exception:
                did = 0
            d = SieeDimension.query.get(did)
            nombre = (request.form.get("nuevo_nombre") or "Nueva casilla").strip()[:120]
            if d and (d.institucion_id == iid or rol_actual() == "Soporte"):
                db.session.add(SieeCriterio(
                    institucion_id=iid, dimension_id=d.id,
                    nombre=nombre or "Nueva casilla", porcentaje=0, asignatura=asignatura,
                ))
                db.session.commit()
                mensaje = f"Columna '{nombre}' agregada a {d.nombre}."
        elif accion == "del_col":
            try:
                cid = int(request.form.get("criterio_id"))
            except Exception:
                cid = 0
            c = SieeCriterio.query.get(cid)
            if c and (c.institucion_id == iid or rol_actual() == "Soporte") and not (c.nombre or "").startswith("LOG"):
                db.session.delete(c)
                db.session.commit()
                mensaje = "Columna eliminada."

        dims = SieeDimension.query.filter_by(institucion_id=iid).order_by(SieeDimension.orden.asc()).all()

    mats = todas_materias()
    mat_opts = "".join(
        f'<option value="{m}" {"selected" if m==asignatura else ""}>{m}</option>' for m in mats
    )

    bloques = ""
    for d in dims:
        crits = SieeCriterio.query.filter(
            SieeCriterio.institucion_id == iid,
            SieeCriterio.dimension_id == d.id,
            ~SieeCriterio.nombre.like("LOG%"),
        ).order_by(SieeCriterio.id.asc()).all()
        filas_col = ""
        for c in crits:
            filas_col += (
                f"<tr><td><input name='col_{c.id}' value='{(c.nombre or '').replace(chr(39),'')}' "
                f"style='width:100%;font-size:13px'></td>"
                f"<td style='width:90px'><form method='POST' style='display:inline'>"
                f"<input type='hidden' name='accion' value='del_col'>"
                f"<input type='hidden' name='criterio_id' value='{c.id}'>"
                f"<input type='hidden' name='asignatura' value='{asignatura}'>"
                f"<button class='btn-red' style='padding:3px 8px;font-size:11px'>Quitar</button></form></td></tr>"
            )
        bloques += f"""
        <section class="role-panel" style="margin-bottom:12px">
          <div class="form-row" style="display:grid;grid-template-columns:1.5fr 100px;gap:10px;align-items:end">
            <div><label><b>Componente</b></label>
              <input name="dim_nombre_{d.id}" value="{(d.nombre or '').replace(chr(39),'')}" form="fcomp"></div>
            <div><label><b>% peso</b></label>
              <input type="number" name="dim_pct_{d.id}" min="0" max="100" step="1" value="{d.porcentaje:g}" form="fcomp"></div>
          </div>
          <p class="mini-text" style="margin:6px 0">Columnas (tipo Excel: renombra como "Trabajo de matemáticas", "Quiz 1", etc.)</p>
          <table style="width:100%;font-size:13px"><tr><th>Nombre de la casilla</th><th></th></tr>{filas_col}</table>
          <form method="POST" style="display:flex;gap:8px;margin-top:8px;align-items:end">
            <input type="hidden" name="accion" value="add_col">
            <input type="hidden" name="dimension_id" value="{d.id}">
            <input type="hidden" name="asignatura" value="{asignatura}">
            <input name="nuevo_nombre" placeholder="Nueva columna..." style="flex:1">
            <button style="padding:6px 12px">+ Columna</button>
          </form>
        </section>
        """

    logs = SieeCriterio.query.filter(
        SieeCriterio.institucion_id == iid, SieeCriterio.nombre.like("LOG%")
    ).order_by(SieeCriterio.nombre.asc()).all()
    log_html = ""
    for c in logs:
        log_html += f"<div style='margin-bottom:6px'><input name='col_{c.id}' value='{(c.nombre or '').replace(chr(39),'')}' form='fcomp' style='width:100%'></div>"

    content = f"""
<div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px;margin-bottom:14px">
  <div>
    <h1 style="margin:0;font-size:20px">Componentes de evaluación</h1>
    <p class="mini-text">Cognitivo (saber) · Actitudinal (ser) · Procedimental (hacer) — columnas renombrables tipo Excel</p>
  </div>
  <a class="btn" href="/notas/planilla?asignatura={asignatura}">Abrir planilla</a>
</div>
{"<div class='msg ok'>"+mensaje+"</div>" if mensaje else ""}
<form method="GET" style="margin-bottom:12px;max-width:420px">
  <label><b>Materia</b></label>
  <select name="asignatura" onchange="this.form.submit()">
    <option value="General" {"selected" if asignatura=="General" else ""}>General</option>
    {mat_opts}
  </select>
</form>
<form method="POST" id="fcomp">
  <input type="hidden" name="accion" value="guardar">
  <input type="hidden" name="asignatura" value="{asignatura}">
  {bloques}
  <section class="role-panel" style="margin-bottom:12px">
    <h3 style="margin-top:0;font-size:14px">Logros (texto / código)</h3>
    {log_html if log_html else "<p class='mini-text'>LOG1, LOG2 se crean al abrir la planilla.</p>"}
  </section>
  <button>Guardar nombres y porcentajes</button>
</form>
<p class="mini-text" style="margin-top:10px">
  Definitiva = Prom. Cognitivo × % + Prom. Actitudinal × % + Prom. Procedimental × %.
  Cada promedio es el promedio simple de las casillas del componente.
</p>
"""
    return page("Componentes", shell(content))






# ===================== MOTOR SIEE / BOLETINES =====================
# Cognitivo 45% | Procedimental 40% | Actitudinal 15%
# Subcriterios con peso sobre la nota del periodo.

SIEE_SCHEMA = [
    {
        "nombre": "Cognitivo",
        "pct": 45,
        "orden": 1,
        "grupos": [
            {"nombre": "Quices / Eval. cortas", "pct": 30, "casillas": 5, "prefijo": "Quiz"},
            {"nombre": "Evaluación Final", "pct": 15, "casillas": 1, "prefijo": "Eval. Final"},
        ],
    },
    {
        "nombre": "Procedimental",
        "pct": 40,
        "orden": 2,
        "grupos": [
            {"nombre": "Trabajos", "pct": 30, "casillas": 5, "prefijo": "Trabajo"},
            {"nombre": "Tareas", "pct": 20, "casillas": 5, "prefijo": "Tarea"},
            # Nota: Trabajos 30 + Tareas 20 = 50 del total? User said Procedimental 40% with
            # Trabajos 20 + Tareas 20. Commercial message also said Trabajos 30.
            # Usamos: Trabajos 20, Talleres/Quices ya en cognitivo, Tareas 20 dentro de 40.
            # Ajuste final abajo en ensure_siee_schema.
        ],
    },
    {
        "nombre": "Actitudinal",
        "pct": 15,
        "orden": 3,
        "grupos": [
            {"nombre": "Autoevaluación", "pct": 5, "casillas": 1, "prefijo": "Autoeval"},
            {"nombre": "Coevaluación", "pct": 10, "casillas": 1, "prefijo": "Coeval"},
        ],
    },
]

# Estructura operativa exacta pedida:
# Trabajos 30% (5), Tareas 20% (5), Talleres/Quices 20% (5), Eval Final 15% (1), Actitudinal 15% (1-2)
SIEE_CASILLAS = [
    # Dimensión | % | N casillas | prefijo  (suma 100%)
    ("Cognitivo", 30.0, 10, "Cog"),        # 10 notas (sin EFP)
    ("EFP", 15.0, 1, "EFP"),               # Evaluación final del periodo — 15% aparte
    ("Procedimental", 40.0, 10, "Proc"),   # 10 notas
    ("Actitudinal", 15.0, 5, "Act"),       # Autoeval + Coeval + 3
]


def ensure_siee_schema(iid, asignatura="General"):
    """Crea dimensiones y criterios SIEE por MATERIA (nombres y notas independientes)."""
    if iid is None:
        return [], []
    asig = (asignatura or "").strip() or "Matemáticas"
    dims = []
    for orden, (nombre, pct, n_cas, pref) in enumerate(SIEE_CASILLAS, 1):
        d = SieeDimension.query.filter_by(institucion_id=iid, nombre=nombre).first()
        if not d:
            d = SieeDimension(institucion_id=iid, nombre=nombre, porcentaje=pct, orden=orden)
            db.session.add(d)
            db.session.flush()
        else:
            d.orden = orden
            # Sincroniza % estándar de Cognitivo/EFP/Procedimental/Actitudinal
            if (nombre or "") in ("Cognitivo", "EFP", "Procedimental", "Actitudinal") or (nombre or "").startswith("EFP"):
                d.porcentaje = pct
            elif d.porcentaje is None:
                d.porcentaje = pct
        # Criterios SOLO de esta materia
        slots = SieeCriterio.query.filter(
            SieeCriterio.institucion_id == iid,
            SieeCriterio.dimension_id == d.id,
            SieeCriterio.asignatura == asig,
            ~SieeCriterio.nombre.like("LOG%"),
        ).order_by(SieeCriterio.id.asc()).all()
        if len(slots) < n_cas:
            for i in range(len(slots) + 1, n_cas + 1):
                label = pref if n_cas == 1 else f"{pref} {i}"
                if nombre.startswith("Actitudinal"):
                    if i == 1:
                        label = "Autoevaluación"
                    elif i == 2:
                        label = "Coevaluación"
                    else:
                        label = f"{pref} {i}"
                if nombre.strip().upper() == "EFP" or nombre.startswith("EFP"):
                    label = "EFP"
                db.session.add(SieeCriterio(
                    institucion_id=iid, dimension_id=d.id,
                    nombre=label, porcentaje=0, asignatura=asig,
                ))
            db.session.flush()
            slots = SieeCriterio.query.filter(
                SieeCriterio.institucion_id == iid,
                SieeCriterio.dimension_id == d.id,
                SieeCriterio.asignatura == asig,
                ~SieeCriterio.nombre.like("LOG%"),
            ).order_by(SieeCriterio.id.asc()).all()
        slots = slots[:n_cas]
        # Dimensión EFP: una sola casilla llamada EFP
        if (nombre or "").strip().upper() == "EFP" and slots:
            slots[0].nombre = "EFP"
        # Actitudinal: primeras dos fijas
        if nombre.startswith("Actitudinal") and len(slots) >= 2:
            if (slots[0].nombre or "") != "Autoevaluación":
                slots[0].nombre = "Autoevaluación"
            if (slots[1].nombre or "") != "Coevaluación":
                slots[1].nombre = "Coevaluación"
        dims.append((d, slots))
    # LOG por materia
    logs = SieeCriterio.query.filter(
        SieeCriterio.institucion_id == iid,
        SieeCriterio.asignatura == asig,
        SieeCriterio.nombre.like("LOG%"),
    ).order_by(SieeCriterio.nombre.asc()).all()
    if len(logs) < 1:
        d0 = dims[0][0] if dims else None
        if d0:
            db.session.add(SieeCriterio(
                institucion_id=iid, dimension_id=d0.id,
                nombre="LOG1", porcentaje=0, asignatura=asig,
            ))
        db.session.flush()
        logs = SieeCriterio.query.filter(
            SieeCriterio.institucion_id == iid,
            SieeCriterio.asignatura == asig,
            SieeCriterio.nombre.like("LOG%"),
        ).order_by(SieeCriterio.nombre.asc()).all()
    db.session.commit()
    return dims, logs[:1]


def calc_nota_periodo(est_id, dim_slots, notas_map):
    """
    NDN = suma (promedio de casillas de cada dimensión × % de la dimensión).
    EFP es dimensión aparte (15%): no va dentro de Cognitivo.

    Muestra NDN en cuanto hay al menos 1 nota normal + EFP (o pesos cargados).
    Cláusula: si EFP < 3.0 → periodo en BAJO (nota max 2.9).
    """
    total = 0.0
    peso_usado = 0.0
    detalle = []
    eval_final_prom = None
    notas_normales = 0
    notas_actitudinal = 0
    tiene_eval_final = False
    for d, slots in dim_slots:
        vals = []
        for c in slots:
            v = notas_map.get((est_id, c.id))
            if v is not None:
                try:
                    vals.append(float(v))
                except Exception:
                    pass
            # también detectar EFP por nombre de criterio
            cn = (c.nombre or "").upper()
            if cn.startswith("EFP") or "EVAL" in cn and "FINAL" in cn:
                if v is not None:
                    try:
                        eval_final_prom = float(v)
                        tiene_eval_final = True
                    except Exception:
                        pass
        nombre_d = (d.nombre or "")
        nd_up = nombre_d.upper()
        if not vals:
            detalle.append((nombre_d, None, float(d.porcentaje or 0)))
            continue
        prom = sum(vals) / len(vals)
        pct = float(d.porcentaje or 0)
        total += prom * (pct / 100.0)
        peso_usado += pct
        detalle.append((nombre_d, prom, pct))
        if nd_up == "EFP" or nd_up.startswith("EFP") or "EVALUACIÓN FINAL" in nd_up or "EVALUACION FINAL" in nd_up:
            eval_final_prom = prom
            tiene_eval_final = True
        elif "COGNITIVO" in nd_up:
            notas_normales += len(vals)  # notas de cognitivo
        elif "ACTITUDINAL" in nd_up or "SER" in nd_up:
            notas_actitudinal += len(vals)
        else:
            # procedimental u otros: cuentan como normales de apoyo pero NDN exige cognitivo
            pass
    # NDN solo si hay EFP + al menos 1 nota de Cognitivo (EFP es la más importante)
    cerrado = bool(tiene_eval_final and notas_normales >= 1)
    if peso_usado <= 0:
        return None, detalle, cerrado, False
    if peso_usado > 0 and peso_usado < 99.5:
        total = total * (100.0 / peso_usado)
    forzado_bajo = False
    if tiene_eval_final and eval_final_prom is not None and eval_final_prom < 3.0:
        total = min(float(eval_final_prom), 2.9)
        forzado_bajo = True
    if not cerrado:
        return None, detalle, cerrado, forzado_bajo
    return round(float(total), 2), detalle, cerrado, forzado_bajo


def calc_nota_anual(est_id, iid, asignatura, dim_slots):
    """Promedio simple de Periodo 1, 2 y 3 (≈ 33.3% cada uno)."""
    periodos = ["Periodo 1", "Periodo 2", "Periodo 3"]
    notas = []
    for per in periodos:
        all_ids = [c.id for d, slots in dim_slots for c in slots]
        if not all_ids:
            continue
        regs = NotaRegistro.query.filter(
            NotaRegistro.institucion_id == iid,
            NotaRegistro.estudiante_id == est_id,
            NotaRegistro.criterio_id.in_(all_ids),
            NotaRegistro.periodo == per,
        ).all()
        nmap = {(r.estudiante_id, r.criterio_id): r.valor for r in regs if r.valor is not None}
        n, _, _cerrado_tmp, _forzado_tmp = calc_nota_periodo(est_id, dim_slots, nmap)
        if n is not None:
            notas.append(n)
    if not notas:
        return None
    return sum(notas) / len(notas)


def desempeno_label(n):
    if n is None:
        return "—", ""
    if n >= 4.6:
        return "SUPERIOR", "des-superior"
    if n >= 4.0:
        return "ALTO", "des-alto"
    if n >= 3.0:
        return "BASICO", "des-basico"
    return "BAJO", "des-bajo"


@app.route("/notas/planilla")
def notas_planilla():
    """Planilla SIEE pantalla completa + motor de definitivas."""
    if not requiere_login():
        return redirect("/login")
    if not puede_ver_notas():
        return acceso_denegado()
    solo_lectura = not puede_editar_notas()

    iid = institucion_id_actual()
    grado = (request.args.get("grado") or "").strip()
    asignatura = (request.args.get("asignatura") or "").strip()
    if asignatura in ("General", "general"):
        asignatura = ""
    periodo = (request.args.get("periodo") or periodo_actual()).strip()
    filtro = (request.args.get("filtro") or "todos").strip().lower()

    mats_doc = materias_docente_actual()
    grados_doc = grados_docente_actual()
    if mats_doc is not None:
        if not mats_doc:
            return page("Planilla", """
            <div style="padding:40px;font-family:Segoe UI,Arial">
              <div style="background:#fef2f2;border:1px solid #fecaca;padding:16px;border-radius:12px;color:#991b1b">
                No tienes materias asignadas.
              </div>
              <p style="margin-top:16px"><a href="/docente-escritorio" style="color:#2563eb">← Volver</a></p>
            </div>""")
        if asignatura and asignatura not in mats_doc:
            asignatura = ""
        if grados_doc and grado and grado not in grados_doc:
            grado = ""

    # Planilla vacía hasta elegir GRADO + MATERIA (sin opción General)
    dim_slots, log_slots = ensure_siee_schema(iid, asignatura or "Matemáticas")
    all_ids = [c.id for d, slots in dim_slots for c in slots] + [c.id for c in log_slots]
    notas_map, logro_map = {}, {}
    estudiantes_all = []
    if grado and asignatura:
        est_q = q_estudiantes().filter(Estudiante.grado == grado)
        estudiantes_all = est_q.order_by(Estudiante.apellido.asc(), Estudiante.nombre.asc()).limit(250).all()
        if estudiantes_all and all_ids:
            qn = NotaRegistro.query.filter(
                NotaRegistro.institucion_id == iid,
                NotaRegistro.estudiante_id.in_([e.id for e in estudiantes_all]),
                NotaRegistro.criterio_id.in_(all_ids),
                NotaRegistro.periodo == periodo,
                NotaRegistro.asignatura == asignatura,
            )
            for r in qn.all():
                if r.valor is not None:
                    notas_map[(r.estudiante_id, r.criterio_id)] = r.valor
                if r.logro:
                    logro_map[(r.estudiante_id, r.criterio_id)] = r.logro

    faltas_map = {}  # est_id -> {nj, fj}
    if estudiantes_all and grado and asignatura:
        for fp in FaltaPlanilla.query.filter(
            FaltaPlanilla.institucion_id == iid,
            FaltaPlanilla.estudiante_id.in_([e.id for e in estudiantes_all]),
            FaltaPlanilla.asignatura == asignatura,
            FaltaPlanilla.periodo == periodo,
        ).all():
            faltas_map[fp.estudiante_id] = {"nj": fp.nj or 0, "fj": fp.fj or 0}
    for e in estudiantes_all:
        if e.id not in faltas_map:
            faltas_map[e.id] = {"nj": 0, "fj": 0}

    def_map = {}
    for e in estudiantes_all:
        n, _det, cerrado, forzado = calc_nota_periodo(e.id, dim_slots, notas_map)
        if n is not None and cerrado:
            def_map[e.id] = n

    estudiantes = estudiantes_all
    if filtro == "perdidos":
        estudiantes = [e for e in estudiantes if e.id in def_map and def_map[e.id] < 3.0]
    elif filtro == "aprobados":
        estudiantes = [e for e in estudiantes if e.id in def_map and def_map[e.id] >= 3.0]

    lista_grados = grados_disponibles()
