@app.route("/soporte/seguridad-empleados", methods=["GET", "POST"])
def soporte_seguridad_empleados():
    """Panel: horarios, MFA, desactivar, sesiones, acceso extraordinario."""
    if not requiere_login() or rol_actual() not in ("Soporte", "Superadmin", "Administrador", "Gerente"):
        return redirect("/soporte-login")
    msg = ""
    if request.method == "POST":
        acc = request.form.get("accion") or ""
        uid = request.form.get("usuario_id")
        try:
            uid = int(uid)
        except Exception:
            uid = 0
        u = Usuario.query.get(uid) if uid else None
        if acc == "desactivar" and u:
            desactivar_empleado(u.id, session.get("usuario"))
            msg = f"Usuario {u.usuario} desactivado y sesiones cerradas."
        elif acc == "activar" and u:
            u.activo = True
            db.session.commit()
            registrar_auditoria("Activar empleado", u.usuario)
            msg = f"Usuario {u.usuario} reactivado."
        elif acc == "revocar_sesiones" and u:
            revocar_sesiones_usuario(u.id)
            registrar_auditoria("Revocar sesiones", u.usuario)
            msg = f"Sesiones de {u.usuario} revocadas."
        elif acc == "horario" and u:
            u.hora_inicio = (request.form.get("hora_inicio") or "06:00")[:8]
            u.hora_fin = (request.form.get("hora_fin") or "20:00")[:8]
            u.dias_laborales = (request.form.get("dias") or "1,2,3,4,5")[:40]
            u.forzar_mfa = request.form.get("forzar_mfa") == "1"
            db.session.commit()
            registrar_auditoria("Config seguridad empleado", f"{u.usuario} horario {u.hora_inicio}-{u.hora_fin}")
            msg = "Horario / MFA actualizados."
        elif acc == "acceso_extra" and u:
            desde = (request.form.get("desde") or "").strip()[:30]
            hasta = (request.form.get("hasta") or "").strip()[:30]
            motivo = (request.form.get("motivo") or "").strip()[:300]
            db.session.add(AccesoExtraordinario(
                usuario_id=u.id,
                autorizado_por=session.get("usuario") or "",
                motivo=motivo,
                desde=desde,
                hasta=hasta,
                activo=True,
            ))
            db.session.commit()
            registrar_auditoria("Acceso extraordinario", f"{u.usuario} {desde}→{hasta} · {motivo}")
            msg = "Acceso extraordinario registrado."
        elif acc == "reset_mfa" and u:
            u.mfa_secret = ""
            u.mfa_habilitado = False
            db.session.commit()
            registrar_auditoria("Reset MFA", u.usuario)
            msg = f"MFA reiniciado para {u.usuario}."
    # listar empleados internos
    internos = Usuario.query.filter(
        Usuario.rol.in_(list(ROLES_INTERNOS))
    ).order_by(Usuario.rol, Usuario.usuario).all()
    filas = []
    for u in internos:
        estado = "Activo" if getattr(u, "activo", True) else "DESACTIVADO"
        mfa = "Sí" if getattr(u, "mfa_habilitado", False) else ("Forzado" if getattr(u, "forzar_mfa", False) else "No")
        filas.append(f"""
<tr>
  <td>{u.id}</td><td><b>{u.usuario}</b></td><td>{u.rol}</td><td>{estado}</td>
  <td>{getattr(u,'hora_inicio',None) or '06:00'}–{getattr(u,'hora_fin',None) or '20:00'}</td>
  <td>{mfa}</td><td>{getattr(u,'ultimo_acceso',None) or '—'}</td>
  <td>
    <form method="POST" style="display:inline" onsubmit="return confirm('¿Confirmar acción sensible?');">
      <input type="hidden" name="usuario_id" value="{u.id}">
      <input type="hidden" name="accion_sensible" value="1">
      <button name="accion" value="desactivar" type="submit">Desactivar</button>
      <button name="accion" value="activar" type="submit">Activar</button>
      <button name="accion" value="revocar_sesiones" type="submit">Cerrar sesiones</button>
      <button name="accion" value="reset_mfa" type="submit">Reset MFA</button>
    </form>
    <details style="margin-top:6px">
      <summary>Horario / extra</summary>
      <form method="POST">
        <input type="hidden" name="usuario_id" value="{u.id}">
        <input type="hidden" name="accion" value="horario">
        <input name="hora_inicio" value="{getattr(u,'hora_inicio',None) or '06:00'}" placeholder="06:00">
        <input name="hora_fin" value="{getattr(u,'hora_fin',None) or '20:00'}" placeholder="20:00">
        <input name="dias" value="{getattr(u,'dias_laborales',None) or '1,2,3,4,5'}" placeholder="1,2,3,4,5">
        <label><input type="checkbox" name="forzar_mfa" value="1" {"checked" if getattr(u,"forzar_mfa",False) else ""}> Forzar MFA</label>
        <button type="submit">Guardar</button>
      </form>
      <form method="POST" style="margin-top:6px">
        <input type="hidden" name="usuario_id" value="{u.id}">
        <input type="hidden" name="accion" value="acceso_extra">
        <input name="desde" placeholder="2026-08-16 20:00">
        <input name="hasta" placeholder="2026-08-16 23:00">
        <input name="motivo" placeholder="Motivo acceso extra">
        <button type="submit">Autorizar extra</button>
      </form>
    </details>
  </td>
</tr>""")
    sesiones = SesionEmpleado.query.filter_by(activa=True).order_by(SesionEmpleado.id.desc()).limit(30).all()
    ses_html = "".join(
        f"<tr><td>{s.usuario_id}</td><td>{(s.token or '')[:12]}…</td><td>{s.ip}</td><td>{s.creada}</td><td>{s.ultimo_ping}</td></tr>"
        for s in sesiones
    ) or "<tr><td colspan='5'>Sin sesiones activas</td></tr>"
    content = f"""
<header class="role-hero"><div>
  <h1>Seguridad de empleados</h1>
  <p>Usuarios individuales · roles · MFA · horario · sesiones · auditoría</p>
</div><a class="btn" href="/soporte_admin">Volver</a></header>
{"<div class='msg ok'>"+msg+"</div>" if msg else ""}
<section class="role-panel">
  <h2>Política</h2>
  <ul>
    <li>Sin cuentas compartidas: cada persona con su usuario.</li>
    <li>MFA obligatorio para Soporte, Administrador, Superadmin y Gerente.</li>
    <li>Fuera de horario laboral el acceso se bloquea (salvo autorización extraordinaria registrada).</li>
    <li>Al desactivar un empleado se cortan todas las sesiones.</li>
    <li>Acciones sensibles piden confirmación adicional.</li>
  </ul>
</section>
<section class="role-panel">
  <h2>Empleados internos</h2>
  <p class="mini-text">Al crear un usuario de empresa debe registrar su rostro (Registrar rostro). Cada ingreso exige validación biométrica + PIN. Los accesos quedan en Auditoría y en la Planilla Excel.</p>
  <div style="overflow:auto">
  <table class="data"><thead><tr>
    <th>ID</th><th>Usuario</th><th>Rol</th><th>Estado</th><th>Horario</th><th>MFA</th><th>Último acceso</th><th>Acciones</th>
  </tr></thead><tbody>{''.join(filas) or '<tr><td colspan="8">Sin empleados internos</td></tr>'}</tbody></table>
  </div>
</section>
<section class="role-panel">
  <h2>Sesiones activas</h2>
  <table class="data"><thead><tr><th>Usuario ID</th><th>Token</th><th>IP</th><th>Creada</th><th>Último ping</th></tr></thead>
  <tbody>{ses_html}</tbody></table>
</section>
"""
    return page("Seguridad empleados", shell_soporte(content))



