@app.route("/soporte/pqr/<int:id>", methods=["GET", "POST"])
def soporte_pqr_detalle(id):
    if not requiere_login() or rol_actual() != "Soporte":
        return redirect("/soporte-login")
    t = TicketPQR.query.get_or_404(id)
    mensaje = ""
    cerrado = (t.estado or "").upper() in ("CERRADA", "CERRADO", "RESUELTA")
    if request.method == "POST":
        # Bloqueo total si ya está cerrada/resuelta (solo consulta)
        if cerrado and not es_gerente_pqr():
            mensaje = "Ticket cerrado/resuelto: no se permiten más cambios. Solo consulta."
        else:
            nuevo = (request.form.get("estado") or t.estado).strip()
            resp = (request.form.get("respuesta") or "").strip()
            t.estado = nuevo
            if resp:
                # Acumular respuesta (no borrar la anterior)
                prev = (t.respuesta or "").strip()
                stamp = f"[{fecha_hoy()} {hora_actual()} · {session.get('usuario','soporte')}]"
                t.respuesta = (prev + "\n\n" + stamp + "\n" + resp).strip() if prev else (stamp + "\n" + resp)
                t.fecha_respuesta = fecha_hoy()
                if resp:
                    t.descripcion_cierre = resp  # solución visible en consulta pública
            if nuevo.upper() in ("CERRADA", "CERRADO", "RESUELTA"):
                t.cerrado_por = session.get("usuario", "")
                t.fecha_cierre = fecha_hoy()
                t.estado_cun = "CERRADO"
                if resp:
                    t.descripcion_cierre = resp
            try:
                db.session.commit()
                cerrado = (t.estado or "").upper() in ("CERRADA", "CERRADO", "RESUELTA")
                try:
                    registrar_historial_pqr(t.id, "RESPUESTA" if resp else "ESTADO", resp or f"Estado → {nuevo}", nuevo)
                    db.session.commit()
                except Exception as ex:
                    db.session.rollback()
                    print("historial pqr:", ex)
                cierra_caso = nuevo.upper() in ("CERRADA", "CERRADO", "RESUELTA")
                enviar_mail = (request.form.get("enviar_correo") or "") == "1" or cierra_caso
                mail_ok = False
                if resp and t.email and enviar_mail:
                    try:
                        # Al cerrar/resolver el caso se envía automáticamente el aviso
                        # estilo Tigo (link a la landing pública); en otros estados
                        # intermedios se manda el correo directo con la respuesta.
                        mail_ok = (
                            enviar_notificacion_pqr_estilo_tigo(t.email, t)
                            if cierra_caso else
                            enviar_correo_respuesta_pqr(t.email, t, resp)
                        )
                    except Exception as ex:
                        print("mail respuesta:", ex)
                if resp and t.email and enviar_mail:
                    mensaje = "Respuesta guardada. " + (
                        "Correo enviado al usuario (botón VER RESPUESTA)."
                        if mail_ok
                        else "No se pudo enviar el correo (configure RESEND_API_KEY en Railway o SOPORTE_PASSWORD en plan Pro)."
                    )
                else:
                    mensaje = "Respuesta y estado guardados correctamente."
            except Exception as ex:
                db.session.rollback()
                mensaje = f"Error al guardar: {ex}"
    try:
        hist = HistorialPQR.query.filter_by(ticket_id=t.id).order_by(HistorialPQR.id.desc()).limit(40).all()
    except Exception:
        hist = []
    htm = "".join(
        f"<li style='margin-bottom:8px'><b>{getattr(h,'fecha','')} {getattr(h,'hora','')}</b> · {getattr(h,'usuario','')}<br>"
        f"<span class='mini-text'>{getattr(h,'accion','')}</span><br>{(getattr(h,'detalle','') or '')[:500]}</li>"
        for h in hist
    )
    resp_html = (t.respuesta or "").replace("<", "&lt;").replace("\n", "<br>")
    form_block = ""
    if cerrado and not es_gerente_pqr():
        form_block = "<div class='msg' style='background:#fef3c7;color:#92400e;padding:12px;border-radius:10px'>Ticket <b>cerrado/resuelto</b>. Solo consulta. No se puede editar ni eliminar.</div>"
