# ── API Procsis Interno (activaciones / suspensión / cancelación) ─────────
def _procsis_auth_ok():
    token = (os.environ.get("PROCSIS_API_TOKEN") or "procsis-edutrack-token-cambiar").strip()
    auth = (request.headers.get("Authorization") or "").strip()
    if auth.lower().startswith("bearer "):
        return auth[7:].strip() == token
    return (request.headers.get("X-API-Token") or "").strip() == token


@app.route("/api/procsis/instituciones", methods=["GET"])
def api_procsis_list_inst():
    if not _procsis_auth_ok():
        return jsonify({"ok": False, "error": "No autorizado"}), 401
    rows = []
    for i in Institucion.query.order_by(Institucion.nombre.asc()).all():
        rows.append({
            "id": i.id,
            "codigo": i.codigo,
            "nombre": i.nombre,
            "sede": getattr(i, "sede", "") or "",
            "estado": i.estado,
            "plan": getattr(i, "plan", None) or getattr(i, "plan_contratado", "") or "",
            "nit": getattr(i, "nit", "") or "",
        })
    return jsonify({"ok": True, "instituciones": rows})


@app.route("/api/procsis/instituciones", methods=["POST"])
def api_procsis_crear_inst():
    """Alta/activación desde Procsis Interno."""
    if not _procsis_auth_ok():
        return jsonify({"ok": False, "error": "No autorizado"}), 401
    data = request.get_json(silent=True) or {}
    nombre = (data.get("nombre") or "").strip()
    if not nombre:
        return jsonify({"ok": False, "error": "nombre requerido"}), 400
    codigo = (data.get("codigo") or "").strip().upper()
    if not codigo:
        # generar código simple
        import random
        codigo = f"LW{random.randint(100000, 999999)}"
        while Institucion.query.filter_by(codigo=codigo).first():
            codigo = f"LW{random.randint(100000, 999999)}"
    existing = Institucion.query.filter_by(codigo=codigo).first()
    if existing:
        existing.estado = (data.get("estado") or "ACTIVA").upper()
        if data.get("plan"):
            if hasattr(existing, "plan"):
                existing.plan = data.get("plan")
            if hasattr(existing, "plan_contratado"):
                existing.plan_contratado = data.get("plan")
        if data.get("fecha_fin") and hasattr(existing, "fecha_vencimiento"):
            existing.fecha_vencimiento = data.get("fecha_fin")
        if data.get("fecha_inicio") and hasattr(existing, "fecha_inicio"):
            existing.fecha_inicio = data.get("fecha_inicio")
        db.session.commit()
        return jsonify({"ok": True, "id": existing.id, "codigo": existing.codigo, "accion": "actualizada"})
    inst = Institucion(
        codigo=codigo,
        nombre=nombre,
        estado=(data.get("estado") or "ACTIVA").upper(),
    )
    if hasattr(Institucion, "sede"):
        inst.sede = (data.get("sede") or "Principal")[:80]
    if hasattr(Institucion, "nit"):
        inst.nit = (data.get("nit") or "")[:40]
    if hasattr(Institucion, "plan"):
        inst.plan = (data.get("plan") or "Basico")[:40]
    if hasattr(Institucion, "plan_contratado"):
        inst.plan_contratado = (data.get("plan") or "Basico")[:40]
    if hasattr(Institucion, "fecha_inicio") and data.get("fecha_inicio"):
        inst.fecha_inicio = data.get("fecha_inicio")
    if hasattr(Institucion, "fecha_vencimiento") and data.get("fecha_fin"):
        inst.fecha_vencimiento = data.get("fecha_fin")
    db.session.add(inst)
    db.session.flush()
    # logo opcional (base64 data URL o raw)
    logo_b64 = data.get("logo_base64") or data.get("logo")
    if logo_b64:
        try:
            import base64, re
            raw = logo_b64
            if "," in raw and raw.strip().startswith("data:"):
                raw = raw.split(",", 1)[1]
            img_bytes = base64.b64decode(raw)
            # guardar en config o campo logo de institucion
            cfg = Configuracion.query.filter_by(institucion_id=inst.id).first()
            if not cfg:
                cfg = Configuracion(institucion_id=inst.id)
                db.session.add(cfg)
            # path
            logo_dir = os.path.join(app.root_path, "static", "uploads", "logos")
            os.makedirs(logo_dir, exist_ok=True)
            fname = f"inst_{inst.id}.png"
            fpath = os.path.join(logo_dir, fname)
            with open(fpath, "wb") as f:
                f.write(img_bytes)
            rel = f"/static/uploads/logos/{fname}"
            if hasattr(inst, "logo"):
                inst.logo = rel
            if hasattr(cfg, "logo"):
                cfg.logo = rel
            if hasattr(cfg, "logo_url"):
                cfg.logo_url = rel
        except Exception as _logo_err:
            pass
    # admin por defecto del colegio
    admin_user = f"admin_{codigo.lower()}"
    if not Usuario.query.filter_by(usuario=admin_user).first():
        u = Usuario(
            usuario=admin_user,
            password=crear_hash("Colegio2026*"),
            rol="Administrador",
            institucion_id=inst.id,
            password_temporal=True,
        )
        db.session.add(u)
    db.session.commit()
    return jsonify({
        "ok": True,
        "id": inst.id,
        "codigo": inst.codigo,
        "admin_usuario": admin_user,
        "admin_password_temporal": "Colegio2026*",
        "accion": "creada",
    }), 201


@app.route("/api/procsis/instituciones/<codigo>/estado", methods=["PATCH"])
def api_procsis_estado_inst(codigo):
    if not _procsis_auth_ok():
        return jsonify({"ok": False, "error": "No autorizado"}), 401
    data = request.get_json(silent=True) or {}
    estado = (data.get("estado") or "").strip().upper()
    if estado not in ("ACTIVA", "SUSPENDIDA", "CANCELADA", "INACTIVA"):
        return jsonify({"ok": False, "error": "estado inválido"}), 400
    inst = Institucion.query.filter_by(codigo=codigo).first()
    if not inst and str(codigo).isdigit():
        inst = Institucion.query.get(int(codigo))
    if not inst:
        return jsonify({"ok": False, "error": "Institución no encontrada"}), 404
    inst.estado = estado
    db.session.commit()
    try:
        registrar_auditoria("API Procsis estado", f"{inst.codigo} → {estado} · {data.get('motivo','')}")
    except Exception:
        pass
    return jsonify({"ok": True, "codigo": inst.codigo, "estado": inst.estado})




@app.route("/api/procsis/instituciones/<codigo>", methods=["DELETE"])
def api_procsis_eliminar_inst(codigo):
    """Borrado definitivo solicitado desde Procsis Interno."""
    if not _procsis_auth_ok():
        return jsonify({"ok": False, "error": "No autorizado"}), 401
    inst = Institucion.query.filter_by(codigo=codigo).first()
    if not inst and str(codigo).isdigit():
        inst = Institucion.query.get(int(codigo))
    if not inst:
        return jsonify({"ok": False, "error": "Institución no encontrada"}), 404
    cod = inst.codigo
    nombre = inst.nombre or ""
    iid = inst.id
    try:
        for model_name in [
            "Configuracion", "FeatureFlag", "SedeInstitucion", "PreMatricula",
            "TicketPQR", "AsignacionDocente",
        ]:
            try:
                model = globals().get(model_name)
                if model is not None and hasattr(model, "institucion_id"):
                    model.query.filter_by(institucion_id=iid).delete(synchronize_session=False)
            except Exception:
                db.session.rollback()
        for u in Usuario.query.filter(Usuario.institucion_id == iid).all():
            if (u.rol or "") == "Soporte":
                u.institucion_id = None
            else:
                try:
                    AsignacionDocente.query.filter_by(usuario_id=u.id).delete(synchronize_session=False)
                except Exception:
                    pass
                db.session.delete(u)
        for e in Estudiante.query.filter_by(institucion_id=iid).all():
            try:
                IngresoPorteria.query.filter_by(estudiante_id=e.id).delete(synchronize_session=False)
            except Exception:
                pass
            try:
                AsistenciaClase.query.filter_by(estudiante_id=e.id).delete(synchronize_session=False)
            except Exception:
                pass
            db.session.delete(e)
        db.session.delete(inst)
        db.session.commit()
        try:
            registrar_auditoria("API Procsis eliminar", f"{cod} · {nombre}")
        except Exception:
            pass
        return jsonify({"ok": True, "codigo": cod, "nombre": nombre, "eliminada": True})
    except Exception as ex:
        db.session.rollback()
        return jsonify({"ok": False, "error": str(ex)[:200]}), 500


@app.route("/api/procsis/instituciones/<codigo>/licencia", methods=["GET"])
def api_procsis_licencia(codigo):
    if not _procsis_auth_ok():
        return jsonify({"ok": False, "error": "No autorizado"}), 401
    inst = Institucion.query.filter_by(codigo=codigo).first()
    if not inst and str(codigo).isdigit():
        inst = Institucion.query.get(int(codigo))
    if not inst:
        return jsonify({"ok": False, "error": "No encontrada"}), 404
    try:
        lic = estado_licencia(inst)
    except Exception:
        lic = {"estado": inst.estado}
    return jsonify({"ok": True, "codigo": inst.codigo, "nombre": inst.nombre, **(lic if isinstance(lic, dict) else {"info": str(lic)})})





@app.route("/api/procsis/plataforma", methods=["GET", "POST"])
def api_procsis_plataforma():
    """Marketing Procsis actualiza novedades/FAQ del login EduTrack."""
    if not _procsis_auth_ok():
        return jsonify({"ok": False, "error": "No autorizado"}), 401
    p = plataforma()
    if request.method == "GET":
        return jsonify({
            "ok": True,
            "version": getattr(p, "version_sistema", None) or getattr(p, "version", "") or "",
            "novedades": getattr(p, "novedades", "") or "",
            "faq": getattr(p, "faq", "") or "",
            "hero_titulo": getattr(p, "hero_titulo", "") or "",
            "hero_texto": getattr(p, "hero_texto", "") or getattr(p, "panel_derecho_texto", "") or "",
            "mantenimiento": getattr(p, "mensaje_mantenimiento", "") or "",
        })
    data = request.get_json(silent=True) or {}
    mapping = {
        "version": ["version_sistema", "version"],
        "novedades": ["novedades"],
        "faq": ["faq"],
        "hero_titulo": ["hero_titulo"],
        "hero_texto": ["hero_texto", "panel_derecho_texto"],
        "mantenimiento": ["mensaje_mantenimiento"],
    }
    for key, attrs in mapping.items():
        if key in data and data[key] is not None:
            val = data[key]
            for attr in attrs:
                if hasattr(p, attr):
                    setattr(p, attr, val)
                    break
    db.session.commit()
    return jsonify({"ok": True, "mensaje": "Plataforma actualizada"})


@app.route("/api/procsis/instituciones/<codigo>/detalle", methods=["GET", "PATCH"])
def api_procsis_inst_detalle(codigo):
    if not _procsis_auth_ok():
        return jsonify({"ok": False, "error": "No autorizado"}), 401
    inst = Institucion.query.filter_by(codigo=codigo).first()
    if not inst and str(codigo).isdigit():
        inst = Institucion.query.get(int(codigo))
    if not inst:
        return jsonify({"ok": False, "error": "No encontrada"}), 404
    if request.method == "GET":
        return jsonify({
            "ok": True,
            "id": inst.id,
            "codigo": inst.codigo,
            "nombre": inst.nombre,
            "sede": getattr(inst, "sede", "") or "",
            "nit": getattr(inst, "nit", "") or "",
            "estado": inst.estado,
            "plan": getattr(inst, "plan", None) or getattr(inst, "plan_contratado", "") or "",
            "logo": getattr(inst, "logo", "") or "",
        })
    data = request.get_json(silent=True) or {}
    for field in ("nombre", "sede", "nit", "estado"):
        if field in data and data[field] is not None and hasattr(inst, field):
            setattr(inst, field, data[field])
    if data.get("plan"):
        if hasattr(inst, "plan"):
            inst.plan = data["plan"]
        if hasattr(inst, "plan_contratado"):
            inst.plan_contratado = data["plan"]
    db.session.commit()
    return jsonify({"ok": True, "codigo": inst.codigo})



