@app.route("/docente/actividades/<int:aid>", methods=["GET", "POST"])
def docente_actividad_detalle(aid):
    if not requiere_login():
        return redirect("/login")
    a = ActividadAsignada.query.get_or_404(aid)
    msg = ""
    if request.method == "POST":
        eid = int(request.form.get("entrega_id") or 0)
        ent = EntregaEstudiante.query.get(eid)
        if ent and ent.actividad_id == a.id:
            try:
                nota = float((request.form.get("nota") or "").replace(",", "."))
            except ValueError:
                nota = None
            ent.nota = nota
            ent.observaciones_docente = (request.form.get("obs") or "").strip()[:2000]
            ent.estado = "CALIFICADA" if nota is not None else "REVISADA"
            ent.calificado_por = session.get("usuario") or ""
            ent.calificado_en = f"{fecha_hoy()} {hora_actual()}"
            # Reflejo opcional en planilla (NotaRegistro) si hay valor
            if nota is not None:
                try:
                    nr = NotaRegistro(
                        institucion_id=ent.institucion_id,
                        estudiante_id=ent.estudiante_id,
                        asignatura=a.asignatura or "",
                        grado=a.grado or "",
                        periodo=a.periodo or "",
                        valor=nota,
                        logro=(a.titulo or "")[:255],
                        observacion=f"Entrega actividad #{a.id}",
                        docente=session.get("usuario") or "",
                        actualizado=ent.calificado_en,
                    )
                    db.session.add(nr)
                except Exception:
                    pass
            db.session.commit()
            msg = "Calificación guardada. También puede ajustarla en la planilla de notas."
    entregas = EntregaEstudiante.query.filter_by(actividad_id=a.id).order_by(EntregaEstudiante.id.desc()).all()
    bloques = ""
    for ent in entregas:
        est = Estudiante.query.get(ent.estudiante_id)
        nom = f"{est.nombre or ''} {est.apellido or ''}".strip() if est else f"ID {ent.estudiante_id}"
        files = EntregaArchivo.query.filter_by(entrega_id=ent.id).all()
        fl = "".join(f'<li><a href="{f.ruta}" target="_blank">{f.nombre_original}</a></li>' for f in files)
        bloques += f"""
        <div style="border:1px solid #e2e8f0;border-radius:12px;padding:14px;margin-bottom:12px;background:#fff">
          <b>{nom}</b> · {ent.fecha} {ent.hora} · <span style="color:#0B2D57">{ent.estado}</span>
          <div style="font-size:13px;color:#475569;margin:6px 0">Envia: {ent.enviado_por or '—'} · Integrantes: {ent.integrantes or '—'}</div>
          <div style="font-size:13px">{ent.comentario or ''}</div>
          <ul>{fl or '<li>Sin archivos</li>'}</ul>
          <form method="POST" style="display:flex;flex-wrap:wrap;gap:8px;align-items:end;margin-top:8px">
            <input type="hidden" name="entrega_id" value="{ent.id}">
            <div><label>Nota</label><input name="nota" type="number" step="0.1" min="0" max="5" value="{ent.nota if ent.nota is not None else ''}" style="width:90px"></div>
            <div style="flex:1"><label>Obs. docente</label><input name="obs" value="{(ent.observaciones_docente or '')}"></div>
            <button type="submit" class="btn" style="padding:10px 14px">Guardar nota</button>
            <a class="btn" style="background:#15803d;padding:10px 14px" href="/planilla?grado={a.grado}&materia={a.asignatura}">Planilla</a>
          </form>
        </div>"""
    body = f"""
<div style="max-width:800px;margin:16px auto;padding:12px;font-family:Segoe UI,sans-serif">
  <a href="/docente/actividades">← Actividades</a>
  <h1 style="color:#0B2D57">{a.titulo}</h1>
  <p style="color:#64748b">{a.asignatura} · Grado {a.grado} · {a.docente_nombre}</p>
  {"<div class='msg ok'>"+msg+"</div>" if msg else ""}
  <h2 style="font-size:17px;color:#0B2D57">Entregas recibidas</h2>
  {bloques or "<p>Aún no hay entregas.</p>"}
</div>
"""
    return page("Entregas actividad", body)


