def _rol_coord_reportes_ok():
    if not requiere_login():
        return False
    return rol_actual() in (
        "Coordinador", "Coordinación", "Rector", "Rectoría",
        "Secretaria", "Secretaría", "Administrador", "Superadmin", "Soporte",
    )


def _nav_coord_reportes(activo=""):
    items = [
        ("info", "Información General", "/coordinacion/reportes"),
        ("mejores", "Mejores Estudiantes", "/coordinacion/reportes/mejores"),
        ("honor", "Cuadro de Honor", "/coordinacion/reportes/honor"),
        ("salones", "Rendimiento Académico por Salones", "/coordinacion/reportes/salones"),
        ("docentes", "Rendimiento Académico por Docentes", "/coordinacion/reportes/docentes"),
        ("doc_cons", "Rendimiento Docentes Consolidado", "/coordinacion/reportes/docentes-consolidado"),
        ("asig_salon", "Rendimiento Asignatura por Salón", "/coordinacion/reportes/asignatura-salon"),
        ("asig_grado", "Rendimiento Asignatura por Grado", "/coordinacion/reportes/asignatura-grado"),
        ("areas", "Rendimiento por Áreas", "/coordinacion/reportes/areas"),
        ("niveles", "Rendimiento por Niveles", "/coordinacion/reportes/niveles"),
    ]
    html = ""
    for key, label, href in items:
        on = " is-on" if activo == key else ""
        html += f'<a class="cr-nav{on}" href="{href}">{label}</a>'
    return html


