def _nota_final_estudiante(est_id, iid, periodo):
    """Promedio simple de notas del estudiante en el periodo."""
    q = NotaRegistro.query.filter_by(estudiante_id=est_id)
    if iid:
        q = q.filter_by(institucion_id=iid)
    if periodo:
        q = q.filter(
            or_(
                NotaRegistro.periodo == periodo,
                NotaRegistro.periodo == periodo.replace("Periodo ", ""),
                NotaRegistro.periodo.ilike(f"%{periodo}%"),
            )
        )
    vals = [float(r.valor) for r in q.all() if r.valor is not None]
    if not vals:
        return None
    return sum(vals) / len(vals)


def _areas_perdidas_estudiante(est_id, iid, periodo, umbral=3.0):
    """Cuántas asignaturas tiene por debajo del umbral en el periodo."""
    q = NotaRegistro.query.filter_by(estudiante_id=est_id)
    if iid:
        q = q.filter_by(institucion_id=iid)
    if periodo:
        q = q.filter(
            or_(
                NotaRegistro.periodo == periodo,
                NotaRegistro.periodo == periodo.replace("Periodo ", ""),
                NotaRegistro.periodo.ilike(f"%{periodo}%"),
            )
        )
    por_asig = {}
    for r in q.all():
        if r.valor is None:
            continue
        a = (r.asignatura or "").strip() or "—"
        if a.lower() == "general":
            continue
        por_asig.setdefault(a, []).append(float(r.valor))
    perdidas = 0
    for a, vs in por_asig.items():
        if sum(vs) / len(vs) < umbral:
            perdidas += 1
    return perdidas, len(por_asig)


